/* =========================================================
   NORMALIZE DATA
========================================================= */

products =
    products.map(function(product){

        return {

            id:
                product.id ??
                createId(),

            name:
                String(
                    product.name ??
                    ""
                ),

            category:
                product.category ??
                "Autre",

            unit:
                product.unit ??
                "pièce",

            stock:
                Number(
                    product.stock ??
                    0
                ),

            minStock:
                Number(
                    product.minStock ??
                    0
                ),

            price:
                Number(
                    product.price ??
                    0
                ),

            // Preserve the last known purchase VAT across page reloads.
            // 0% is a valid VAT rate, so we must keep a separate "known" flag.
            lastPurchaseTVA:
                Number(
                    product.lastPurchaseTVA ??
                    0
                ),

            lastPurchaseTVAKnown:
                product.lastPurchaseTVAKnown === true,

            // Learned supplier invoice designations linked to this stock article.
            invoiceAliases:
                Array.isArray(product.invoiceAliases)
                ? product.invoiceAliases
                    .map(function(alias){
                        if(typeof alias === "string"){
                            return {
                                supplierId: null,
                                designation: alias,
                                normalized: normalizeText(alias),
                                updatedAt: new Date().toISOString()
                            };
                        }
                        return {
                            supplierId: alias?.supplierId ?? null,
                            designation: String(alias?.designation || alias?.name || ""),
                            normalized: String(alias?.normalized || normalizeText(alias?.designation || alias?.name || "")),
                            updatedAt: alias?.updatedAt || new Date().toISOString()
                        };
                    })
                    .filter(function(alias){ return Boolean(alias.normalized); })
                : [],

            createdAt:
                product.createdAt ??
                new Date().toISOString()

        };

    });


movements =
    movements.map(function(movement){

        return {

            ...movement,

            quantity:
                Number(
                    movement.quantity ??
                    0
                )

        };

    });


suppliers =
    suppliers.map(function(supplier){

        const paymentTerm=ppSupplierLegalTermPP(supplier);

        return {

            id:
                supplier.id ??
                createId(),

            name:
                String(
                    supplier.name ??
                    ""
                ),

            phone:
                String(
                    supplier.phone ??
                    ""
                ),

            email:
                String(
                    supplier.email ??
                    ""
                ),

            ice:
                String(
                    supplier.ice ??
                    ""
                ),

            if:
                String(
                    supplier.if ??
                    supplier.ifNumber ??
                    ""
                ),

            address:
                String(
                    supplier.address ??
                    ""
                ),

            purchases:
                Number(
                    supplier.purchases ??
                    0
                ),

            paid:
                Number(
                    supplier.paid ??
                    0
                ),

            paymentTermType:
                paymentTerm.type,

            paymentTermDays:
                paymentTerm.days,

            paymentTermNote:
                String(
                    supplier.paymentTermNote ??
                    ""
                )

        };

    });


invoices =
    invoices.map(function(invoice){

        const legalTerm=ppInvoiceLegalTermPP(invoice);

        return {

            ...invoice,

            totalHT:
                Number(
                    invoice.totalHT ??
                    0
                ),

            tva:
                Number(
                    invoice.tva ??
                    0
                ),

            totalTTC:
                Number(
                    invoice.totalTTC ??
                    0
                ),

            paid:
                Number(
                    invoice.paid ??
                    0
                ),

            due:
                Number(
                    invoice.due ??
                    Math.max(Number(invoice.totalTTC||0)-Number(invoice.paid||0),0)
                ),

            paymentTermType:
                legalTerm.type,

            paymentTermDays:
                legalTerm.days,

            dueDate:
                String(
                    invoice.dueDate ||
                    ppAddCalendarDaysPP(invoice.date,legalTerm.days) ||
                    ""
                ).slice(0,10),

            lines:
                Array.isArray(
                    invoice.lines
                )
                ?
                invoice.lines
                :
                []

        };

    });


