/* =========================================================
   STORAGE
========================================================= */

function loadStorage(
    key,
    fallback
){

    try{

        const raw =
            localStorage.getItem(
                key
            );


        if(!raw){

            return fallback;

        }


        return JSON.parse(
            raw
        ) ?? fallback;

    }
    catch(error){

        console.error(
            error
        );

        return fallback;

    }

}


function saveData(){

    localStorage.setItem(
        STORAGE_KEYS.products,
        JSON.stringify(
            products
        )
    );


    localStorage.setItem(
        STORAGE_KEYS.movements,
        JSON.stringify(
            movements
        )
    );


    localStorage.setItem(
        STORAGE_KEYS.suppliers,
        JSON.stringify(
            suppliers
        )
    );


    localStorage.setItem(
        STORAGE_KEYS.invoices,
        JSON.stringify(
            invoices
        )
    );

}


/* =========================================================
   NAVIGATION
========================================================= */

function initializeNavigation(){

    const navItems =
        document.querySelectorAll(
            ".nav-item"
        );


    navItems.forEach(function(item){

        item.addEventListener(
            "click",
            function(){

                const page =
                    item.dataset.page;


                navItems.forEach(function(nav){

                    nav.classList.remove(
                        "active"
                    );

                });


                item.classList.add(
                    "active"
                );


                document
                    .querySelectorAll(
                        ".page"
                    )
                    .forEach(function(pageElement){

                        pageElement.classList.remove(
                            "active-page"
                        );

                    });


                document
                    .getElementById(
                        page + "Page"
                    )
                    ?.classList.add(
                        "active-page"
                    );


                updatePageTitle(
                    page
                );

            }
        );

    });

}


