/* =========================================================
   PRODUCTS
========================================================= */

function openProductModal(id = null){
    editingProductId = id ? Number(id) : null;
    const form = document.getElementById("productForm");
    if(form) form.reset();
    const title = document.querySelector("#productModal .modal-header h2");
    if(editingProductId){
        const product = products.find(p => Number(p.id) === editingProductId);
        if(!product) return;
        if(title) title.textContent = "Modifier un produit";
        setValue("productName", product.name);
        setValue("productCategory", product.category);
        setValue("productUnit", product.unit);
        setValue("productStock", product.stock);
        setValue("productMinStock", product.minStock);
        setValue("productPrice", product.price);
    } else {
        if(title) title.textContent = "Ajouter un produit";
        setValue("productStock", 0);
        setValue("productMinStock", 0);
        setValue("productPrice", 0);
    }
    openModal("productModal");
}


function addProduct(){
    const name = getValue("productName").trim();
    if(!name){ alert("Veuillez saisir le nom du produit."); return; }
    const duplicate = products.find(p => normalizeText(p.name) === normalizeText(name) && Number(p.id) !== Number(editingProductId));
    if(duplicate){ alert("Ce produit existe déjà."); return; }
    const data = {
        name,
        category:getValue("productCategory") || "Autre",
        unit:getValue("productUnit") || "pièce",
        stock:parseNumber(getValue("productStock")),
        minStock:parseNumber(getValue("productMinStock")),
        price:parseNumber(getValue("productPrice"))
    };
    if(editingProductId){
        const product=products.find(p=>Number(p.id)===Number(editingProductId));
        if(!product) return;
        Object.assign(product,data);
    } else {
        products.push({id:createId(),...data,createdAt:new Date().toISOString()});
    }
    editingProductId=null;
    saveData(); closeModal("productModal"); renderAll();
}


function renderProducts(){
    const table=document.getElementById("productsTable"); if(!table) return;
    const search=normalizeText(getValue("searchInput")); const category=getValue("categoryFilter");
    const filtered=products.filter(p=>normalizeText(p.name).includes(search)&&(!category||p.category===category));
    if(!filtered.length){ table.innerHTML='<tr><td colspan="7" class="empty">Aucun produit enregistré.</td></tr>'; return; }
    table.innerHTML=filtered.map(product=>{
        const stock=Number(product.stock||0);
        const value=stock*Number(product.price);
        const min=Number(product.minStock||0);
        const rupture=stock<=0;
        const low=!rupture && min>0 && stock<=min;
        const statusClass=rupture?'danger':(low?'warning':'success');
        const statusLabel=rupture?'Rupture':(low?'Stock faible':'Normal');
        return `<tr><td><strong>${escapeHTML(product.name)}</strong></td><td>${escapeHTML(product.category)}</td><td>${formatNumber(product.stock)} ${escapeHTML(product.unit)}</td><td>${formatMoney(product.price)}</td><td>${formatMoney(value)}</td><td><span class="status ${statusClass}">${statusLabel}</span></td><td><div class="action-buttons"><button class="btn small view" onclick="viewProduct(${product.id})" title="Voir">👁️</button><button class="btn small edit" onclick="openProductModal(${product.id})" title="Modifier">✏️</button><button class="btn small print" onclick="printProduct(${product.id})" title="Imprimer">🖨️</button><button class="btn small danger" onclick="deleteProduct(${product.id})" title="Supprimer">🗑️</button></div></td></tr>`;
    }).join("");
}


function deleteProduct(id){

    if(
        !confirm(
            "Voulez-vous supprimer ce produit ?"
        )
    ){

        return;

    }


    products =
        products.filter(function(product){

            return Number(
                product.id
            )
            !==
            Number(
                id
            );

        });


    saveData();

    renderAll();

}



function viewProduct(id){
    const p=products.find(x=>Number(x.id)===Number(id)); if(!p) return;
    showDetailsModal("Produit", [["Nom",p.name],["Catégorie",p.category],["Unité",p.unit],["Stock",formatNumber(p.stock)+" "+p.unit],["Stock minimum",formatNumber(p.minStock)+" "+p.unit],["Prix moyen",formatMoney(p.price)],["Valeur",formatMoney(Number(p.stock)*Number(p.price))]], ()=>printProduct(id));
}
function printProduct(id){
    const p=products.find(x=>Number(x.id)===Number(id)); if(!p) return;
    printDocument("Fiche produit - "+p.name, `<h2>Fiche produit</h2>${detailRowsHTML([["Produit",p.name],["Catégorie",p.category],["Unité",p.unit],["Stock",formatNumber(p.stock)+" "+p.unit],["Stock minimum",formatNumber(p.minStock)+" "+p.unit],["Prix moyen",formatMoney(p.price)],["Valeur stock",formatMoney(Number(p.stock)*Number(p.price))]])}`);
}

/* =========================================================
   STOCK MOVEMENTS
========================================================= */

function openMovementModal(type, id = null){
    if(!products.length){ alert("Ajoutez d'abord un produit."); return; }
    editingMovementId=id?Number(id):null;
    const form=document.getElementById("movementForm"); if(form) form.reset();
    const select=document.getElementById("movementProduct");
    if(select) select.innerHTML='<option value="">Sélectionner un produit</option>'+products.map(p=>`<option value="${p.id}">${escapeHTML(p.name)} — ${formatNumber(p.stock)} ${escapeHTML(p.unit)}</option>`).join('');
    if(editingMovementId){
        const m=movements.find(x=>Number(x.id)===editingMovementId); if(!m) return;
        setValue("movementType",m.type); setValue("movementDate",String(m.date||"").slice(0,10)); setValue("movementProduct",m.productId); setValue("movementQuantity",m.quantity); setValue("movementReason",m.reason); setValue("movementNote",m.note||"");
        setText("movementTitle","Modifier le mouvement");
    } else { setValue("movementType",type); setValue("movementDate",""); setText("movementTitle",type==="entry"?"➕ Entrée Stock":"➖ Sortie Stock"); }
    openModal("movementModal");
}


function saveMovement(){
    if(!ppCan('stock','edit')){
        alert("Accès non autorisé.");
        return;
    }

    const type = getValue("movementType");
    const movementDate = getValue("movementDate");
    const productId = Number(getValue("movementProduct"));
    const quantity = parseNumber(getValue("movementQuantity"));
    const product = products.find(p=>Number(p.id)===productId);

    if(!movementDate){
        alert("Veuillez sélectionner la date du mouvement.");
        document.getElementById("movementDate")?.focus();
        return;
    }

    if(!product){
        alert("Veuillez sélectionner un produit.");
        return;
    }

    if(quantity<=0){
        alert("Quantité invalide.");
        return;
    }

    const editId = editingMovementId ? Number(editingMovementId) : null;
    const oldMovement = editId
        ? movements.find(m=>Number(m.id)===editId)
        : null;
    const before = oldMovement ? ppAuditSnapshot(oldMovement) : null;

    // Annuler l'impact de l'ancienne version avant modification.
    if(oldMovement){
        const oldProduct = products.find(
            p=>Number(p.id)===Number(oldMovement.productId)
        );
        if(oldProduct){
            oldProduct.stock +=
                oldMovement.type==="entry"
                    ? -Number(oldMovement.quantity||0)
                    : Number(oldMovement.quantity||0);
        }
    }

    // Si la nouvelle sortie est impossible, restaurer l'ancienne opération.
    if(type==="exit" && Number(product.stock)<quantity){
        if(oldMovement){
            const oldProduct = products.find(
                p=>Number(p.id)===Number(oldMovement.productId)
            );
            if(oldProduct){
                oldProduct.stock +=
                    oldMovement.type==="entry"
                        ? Number(oldMovement.quantity||0)
                        : -Number(oldMovement.quantity||0);
            }
        }
        alert("Stock insuffisant.");
        return;
    }

    product.stock += type==="entry" ? quantity : -quantity;

    const operationId = editId || createId();
    const record = {
        id: operationId,
        // Noon avoids timezone shifts while keeping the user-selected calendar date.
        date: movementDate + "T12:00:00",
        productId: product.id,
        productName: product.name,
        type,
        quantity,
        unit: product.unit,
        reason: getValue("movementReason"),
        note: getValue("movementNote").trim()
    };

    if(editId){
        const i = movements.findIndex(m=>Number(m.id)===editId);
        movements[i] = record;
    }else{
        movements.unshift(record);
    }

    const labelType = type==="entry" ? "Entrée Stock" : "Sortie Stock";
    const sign = type==="entry" ? "+" : "-";
    const label = `${labelType} — ${product.name} — ${sign}${formatNumber(quantity)} ${product.unit||""}`;

    // Chaque mouvement a son propre entityId = movement.id.
    // Les modifications du même mouvement deviennent Version 2, 3...
    ppWriteAudit(
        "stock",
        String(operationId),
        before ? "update" : "create",
        before,
        ppAuditSnapshot(record),
        label
    );

    editingMovementId = null;
    saveData();
    closeModal("movementModal");
    renderAll();
}


function renderMovements(){
    const table=document.getElementById("movementsTable"); if(!table) return;
    if(!movements.length){table.innerHTML='<tr><td colspan="6" class="empty">Aucun mouvement enregistré.</td></tr>';return;}
    table.innerHTML=movements.map(m=>`<tr><td>${formatDate(m.date)}</td><td>${escapeHTML(m.productName)}</td><td><span class="status ${m.type==='entry'?'success':'danger'}">${m.type==='entry'?'Entrée':'Sortie'}</span></td><td>${formatNumber(m.quantity)} ${escapeHTML(m.unit||'')}</td><td>${escapeHTML(m.reason)}</td><td><div class="action-buttons"><button class="btn small view" onclick="viewMovement(${m.id})">👁️</button><button class="btn small edit" onclick="openMovementModal('${m.type}',${m.id})">✏️</button><button class="btn small print" onclick="printMovement(${m.id})">🖨️</button><button class="btn small danger" onclick="deleteMovement(${m.id})">🗑️</button></div></td></tr>`).join('');
}



function viewMovement(id){ const m=movements.find(x=>Number(x.id)===Number(id)); if(!m)return; showDetailsModal("Mouvement de stock",[["Date",formatDate(m.date)],["Produit",m.productName],["Type",m.type==='entry'?'Entrée':'Sortie'],["Quantité",formatNumber(m.quantity)+' '+(m.unit||'')],["Motif",m.reason],["Note",m.note||'-']],()=>printMovement(id)); }
function printMovement(id){ const m=movements.find(x=>Number(x.id)===Number(id)); if(!m)return; printDocument("Mouvement de stock",`<h2>Mouvement de stock</h2>${detailRowsHTML([["Date",formatDate(m.date)],["Produit",m.productName],["Type",m.type==='entry'?'Entrée':'Sortie'],["Quantité",formatNumber(m.quantity)+' '+(m.unit||'')],["Motif",m.reason],["Note",m.note||'-']])}`); }
function deleteMovement(id){
    if(!ppCan('stock','delete')){
        alert("Accès non autorisé.");
        return;
    }

    const m = movements.find(x=>Number(x.id)===Number(id));
    if(!m)return;

    if(!confirm("Supprimer ce mouvement ? Le stock sera corrigé automatiquement."))return;

    const before = ppAuditSnapshot(m);
    const p = products.find(x=>Number(x.id)===Number(m.productId));

    if(p){
        p.stock += m.type==="entry"
            ? -Number(m.quantity||0)
            : Number(m.quantity||0);
    }

    movements = movements.filter(x=>Number(x.id)!==Number(id));

    const labelType = m.type==="entry" ? "Entrée Stock" : "Sortie Stock";
    const label = `${labelType} — ${m.productName||""} — ${formatNumber(Number(m.quantity||0))} ${m.unit||""}`;

    ppWriteAudit(
        "stock",
        String(m.id),
        "delete",
        before,
        null,
        label
    );

    saveData();
    renderAll();
}

/* =========================================================
   SUPPLIERS
========================================================= */

function ppSupplierLegalTermPP(supplier={}){
    const rawType=String(supplier.paymentTermType||'');
    if(rawType==='exception'||Number(supplier.paymentTermDays)===180)return {type:'exception',days:180};
    if(rawType==='agreed'||Number(supplier.paymentTermDays)===120)return {type:'agreed',days:120};
    return {type:'default',days:60};
}
function ppSupplierTermLabelPP(supplier){
    const term=ppSupplierLegalTermPP(supplier);
    if(term.type==='exception')return '180 jours — Dérogation sectorielle';
    if(term.type==='agreed')return '120 jours — Délai convenu';
    return '60 jours — Délai légal';
}
function ppNormalizeSupplierPaymentTermPP(supplier={}){
    const term=ppSupplierLegalTermPP(supplier);
    return {...supplier,paymentTermType:term.type,paymentTermDays:term.days,paymentTermNote:String(supplier.paymentTermNote||'')};
}
function ppEnsureSupplierPaymentTermFieldsPP(){
    if(document.getElementById('supplierPaymentTermType'))return;
    const form=document.getElementById('supplierForm'),actions=form?.querySelector('.modal-actions');if(!form||!actions)return;
    const box=document.createElement('div');box.id='ppSupplierPaymentTermBox';box.style.cssText='margin:14px 0;padding:14px;border:1px solid #d0d5dd;border-radius:12px;background:#f8fafc';
    box.innerHTML=`<h3 style="margin:0 0 10px">Délai de paiement fournisseur</h3><label>Délai applicable *</label><select id="supplierPaymentTermType" onchange="ppUpdateSupplierPaymentTermHelpPP()" style="width:100%;padding:10px"><option value="default">60 jours — délai légal sans accord</option><option value="agreed">120 jours — délai convenu avec le fournisseur</option><option value="exception">180 jours — dérogation sectorielle uniquement</option></select><div id="supplierPaymentTermHelp" style="display:none"></div><label>Référence accord / dérogation</label><textarea id="supplierPaymentTermNote" rows="2" placeholder="Ex: accord contractuel, secteur et référence de la dérogation..."></textarea>`;
    form.insertBefore(box,actions);
}
function ppUpdateSupplierPaymentTermHelpPP(){
    const type=getValue('supplierPaymentTermType')||'default',help=document.getElementById('supplierPaymentTermHelp');if(!help)return;
    help.innerHTML=type==='exception'?'<strong style="color:#b42318">180 jours :</strong> à utiliser uniquement si le secteur bénéficie réellement d’une dérogation autorisée.':type==='agreed'?'<strong style="color:#896400">120 jours :</strong> accord entre les parties obligatoire.':'<strong style="color:#177348">60 jours :</strong> délai légal appliqué automatiquement en l’absence d’accord.';
}

function openSupplierModal(id = null){
    ppEnsureSupplierPaymentTermFieldsPP();editingSupplierId=id?Number(id):null; const form=document.getElementById("supplierForm"); if(form)form.reset(); const title=document.querySelector("#supplierModal .modal-header h2");
    if(editingSupplierId){ const x=suppliers.find(s=>Number(s.id)===editingSupplierId); if(!x)return;const term=ppSupplierLegalTermPP(x); if(title)title.textContent="Modifier un fournisseur"; setValue("supplierName",x.name);setValue("supplierPhone",x.phone);setValue("supplierEmail",x.email);setValue("supplierIce",x.ice);setValue("supplierIf",x.if);setValue("supplierAddress",x.address);setValue("supplierPurchases",x.purchases);setValue("supplierPaid",x.paid);setValue('supplierPaymentTermType',term.type);setValue('supplierPaymentTermNote',x.paymentTermNote||''); }
    else {if(title)title.textContent="Ajouter un fournisseur";setValue("supplierPurchases",0);setValue("supplierPaid",0);setValue('supplierPaymentTermType','default');setValue('supplierPaymentTermNote','');}ppUpdateSupplierPaymentTermHelpPP(); openModal("supplierModal");
}


function addSupplier(){
    const name=getValue("supplierName").trim(); if(!name){alert("Veuillez saisir le nom du fournisseur.");return;}
    const paymentTermType=getValue('supplierPaymentTermType')||'default',paymentTerm=ppSupplierLegalTermPP({paymentTermType}),paymentTermNote=getValue('supplierPaymentTermNote').trim();
    if(paymentTermType==='exception'&&!paymentTermNote){alert('Pour un délai de 180 jours, indiquez le secteur ou la référence de la dérogation.');return;}
    const data={name,phone:getValue("supplierPhone").trim(),email:getValue("supplierEmail").trim(),ice:getValue("supplierIce").trim(),if:getValue("supplierIf").trim(),address:getValue("supplierAddress").trim(),purchases:parseNumber(getValue("supplierPurchases")),paid:parseNumber(getValue("supplierPaid")),paymentTermType:paymentTerm.type,paymentTermDays:paymentTerm.days,paymentTermNote,paymentTermUpdatedAt:new Date().toISOString()};
    if(editingSupplierId){const x=suppliers.find(s=>Number(s.id)===editingSupplierId);if(!x)return;Object.assign(x,data);invoices.forEach(inv=>{if(Number(inv.supplierId)!==editingSupplierId)return;inv.supplierName=name;if(Number(inv.due||0)>0.005){inv.paymentTermType=paymentTerm.type;inv.paymentTermDays=paymentTerm.days;inv.paymentTermSource='supplier';inv.paymentTermNote=paymentTermNote;inv.dueDate=ppAddCalendarDaysPP(inv.date,paymentTerm.days);}});}
    else suppliers.push({id:createId(),...data});
    editingSupplierId=null;saveData();closeModal("supplierModal");renderAll();
}


function renderSuppliers(){
    const table=document.getElementById("suppliersTable"); if(!table)return; const search=normalizeText(getValue("supplierSearch"));
    const filtered=suppliers.filter(s=>normalizeText(s.name).includes(search)||normalizeText(s.phone).includes(search)||normalizeText(s.ice).includes(search));
    if(!filtered.length){table.innerHTML='<tr><td colspan="8" class="empty">Aucun fournisseur enregistré.</td></tr>';return;}
    table.innerHTML=filtered.map(s=>{const purchases=Number(s.purchases||0),paid=Number(s.paid||0),due=Math.max(purchases-paid,0);let cls='success',txt='Soldé';if(due>0&&paid>0){cls='warning';txt='Partiellement payé';}else if(due>0){cls='danger';txt='Non payé';}
    return `<tr><td><strong>${escapeHTML(s.name)}</strong></td><td>${escapeHTML(s.phone||'-')}</td><td>${escapeHTML(s.ice||'-')}</td><td>${formatMoney(purchases)}</td><td>${formatMoney(paid)}</td><td>${formatMoney(due)}</td><td><span class="status ${cls}">${txt}</span></td><td><div class="action-buttons"><button class="btn small view" onclick="viewSupplier(${s.id})">👁️</button><button class="btn small edit" onclick="openSupplierModal(${s.id})">✏️</button><button class="btn small print" onclick="printSupplier(${s.id})">🖨️</button><button class="btn small danger" onclick="deleteSupplier(${s.id})">🗑️</button></div></td></tr>`;}).join('');
}


function deleteSupplier(id){

    const used =
        invoices.some(function(invoice){

            return Number(
                invoice.supplierId
            )
            ===
            Number(
                id
            );

        });


    if(used){

        alert(
            "Impossible de supprimer ce fournisseur car il possède déjà des factures."
        );

        return;

    }


    if(
        !confirm(
            "Voulez-vous supprimer ce fournisseur ?"
        )
    ){

        return;

    }


    suppliers =
        suppliers.filter(function(supplier){

            return Number(
                supplier.id
            )
            !==
            Number(
                id
            );

        });


    saveData();

    renderAll();

}



function viewSupplier(id){const s=suppliers.find(x=>Number(x.id)===Number(id));if(!s)return;showDetailsModal("Fournisseur",[["Nom",s.name],["Téléphone",s.phone||'-'],["Email",s.email||'-'],["ICE",s.ice||'-'],["IF",s.if||'-'],["Adresse",s.address||'-'],["Total achats",formatMoney(s.purchases)],["Payé",formatMoney(s.paid)],["Reste",formatMoney(Math.max(Number(s.purchases)-Number(s.paid),0))]],()=>printSupplier(id));}
function printSupplier(id){const s=suppliers.find(x=>Number(x.id)===Number(id));if(!s)return;printDocument("Fiche fournisseur - "+s.name,`<h2>Fiche fournisseur</h2>${detailRowsHTML([["Nom",s.name],["Téléphone",s.phone||'-'],["Email",s.email||'-'],["ICE",s.ice||'-'],["IF",s.if||'-'],["Adresse",s.address||'-'],["Total achats",formatMoney(s.purchases)],["Payé",formatMoney(s.paid)],["Reste",formatMoney(Math.max(Number(s.purchases)-Number(s.paid),0))]])}`);}

/* =========================================================
   INVOICE MODAL
========================================================= */

function ppAddCalendarDaysPP(isoDate,days){
    const parts=String(isoDate||'').slice(0,10).split('-').map(Number);
    if(parts.length!==3||!parts.every(Number.isFinite))return '';
    const d=new Date(parts[0],parts[1]-1,parts[2],12,0,0,0);d.setDate(d.getDate()+Number(days||0));
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}
function ppDaysBetweenISOPP(from,to){
    const a=String(from||'').slice(0,10).split('-').map(Number),b=String(to||'').slice(0,10).split('-').map(Number);
    if(a.length!==3||b.length!==3||!a.every(Number.isFinite)||!b.every(Number.isFinite))return 0;
    return Math.round((new Date(b[0],b[1]-1,b[2],12)-new Date(a[0],a[1]-1,a[2],12))/86400000);
}
function ppInvoiceLegalTermPP(invoice={}){
    const allowed=['cash','default','agreed','exception'];
    let type=allowed.includes(String(invoice.paymentTermType||''))?String(invoice.paymentTermType):'default';
    let days=Math.max(Math.round(Number(invoice.paymentTermDays??60)),0);
    if(type==='cash')days=0;
    else if(type==='default')days=60;
    else if(type==='agreed')days=Math.min(Math.max(days||90,1),120);
    else if(type==='exception')days=Math.min(Math.max(days||180,1),180);
    return {type,days};
}
function ppNormalizeInvoiceDeadlinePP(invoice={}){
    const term=ppInvoiceLegalTermPP(invoice);
    return {...invoice,totalHT:Number(invoice.totalHT||0),tva:Number(invoice.tva||0),totalTTC:Number(invoice.totalTTC||0),paid:Number(invoice.paid||0),due:Number(invoice.due??Math.max(Number(invoice.totalTTC||0)-Number(invoice.paid||0),0)),lines:Array.isArray(invoice.lines)?invoice.lines:[],paymentTermType:term.type,paymentTermDays:term.days,dueDate:String(invoice.dueDate||ppAddCalendarDaysPP(invoice.date,term.days)||'').slice(0,10)};
}
function ppInvoiceTermLabelPP(invoice){
    const term=ppInvoiceLegalTermPP(invoice);
    if(term.type==='cash')return 'Paiement comptant';
    if(term.type==='default')return 'Délai légal — 60 jours';
    if(term.type==='agreed')return `Délai convenu — ${term.days} jours`;
    return `Dérogation sectorielle — ${term.days} jours`;
}
function ppApplySupplierTermToInvoicePP(){
    const supplierId=Number(getValue('invoiceSupplier')),supplier=suppliers.find(s=>Number(s.id)===supplierId);
    const term=supplier?ppSupplierLegalTermPP(supplier):{type:'default',days:60};
    setValue('invoicePaymentTermType',term.type);setValue('invoicePaymentTermDays',term.days);ppUpdateInvoiceLegalDeadlinePP(false);
    const note=document.getElementById('invoicePaymentTermNote');if(note&&supplier)note.innerHTML+=`<br><strong>Hérité de la fiche fournisseur : ${escapeHTML(supplier.name)}</strong>`;
}
function ppEnsureInvoicePaymentDeadlineFieldsPP(){
    if(document.getElementById('invoicePaymentTermType'))return;
    const grid=document.querySelector('#invoiceForm .form-grid');if(!grid)return;
    const typeBox=document.createElement('div');typeBox.innerHTML=`<label>Base du délai (fiche fournisseur)</label><select id="invoicePaymentTermType" disabled><option value="default">60 jours — délai légal</option><option value="agreed">120 jours — délai convenu</option><option value="exception">180 jours — dérogation sectorielle</option></select>`;
    const daysBox=document.createElement('div');daysBox.innerHTML=`<label>Nombre de jours</label><input id="invoicePaymentTermDays" type="number" min="0" max="180" step="1" value="60" oninput="ppUpdateInvoiceLegalDeadlinePP(false)"><small id="invoicePaymentTermNote" style="display:none"></small>`;
    const dueBox=document.createElement('div');dueBox.innerHTML=`<label>Échéance légale calculée</label><input id="invoiceLegalDueDate" type="date" readonly>`;
    grid.append(typeBox,daysBox,dueBox);
    document.getElementById('invoiceDate')?.addEventListener('change',()=>ppUpdateInvoiceLegalDeadlinePP(false));
    document.getElementById('invoiceSupplier')?.addEventListener('change',ppApplySupplierTermToInvoicePP);
}
function ppUpdateInvoiceLegalDeadlinePP(resetDays=false){
    const type=getValue('invoicePaymentTermType')||'default',input=document.getElementById('invoicePaymentTermDays');if(!input)return;
    let days=Math.max(Math.round(Number(input.value||0)),0),note='';
    input.readOnly=true;
    if(type==='cash'){days=0;note='Paiement exigible à la date de facture.';}
    else if(type==='default'){days=60;note='Loi 69-21 : 60 jours lorsqu’aucun délai n’est convenu.';}
    else if(type==='agreed'){days=120;note='Délai hérité de la fiche fournisseur — accord entre les parties obligatoire.';}
    else {days=180;note='Délai hérité de la fiche fournisseur — dérogation sectorielle autorisée obligatoire.';}
    input.value=String(days);setValue('invoiceLegalDueDate',ppAddCalendarDaysPP(getValue('invoiceDate'),days));setText('invoicePaymentTermNote',note);
}
function ppInvoiceTermFromFormPP(){
    const type=getValue('invoicePaymentTermType')||'default';let days=Math.max(Math.round(Number(getValue('invoicePaymentTermDays')||0)),0);
    if(type==='cash')days=0;
    if(type==='default')days=60;
    if(type==='agreed'&&(days<1||days>120)){alert('Le délai convenu doit être compris entre 1 et 120 jours.');return null;}
    if(type==='exception'&&(days<1||days>180)){alert('Le délai dérogatoire ne peut pas dépasser 180 jours.');return null;}
    return {type,days,dueDate:ppAddCalendarDaysPP(getValue('invoiceDate'),days)};
}

function openInvoiceModal(id = null){
    ppEnsureInvoicePaymentDeadlineFieldsPP();editingInvoiceId=id?Number(id):null; const form=document.getElementById("invoiceForm"); if(form)form.reset(); populateInvoiceSuppliers(); const container=document.getElementById("invoiceLines");if(container)container.innerHTML=""; const title=document.querySelector("#invoiceModal .modal-header h2");
    if(editingInvoiceId){ const inv=invoices.find(x=>Number(x.id)===editingInvoiceId);if(!inv)return;const term=ppInvoiceLegalTermPP(inv);if(title)title.textContent="🧾 Modifier la facture d'achat";setValue("invoiceSupplier",inv.supplierId);setValue("invoiceNumber",inv.number);setValue("invoiceDate",inv.date);setValue("invoicePaid",inv.paid);setValue('invoicePaymentTermType',term.type);setValue('invoicePaymentTermDays',term.days);(inv.lines||[]).forEach(line=>addInvoiceLine(line));if(!(inv.lines||[]).length)addInvoiceLine(); }
    else {if(title)title.textContent="🧾 Nouvelle facture d'achat";setValue("invoiceDate",new Date().toISOString().split("T")[0]);setValue("invoicePaid",0);setValue('invoicePaymentTermType','default');setValue('invoicePaymentTermDays',60);addInvoiceLine();}
    ppUpdateInvoiceLegalDeadlinePP(false);
    updateInvoiceTotals();openModal("invoiceModal");
}


function populateInvoiceSuppliers(){

    const select =
        document.getElementById(
            "invoiceSupplier"
        );


    if(!select){

        return;

    }


    select.innerHTML = `

        <option value="">
            Sélectionner un fournisseur
        </option>

        ${
            suppliers.map(function(supplier){

                return `

                    <option value="${supplier.id}">

                        ${escapeHTML(supplier.name)}

                    </option>

                `;

            }).join("")
        }

    `;

}


/* =========================================================
   INVOICE LINE
========================================================= */

function addInvoiceLine(data = {}){

    const container =
        document.getElementById(
            "invoiceLines"
        );


    if(!container){

        return;

    }


    const line =
        document.createElement(
            "div"
        );


    line.className =
        "invoice-line";

    // Keep the provenance of the VAT value so that a real 0% can be distinguished
    // from an OCR line where TVA was simply not detected.
    line.dataset.vatKnown = data.vatKnown ? "1" : "0";
    line.dataset.vatSource = data.vatSource || "";

    // Keep the designation exactly as read on the supplier invoice.
    // It is used to learn an alias without changing quantity, price or VAT.
    const originalDesignation = String(
        data.sourceDesignation ||
        data.originalDesignation ||
        data.name ||
        ""
    ).trim();
    line.dataset.invoiceOriginalDesignation = originalDesignation;
    line.dataset.preserveInvoiceValues = (
        data.preserveInvoiceValues === true ||
        Boolean(data.sourceDesignation || data.originalDesignation) ||
        data.quantity !== undefined ||
        data.price !== undefined ||
        data.vatRate !== undefined
    ) ? "1" : "0";


    const selectedCategory =
        data.category ||
        "Autre";


    const selectedUnit =
        data.unit ||
        "pièce";


    const selectedVat =
        Number(
            data.vatRate ??
            0
        );


    line.innerHTML = `

        <div>

            <label>
                Produit
            </label>

            <select
                class="invoice-product"
                onchange="handleInvoiceProductChange(this)"
            >

                <option value="">
                    Nouveau produit
                </option>

                ${
                    products.map(function(product){

                        const selected =
                            data.productId
                            &&
                            Number(
                                data.productId
                            )
                            ===
                            Number(
                                product.id
                            )
                            ?
                            "selected"
                            :
                            "";


                        return `

                            <option
                                value="${product.id}"
                                ${selected}
                            >

                                ${escapeHTML(product.name)}

                            </option>

                        `;

                    }).join("")
                }

            </select>


            <input
                type="text"
                class="invoice-new-product"
                placeholder="Nom du produit"
                value="${escapeHTML(data.name || "")}"
            >

        </div>


        <div>

            <label>
                Catégorie
            </label>

            <select class="invoice-category">

                ${
                    [
                        "Épicerie",
                        "Viandes",
                        "Poissons",
                        "Produits laitiers",
                        "Fruits & Légumes",
                        "Boissons",
                        "Autre"
                    ]
                    .map(function(category){

                        return `

                            <option
                                ${
                                    category ===
                                    selectedCategory
                                    ?
                                    "selected"
                                    :
                                    ""
                                }
                            >

                                ${category}

                            </option>

                        `;

                    })
                    .join("")
                }

            </select>

        </div>


        <div>

            <label>
                Quantité
            </label>

            <input
                type="number"
                class="invoice-quantity"
                min="0.000001"
                step="0.000001"
                value="${Number(data.quantity || 1)}"
                oninput="updateInvoiceTotals()"
            >

        </div>


        <div>

            <label>
                Unité
            </label>

            <select class="invoice-unit">

                ${
                    [
                        "kg",
                        "g",
                        "L",
                        "ml",
                        "pièce",
                        "sac",
                        "carton",
                        "paquet"
                    ]
                    .map(function(unit){

                        return `

                            <option
                                ${
                                    unit ===
                                    selectedUnit
                                    ?
                                    "selected"
                                    :
                                    ""
                                }
                            >

                                ${unit}

                            </option>

                        `;

                    })
                    .join("")
                }

            </select>

        </div>


        <div>

            <label>
                Prix unitaire HT
            </label>

            <input
                type="number"
                class="invoice-price"
                min="0"
                step="0.000001"
                value="${Number(data.price || 0)}"
                oninput="updateInvoiceTotals()"
            >

        </div>


        <div>

            <label>
                TVA
            </label>

            <select
                class="invoice-vat"
                onchange="markInvoiceVatManual(this); updateInvoiceTotals()"
            >

                ${
                    [
                        0,
                        7,
                        10,
                        14,
                        20
                    ]
                    .map(function(rate){

                        return `

                            <option
                                value="${rate}"
                                ${
                                    Number(
                                        rate
                                    )
                                    ===
                                    selectedVat
                                    ?
                                    "selected"
                                    :
                                    ""
                                }
                            >

                                ${rate}%

                            </option>

                        `;

                    })
                    .join("")
                }

            </select>

        </div>


        <div>

            <label>
                Total HT
            </label>

            <input
                type="text"
                class="invoice-line-total"
                readonly
                value="0 DH"
            >

        </div>


        <button
            type="button"
            class="btn danger small"
            onclick="removeInvoiceLine(this)"
        >
            🗑️
        </button>

    `;


    container.appendChild(
        line
    );


    updateInvoiceTotals();

}


function removeInvoiceLine(button){

    button
        .closest(
            ".invoice-line"
        )
        ?.remove();


    if(
        !document.querySelector(
            "#invoiceLines .invoice-line"
        )
    ){

        addInvoiceLine();

    }


    updateInvoiceTotals();

}


function handleInvoiceProductChange(select){

    const line =
        select.closest(
            ".invoice-line"
        );


    if(!line){

        return;

    }


    const product =
        products.find(function(item){

            return Number(
                item.id
            )
            ===
            Number(
                select.value
            );

        });


    if(!product){

        return;

    }


    line.querySelector(
        ".invoice-new-product"
    ).value =
        product.name;


    line.querySelector(
        ".invoice-category"
    ).value =
        product.category;


    line.querySelector(
        ".invoice-unit"
    ).value =
        product.unit;


    line.querySelector(
        ".invoice-price"
    ).value =
        Number(
            product.price ||
            0
        );


    updateInvoiceTotals();

}


/* =========================================================
   INVOICE TOTALS
========================================================= */

function updateInvoiceTotals(){

    let totalHT =
        0;


    let totalTVA =
        0;


    document
        .querySelectorAll(
            "#invoiceLines .invoice-line"
        )
        .forEach(function(line){

            const quantity =
                parseNumber(
                    line.querySelector(
                        ".invoice-quantity"
                    )?.value
                );


            const price =
                parseNumber(
                    line.querySelector(
                        ".invoice-price"
                    )?.value
                );


            const vatRate =
                parseNumber(
                    line.querySelector(
                        ".invoice-vat"
                    )?.value
                );


            const lineHT =
                quantity *
                price;


            const lineTVA =
                lineHT *
                vatRate /
                100;


            totalHT +=
                lineHT;


            totalTVA +=
                lineTVA;


            const totalInput =
                line.querySelector(
                    ".invoice-line-total"
                );


            if(totalInput){

                totalInput.value =
                    formatMoney(
                        lineHT
                    );

            }

        });


    const totalTTC =
        totalHT +
        totalTVA;


    const paid =
        parseNumber(
            getValue(
                "invoicePaid"
            )
        );


    setText(
        "invoiceHTPreview",
        formatMoney(
            totalHT
        )
    );


    setText(
        "invoiceTVAPreview",
        formatMoney(
            totalTVA
        )
    );


    setText(
        "invoiceTTCPreview",
        formatMoney(
            totalTTC
        )
    );


    setText(
        "invoiceDuePreview",
        formatMoney(

            Math.max(
                totalTTC -
                paid,
                0
            )

        )
    );

}


/* =========================================================
   SAVE INVOICE
========================================================= */

function ppInvoiceIdentityPP(value){
    return normalizeText(String(value||""))
        .replace(/[^a-z0-9]/g,"");
}

function ppFindDuplicateSupplierInvoicePP(supplierId,number,excludedInvoiceId=null){
    const identity=ppInvoiceIdentityPP(number);
    if(!identity)return null;
    return invoices.find(invoice=>
        Number(invoice.supplierId)===Number(supplierId)
        && ppInvoiceIdentityPP(invoice.number)===identity
        && (excludedInvoiceId===null || Number(invoice.id)!==Number(excludedInvoiceId))
    )||null;
}

function saveInvoice(){
    const supplierId=Number(getValue("invoiceSupplier"));
    const supplier=suppliers.find(x=>Number(x.id)===supplierId);
    if(!supplier){alert("Veuillez sélectionner un fournisseur.");return;}

    const number=getValue("invoiceNumber").trim();
    if(!number){alert("Veuillez saisir le numéro de facture.");return;}

    const duplicateInvoice=ppFindDuplicateSupplierInvoicePP(supplier.id,number,editingInvoiceId);
    if(duplicateInvoice){
        alert(`Cette facture existe déjà pour ${supplier.name}.\n\nN° facture : ${duplicateInvoice.number}\nDate : ${formatDate(duplicateInvoice.date)}\nMontant TTC : ${formatMoney(duplicateInvoice.totalTTC)}`);
        return;
    }

    const paymentTerm=ppInvoiceTermFromFormPP();
    if(!paymentTerm)return;

    const lines=[];
    document.querySelectorAll("#invoiceLines .invoice-line").forEach(line=>{
        const productId=Number(line.querySelector(".invoice-product")?.value);
        const existing=products.find(p=>Number(p.id)===productId);
        const typed=(line.querySelector(".invoice-new-product")?.value||"").trim();
        const sourceDesignation=(line.dataset.invoiceOriginalDesignation||typed).trim();
        const name=existing?existing.name:typed;
        const quantity=parseNumber(line.querySelector(".invoice-quantity")?.value);
        const price=parseNumber(line.querySelector(".invoice-price")?.value);
        const vatRate=parseNumber(line.querySelector(".invoice-vat")?.value);
        if(!name||quantity<=0)return;

        const totalHT=quantity*price;
        const vatAmount=totalHT*vatRate/100;
        lines.push({
            productId:existing?existing.id:null,
            name,
            sourceDesignation:sourceDesignation||name,
            category:line.querySelector(".invoice-category")?.value||"Autre",
            unit:line.querySelector(".invoice-unit")?.value||"pièce",
            quantity,
            price,
            vatRate,
            vatKnown:line.dataset.vatKnown==="1",
            vatSource:line.dataset.vatSource||"",
            vatAmount,
            totalHT,
            totalTTC:totalHT+vatAmount
        });
    });

    if(!lines.length){alert("Ajoutez au moins un produit.");return;}

    // Learn every manual/automatic link between the supplier designation and
    // the canonical stock article. The next scan will select it directly.
    lines.forEach(line=>{
        if(!line.productId)return;
        const product=products.find(p=>Number(p.id)===Number(line.productId));
        ppRememberInvoiceAliasPP(product,line.sourceDesignation||line.name,supplier.id);
    });

    const totalHT=lines.reduce((a,l)=>a+l.totalHT,0);
    const totalTVA=lines.reduce((a,l)=>a+l.vatAmount,0);
    const totalTTC=totalHT+totalTVA;
    const paid=parseNumber(getValue("invoicePaid"));

    if(editingInvoiceId){
        const old=invoices.find(x=>Number(x.id)===editingInvoiceId);
        if(old)reverseInvoiceEffects(old);
    }

    const previousInvoice=editingInvoiceId
        ?invoices.find(x=>Number(x.id)===editingInvoiceId)
        :null;
    const invoice={
        id:editingInvoiceId||createId(),
        number,
        date:getValue("invoiceDate"),
        supplierId:supplier.id,
        supplierName:supplier.name,
        lines,
        totalHT,
        tva:totalTVA,
        totalTTC,
        paid,
        due:Math.max(totalTTC-paid,0),
        paymentTermType:paymentTerm.type,
        paymentTermDays:paymentTerm.days,
        paymentTermSource:"supplier",
        paymentTermNote:supplier.paymentTermNote||"",
        dueDate:paymentTerm.dueDate,
        createdAt:previousInvoice?.createdAt||new Date().toISOString(),
        updatedAt:new Date().toISOString()
    };

    if(editingInvoiceId){
        const i=invoices.findIndex(x=>Number(x.id)===editingInvoiceId);
        invoices[i]=invoice;
    }else{
        invoices.unshift(invoice);
    }

    applyInvoiceEffects(invoice);
    editingInvoiceId=null;
    saveData();
    closeModal("invoiceModal");
    renderAll();
    alert("Facture enregistrée avec succès.");
}


