/* =========================================================
   SCANNER LOCAL BRIDGE — WINDOWS + MAC
   GitHub Pages communicates only with 127.0.0.1.
========================================================= */
const PP_SCANNER_BRIDGE_URL = "http://127.0.0.1:17891";
const PP_SCANNER_SELECTION_KEY = "pause_plate_selected_scanner";

async function ppScannerFetch(path,options={},timeoutMs=10000){
    const controller=typeof AbortController!=="undefined"?new AbortController():null;
    const timer=controller?setTimeout(()=>controller.abort(),timeoutMs):null;
    try{
        return await fetch(PP_SCANNER_BRIDGE_URL+path,{
            cache:"no-store",
            mode:"cors",
            credentials:"omit",
            ...options,
            ...(controller?{signal:controller.signal}:{})
        });
    }catch(error){
        if(error?.name==="AbortError")throw new Error("Le Scanner Bridge ne répond pas.");
        throw new Error("Scanner Bridge introuvable sur cet ordinateur.");
    }finally{
        if(timer)clearTimeout(timer);
    }
}

async function ppScannerBridgeHealth(){
    const r=await ppScannerFetch("/health",{},30000);
    if(!r.ok)throw new Error("Bridge scanner indisponible.");
    const data=await r.json().catch(()=>({}));
    if(data.ready===false&&data.message)throw new Error(data.message);
    return data;
}

async function ppGetAvailableScanners(){
    const response=await ppScannerFetch("/scanners",{},30000);
    if(!response.ok){
        const data=await response.json().catch(()=>({}));
        throw new Error(data.error||data.message||"Impossible de détecter les scanners.");
    }
    const data=await response.json().catch(()=>({scanners:[]}));
    const scanners=Array.isArray(data)?data:(Array.isArray(data.scanners)?data.scanners:[]);
    if(!scanners.length){
        throw new Error(data.message||"Aucun scanner détecté. Vérifiez le câble USB ou le réseau Wi-Fi/LAN, l’alimentation et le pilote.");
    }
    return scanners.map((scanner,index)=>({
        id:String(scanner.id??scanner.device_id??index),
        name:String(scanner.name??scanner.model??`Scanner ${index+1}`),
        vendor:String(scanner.vendor??scanner.manufacturer??""),
        backend:String(scanner.backend??data.backend??""),
        connection:String(scanner.connection??""),
        network:Boolean(
            scanner.network
            ||String(scanner.connection||"").toLowerCase()==="network"
            ||/airscan|escl|wsd/i.test(String(scanner.backend||""))
        )
    }));
}

function ppChooseScanner(scanners,forceChoice=false){
    if(!Array.isArray(scanners)||!scanners.length)throw new Error("Aucun scanner détecté.");
    const savedId=forceChoice?"":String(localStorage.getItem(PP_SCANNER_SELECTION_KEY)||"");
    const saved=scanners.find(scanner=>scanner.id===savedId);
    if(saved)return saved;

    if(scanners.length===1){
        localStorage.setItem(PP_SCANNER_SELECTION_KEY,scanners[0].id);
        return scanners[0];
    }

    const choices=scanners.map((scanner,index)=>`${index+1}. ${scanner.network?"🌐":"🔌"} ${scanner.name}${scanner.vendor?` — ${scanner.vendor}`:""}`).join("\n");
    const answer=prompt(`Choisissez le scanner :\n\n${choices}`,"1");
    if(answer===null)throw new Error("Sélection du scanner annulée.");
    const index=Math.max(0,Math.min(Number.parseInt(answer,10)-1,scanners.length-1));
    const selected=scanners[Number.isFinite(index)?index:0];
    localStorage.setItem(PP_SCANNER_SELECTION_KEY,selected.id);
    return selected;
}

function ppScannerStatusElementPP(purpose){
    return document.getElementById(purpose==="invoice"?"ppInvoiceScannerStatus":"ppDailyScannerStatus");
}

async function ppRefreshScannerStatusPP(purpose){
    const status=ppScannerStatusElementPP(purpose);
    if(status){
        status.textContent="Recherche du Scanner Bridge et des appareils…";
        status.style.color="#667085";
    }
    try{
        const health=await ppScannerBridgeHealth();
        const scanners=await ppGetAvailableScanners();
        const savedId=String(localStorage.getItem(PP_SCANNER_SELECTION_KEY)||"");
        const selected=scanners.find(scanner=>scanner.id===savedId)||scanners[0];
        if(status){
            status.innerHTML=`✅ Bridge ${escapeHTML(health.platform||"Windows / Mac")} actif — ${selected.network?"🌐":"🔌"} <strong>${escapeHTML(selected.name)}</strong> prêt.`;
            status.style.color="#067647";
        }
        return {health,scanners};
    }catch(error){
        if(status){
            status.innerHTML=`❌ ${escapeHTML(error?.message||String(error))}<br><small>Lancez ou installez Pause & Plate Scanner Bridge sur Windows / Mac.</small>`;
            status.style.color="#b42318";
        }
        return null;
    }
}

async function ppSelectScannerPP(purpose){
    const status=ppScannerStatusElementPP(purpose);
    if(status){
        status.textContent="Recherche des scanners disponibles…";
        status.style.color="#667085";
    }
    try{
        await ppScannerBridgeHealth();
        const scanners=await ppGetAvailableScanners();
        const scanner=ppChooseScanner(scanners,true);
        if(status){
            status.innerHTML=`✅ Scanner sélectionné : ${scanner.network?"🌐":"🔌"} <strong>${escapeHTML(scanner.name)}</strong>`;
            status.style.color="#067647";
        }
        return scanner;
    }catch(error){
        if(status){
            status.innerHTML=`❌ ${escapeHTML(error?.message||String(error))}<br><small>Vérifiez le Bridge, le câble USB ou le réseau local, et le pilote Windows / Mac.</small>`;
            status.style.color="#b42318";
        }
        return null;
    }
}

function ppBase64ToFile(base64,mime,name){
    const bin=atob(base64);
    const bytes=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
    return new File([bytes],name||"scan.jpg",{type:mime||"image/jpeg"});
}

function ppResetInvoiceLiveScanPP(){
    ppInvoiceLiveScanPages.forEach(page=>{
        if(page.previewUrl)URL.revokeObjectURL(page.previewUrl);
    });
    ppInvoiceLiveScanPages=[];
    ppInvoiceScanBusy=false;

    const first=document.getElementById("ppInvoiceScanFirstBtn");
    const next=document.getElementById("ppInvoiceScanNextBtn");
    const restart=document.getElementById("ppInvoiceScanRestartBtn");
    const pages=document.getElementById("ppInvoicePagesStatus");
    if(first){first.style.display="";first.disabled=false;}
    if(next){next.style.display="none";next.disabled=false;}
    if(restart)restart.style.display="none";
    if(pages){pages.style.display="none";pages.innerHTML="";}
}

function ppRestartInvoiceLiveScanPP(){
    scannedInvoiceText="";
    scannedInvoiceData=null;
    scannedPDFPages=[];
    ppResetInvoiceLiveScanPP();
    const preview=document.getElementById("scanPreview");
    if(preview)preview.innerHTML="";
    const status=document.getElementById("ppInvoiceScannerStatus");
    if(status){
        status.textContent="Prêt à scanner la première page.";
        status.style.color="#667085";
    }
}

function ppRenderInvoiceLivePagesPP(){
    const count=ppInvoiceLiveScanPages.length;
    const first=document.getElementById("ppInvoiceScanFirstBtn");
    const next=document.getElementById("ppInvoiceScanNextBtn");
    const restart=document.getElementById("ppInvoiceScanRestartBtn");
    const pages=document.getElementById("ppInvoicePagesStatus");
    if(first)first.style.display=count?"none":"";
    if(next){next.style.display=count?"":"none";next.disabled=ppInvoiceScanBusy;}
    if(restart)restart.style.display=count?"":"none";
    if(!pages)return;
    if(!count){pages.style.display="none";pages.innerHTML="";return;}

    pages.style.display="block";
    pages.innerHTML=`
        <div class="pp-invoice-pages-head">
            <strong>📚 ${count} page(s) scannée(s)</strong>
            <span>Ajoutez toutes les pages avant d'utiliser les informations.</span>
        </div>
        <div class="pp-invoice-pages-list">
            ${ppInvoiceLiveScanPages.map((page,index)=>`
                <div class="pp-invoice-page-chip">
                    <a href="${page.previewUrl}" target="_blank" rel="noopener" title="Ouvrir l'image scannée">
                        <img src="${page.previewUrl}" alt="Page ${index+1}">
                    </a>
                    <div>
                        <strong>Page ${index+1}</strong>
                        <small>${page.textLength} caractères OCR</small>
                        <small>${page.qualityLabel}</small>
                    </div>
                    <button type="button" title="Supprimer cette page" onclick="ppRemoveInvoiceLivePagePP(${index})">×</button>
                </div>
            `).join("")}
        </div>`;
}

function ppCombineInvoiceLiveTextPP(){
    return ppInvoiceLiveScanPages.map((page,index)=>
        `\n===== PAGE ${index+1} =====\n${page.text||""}\n`
    ).join("\n");
}

function ppRemoveInvoiceLivePagePP(index){
    const page=ppInvoiceLiveScanPages[index];
    if(!page)return;
    if(page.previewUrl)URL.revokeObjectURL(page.previewUrl);
    ppInvoiceLiveScanPages.splice(index,1);
    scannedInvoiceText=ppCombineInvoiceLiveTextPP();
    scannedPDFPages=[];
    ppRenderInvoiceLivePagesPP();
    if(ppInvoiceLiveScanPages.length){
        finishScan();
    }else{
        scannedInvoiceData=null;
        const preview=document.getElementById("scanPreview");
        if(preview)preview.innerHTML="";
    }
}

async function ppAddInvoiceLivePagePP(file){
    const pageNumber=ppInvoiceLiveScanPages.length+1;
    const ocr=await ppRecognizeInvoiceImagePP(file,`Page ${pageNumber}`);
    const text=String(ocr?.text||"");
    const score=ppScoreOCRTextPP(text);
    const previewUrl=URL.createObjectURL(file);
    ppInvoiceLiveScanPages.push({
        text,
        rows:Array.isArray(ocr?.rows)?ocr.rows:[],
        textLength:String(text||"").trim().length,
        qualityScore:score,
        qualityLabel:score>=55?"OCR bon":score>=25?"OCR partiel":"OCR faible — vérifiez l'aperçu",
        previewUrl,
        fileName:file.name||`scan-page-${pageNumber}.jpg`
    });
    scannedInvoiceText=ppCombineInvoiceLiveTextPP();
    scannedPDFPages=[];
    finishScan();
    ppRenderInvoiceLivePagesPP();
    return ppInvoiceLiveScanPages[ppInvoiceLiveScanPages.length-1];
}

async function ppScanFromPCScanner(purpose){
    const status=ppScannerStatusElementPP(purpose);
    if(purpose==="invoice"&&ppInvoiceScanBusy)return;
    if(purpose==="invoice"){
        ppInvoiceScanBusy=true;
        ppRenderInvoiceLivePagesPP();
    }
    if(status){
        const pageNumber=purpose==="invoice"?ppInvoiceLiveScanPages.length+1:"";
        status.textContent=purpose==="invoice"?`Connexion au scanner — page ${pageNumber}...`:"Connexion au scanner...";
        status.style.color="#667085";
    }

    try{
        await ppScannerBridgeHealth();

        const scanners=await ppGetAvailableScanners();
        const scanner=ppChooseScanner(scanners);

        if(status){
            const pageLabel=purpose==="invoice"?`page ${ppInvoiceLiveScanPages.length+1} — `:"";
            status.textContent=`Scanner sélectionné : ${scanner.name||scanner.id} — ${pageLabel}numérisation en cours...`;
        }

        const response=await ppScannerFetch("/scan-file",{
            method:"POST",
            headers:{"Content-Type":"application/json"},
            body:JSON.stringify({
                purpose,
                device_id:scanner.id,
                scanner_id:scanner.id,
                resolution:300,
                mode:"Color"
            })
        },240000);

        if(!response.ok){
            const ct=response.headers.get("content-type")||"";
            let message="Échec de la numérisation.";
            if(ct.includes("application/json")){
                const errData=await response.json().catch(()=>({}));
                message=errData.error||message;
            }else{
                const txt=await response.text().catch(()=>"");
                if(txt)message=txt;
            }
            throw new Error(message);
        }

        const blob=await response.blob();
        if(!blob || !blob.size){
            throw new Error("Le scanner n'a retourné aucune image.");
        }

        const mime=blob.type||response.headers.get("content-type")||"image/jpeg";
        const filename=response.headers.get("X-PausePlate-Filename")||("scan-"+Date.now()+".jpg");
        const file=new File([blob],filename,{type:mime});

        if(status)status.textContent="Scan reçu — analyse OCR...";

        if(purpose==="invoice"){
            const page=await ppAddInvoiceLivePagePP(file);
            if(status){
                status.innerHTML=page.qualityScore>=25
                    ?`✅ Page ${ppInvoiceLiveScanPages.length} scannée et analysée. Ajoutez la page suivante si nécessaire.`
                    :`⚠️ Page ${ppInvoiceLiveScanPages.length} reçue, mais l'OCR reste faible. Vérifiez l'aperçu puis rescanner si l'image est pâle ou inclinée.`;
                status.style.color=page.qualityScore>=25?"#067647":"#b54708";
            }
        }else{
            ppDailyScanText=await extractDailySalesTextPP(file);
            ppDailyScanMatches=parseDailySalesTextPP(ppDailyScanText);
            renderDailyScanReviewPP();
            const main=document.getElementById("ppDailyScanStatus");
            if(main)main.innerHTML=`✅ Analyse terminée — <strong>${ppDailyScanMatches.length}</strong> élément(s) rapproché(s).`;
            if(status)status.textContent="✅ Rapport scanné et analysé.";
        }

    }catch(err){
        console.error(err);
        if(status){
            status.innerHTML="❌ "+escapeHTML(err?.message||String(err))+
                "<br><small>Vérifiez que Pause & Plate Scanner Bridge est lancé et que le scanner est connecté sur Windows / Mac.</small>";
            status.style.color="#b42318";
        }
    }finally{
        if(purpose==="invoice"){
            ppInvoiceScanBusy=false;
            ppRenderInvoiceLivePagesPP();
        }
    }
}

function ppScanInvoiceFromPC(){ return ppScanFromPCScanner("invoice"); }
function ppScanDailySalesFromPC(){ return ppScanFromPCScanner("daily-sales"); }

async function handleInvoiceFile(event){
    const files=Array.from(event.target.files||[]);
    if(!files.length)return;

    try{
        const pdfFiles=files.filter(file=>file.type==="application/pdf"||file.name.toLowerCase().endsWith(".pdf"));
        const imageFiles=files.filter(file=>String(file.type||"").startsWith("image/"));
        if(pdfFiles.length){
            if(files.length!==1)throw new Error("Choisissez soit un seul PDF multipage, soit plusieurs images.");
            ppResetInvoiceLiveScanPP();
            await scanPDFSmart(pdfFiles[0]);
            return;
        }
        if(imageFiles.length!==files.length)throw new Error("Format non supporté.");

        ppResetInvoiceLiveScanPP();
        scannedInvoiceText="";
        scannedInvoiceData=null;
        scannedPDFPages=[];
        for(let index=0;index<imageFiles.length;index++){
            showPDFTextProgress(`OCR de l'image ${index+1}/${imageFiles.length}...`,Math.max(5,Math.round(index/imageFiles.length*90)));
            await ppAddInvoiceLivePagePP(imageFiles[index]);
        }
        const status=document.getElementById("ppInvoiceScannerStatus");
        if(status){
            status.textContent=`✅ ${imageFiles.length} image(s) importée(s) et analysée(s).`;
            status.style.color="#067647";
        }
    }catch(error){
        console.error(error);
        const preview=document.getElementById("scanPreview");
        if(preview)preview.innerHTML=`<div class="scan-note">❌ Erreur pendant l'analyse.<br><br>${escapeHTML(error.message)}</div>`;
    }
}


/* =========================================================
   SMART PDF
========================================================= */

async function scanPDFSmart(file){

    if(
        typeof pdfjsLib ===
        "undefined"
    ){

        throw new Error(
            "PDF.js n'est pas chargé."
        );

    }


    const arrayBuffer =
        await file.arrayBuffer();


    const pdf =
        await pdfjsLib
            .getDocument({

                data:
                    arrayBuffer

            })
            .promise;


    showPDFTextProgress(
        "Lecture directe du PDF...",
        5
    );


    const pages =
        [];


    let directText =
        "";


    for(
        let pageNumber = 1;
        pageNumber <= pdf.numPages;
        pageNumber++
    ){

        const page =
            await pdf.getPage(
                pageNumber
            );


        const pageData =
            await extractPDFPageText(
                page
            );


        pages.push(
            pageData
        );


        directText +=

            "\n"

            +

            pageData.text

            +

            "\n";


        showPDFTextProgress(

            "Lecture directe du PDF...",

            Math.round(

                pageNumber
                /
                pdf.numPages
                *
                70

            )

        );

    }


    const score =
        scoreDirectPDFText(
            directText
        );


    if(
        score >=
        70
    ){

        scannedPDFPages =
            pages;


        scannedInvoiceText =
            directText;


        showPDFTextProgress(
            "Analyse de la facture...",
            95
        );


        await sleep(
            120
        );


        finishScan();

        return;

    }


    scannedPDFPages =
        [];


    await scanPDFWithOCRFallback(
        pdf
    );

}


/* =========================================================
   PDF PAGE TEXT + POSITIONS
========================================================= */

async function extractPDFPageText(page){

    const textContent =
        await page.getTextContent();


    const items =
        textContent.items
        .filter(function(item){

            return (

                item

                &&

                typeof item.str ===
                "string"

                &&

                item.str.trim()

            );

        })
        .map(function(item){

            const transform =
                item.transform ||
                [];


            return {

                text:
                    item.str.trim(),

                x:
                    Number(
                        transform[4] ||
                        0
                    ),

                y:
                    Number(
                        transform[5] ||
                        0
                    ),

                width:
                    Number(
                        item.width ||
                        0
                    )

            };

        });


    const rows =
        [];


    items.forEach(function(item){

        let row =
            rows.find(function(existing){

                return Math.abs(
                    existing.y -
                    item.y
                )
                <=
                3.5;

            });


        if(!row){

            row = {

                y:
                    item.y,

                items:
                    []

            };


            rows.push(
                row
            );

        }


        row.items.push(
            item
        );

    });


    rows.sort(function(a,b){

        return b.y -
            a.y;

    });


    rows.forEach(function(row){

        row.items.sort(function(a,b){

            return a.x -
                b.x;

        });

    });


    const structuredRows =
        rows.map(function(row){

            return {

                y:
                    row.y,

                columns:
                    row.items.map(function(item){

                        return {

                            text:
                                item.text,

                            x:
                                item.x,

                            width:
                                item.width

                        };

                    }),

                text:
                    row.items
                    .map(function(item){

                        return item.text;

                    })
                    .join(
                        " | "
                    )

            };

        });


    return {

        rows:
            structuredRows,

        text:
            structuredRows
            .map(function(row){

                return row.text;

            })
            .join(
                "\n"
            )

    };

}


/* =========================================================
   PDF QUALITY
========================================================= */

function scoreDirectPDFText(text){

    const normalized =
        normalizeText(
            text
        );


    let score =
        0;


    const letters =
        (
            text.match(
                /[A-Za-zÀ-ÿ]/g
            )
            ||
            []
        ).length;


    const numbers =
        (
            text.match(
                /\d+(?:[.,]\d+)?/g
            )
            ||
            []
        ).length;


    if(letters > 50){

        score +=
            20;

    }


    if(letters > 150){

        score +=
            20;

    }


    if(numbers >= 5){

        score +=
            15;

    }


    if(numbers >= 15){

        score +=
            15;

    }


    [

        "facture",
        "designation",
        "quantite",
        "total",
        "tva",
        "prix"

    ]
    .forEach(function(keyword){

        if(
            normalized.includes(
                normalizeText(
                    keyword
                )
            )
        ){

            score +=
                10;

        }

    });


    return score;

}


/* =========================================================
   PDF OCR FALLBACK
========================================================= */

async function scanPDFWithOCRFallback(pdf){

    if(
        typeof Tesseract ===
        "undefined"
    ){

        throw new Error(
            "Tesseract OCR n'est pas chargé."
        );

    }


    let fullText =
        "";


    for(
        let pageNumber = 1;
        pageNumber <= pdf.numPages;
        pageNumber++
    ){

        const page =
            await pdf.getPage(
                pageNumber
            );


        const viewport =
            page.getViewport({

                scale:
                    3.5

            });


        const canvas =
            document.createElement(
                "canvas"
            );


        const context =
            canvas.getContext(
                "2d"
            );


        canvas.width =
            Math.ceil(
                viewport.width
            );


        canvas.height =
            Math.ceil(
                viewport.height
            );


        context.fillStyle =
            "#FFFFFF";


        context.fillRect(

            0,

            0,

            canvas.width,

            canvas.height

        );


        await page.render({

            canvasContext:
                context,

            viewport:
                viewport

        }).promise;


        const text =
            await runDualOCR(

                canvas,

                preprocessCanvas(
                    canvas
                ),

                `Page ${pageNumber}`

            );


        fullText +=
            "\n" +
            text +
            "\n";

    }


    scannedInvoiceText =
        fullText;


    scannedPDFPages =
        [];


    finishScan();

}


/* =========================================================
   IMAGE OCR
========================================================= */

async function scanImageImproved(file){
    const ocr=await ppRecognizeInvoiceImagePP(file,"Image");
    scannedInvoiceText=String(ocr?.text||"");
    ppInvoiceLiveScanPages=[{
        text:scannedInvoiceText,
        rows:Array.isArray(ocr?.rows)?ocr.rows:[],
        textLength:scannedInvoiceText.trim().length,
        qualityScore:ppScoreOCRTextPP(scannedInvoiceText),
        qualityLabel:"OCR",
        previewUrl:"",
        fileName:file?.name||"image"
    }];
    scannedPDFPages=[];
    finishScan();
}

async function ppRecognizeInvoiceImagePP(file,label="Image"){
    if(typeof Tesseract==="undefined")throw new Error("Tesseract OCR n'est pas chargé.");
    const imageBitmap=await createImageBitmap(file);
    try{
        const canvas=ppPrepareOCRCanvasPP(imageBitmap);
        return await runDualOCR(canvas,preprocessCanvas(canvas,false),label,true);
    }finally{
        if(typeof imageBitmap.close==="function")imageBitmap.close();
    }
}

function ppPrepareOCRCanvasPP(imageSource){
    const sourceWidth=Math.max(1,Number(imageSource.width||1));
    const sourceHeight=Math.max(1,Number(imageSource.height||1));
    const longest=Math.max(sourceWidth,sourceHeight);
    let scale=1;
    if(longest>3800)scale=3800/longest;
    else if(longest<1900)scale=1900/longest;
    const maxPixels=12000000;
    if(sourceWidth*sourceHeight*scale*scale>maxPixels){
        scale=Math.sqrt(maxPixels/(sourceWidth*sourceHeight));
    }
    const canvas=document.createElement("canvas");
    canvas.width=Math.max(1,Math.round(sourceWidth*scale));
    canvas.height=Math.max(1,Math.round(sourceHeight*scale));
    const context=canvas.getContext("2d",{willReadFrequently:true});
    context.fillStyle="#fff";
    context.fillRect(0,0,canvas.width,canvas.height);
    context.imageSmoothingEnabled=true;
    context.imageSmoothingQuality="high";
    context.drawImage(imageSource,0,0,canvas.width,canvas.height);
    return canvas;
}


/* =========================================================
   OCR
========================================================= */

async function runDualOCR(
    originalCanvas,
    processedCanvas,
    label,
    returnDetailed=false
){
    const worker=await ppGetOCRWorkerPP();
    const autoPSM=Tesseract.PSM?.AUTO||"3";
    const sparsePSM=Tesseract.PSM?.SPARSE_TEXT||"11";
    const candidates=[];

    async function recognize(canvas,name,psm){
        ppOCRProgressLabelPP=`${label} — ${name}`;
        if(worker.setParameters){
            await worker.setParameters({
                tessedit_pageseg_mode:psm,
                preserve_interword_spaces:"1",
                user_defined_dpi:"300"
            });
        }
        const blob=await canvasToBlob(canvas);
        const result=await worker.recognize(
            blob,
            {},
            {text:true,blocks:true,tsv:true}
        );
        const text=String(result?.data?.text||"").trim();
        const rows=ppOCRBlocksToRowsPP(result?.data?.blocks);
        const confidence=Number(result?.data?.confidence||0);
        const score=ppScoreOCRTextPP(text)+Math.max(0,confidence)*0.15;
        candidates.push({text,rows,score,confidence,name});
    }

    await recognize(originalCanvas,"lecture naturelle",autoPSM);
    await recognize(processedCanvas,"contraste renforcé",autoPSM);

    let best=ppBestOCRCandidatePP(candidates);
    if(!best||best.score<45){
        await recognize(preprocessCanvas(originalCanvas,true),"noir et blanc",sparsePSM);
        best=ppBestOCRCandidatePP(candidates);
    }

    if(!best||best.score<35){
        const rotation=originalCanvas.width>originalCanvas.height?90:180;
        const rotated=ppRotateCanvasPP(processedCanvas,rotation);
        await recognize(rotated,`rotation ${rotation}°`,autoPSM);
        best=ppBestOCRCandidatePP(candidates);
        if(rotation===90&&(!best||best.score<35)){
            await recognize(ppRotateCanvasPP(processedCanvas,270),"rotation 270°",autoPSM);
            best=ppBestOCRCandidatePP(candidates);
        }
    }

    if(returnDetailed){
        return best||{text:"",rows:[],score:0,confidence:0,name:""};
    }
    return best?.text||"";
}

// Tesseract may split one visual table row into several text blocks.  Flatten
// every word and group it again by its vertical position so invoice columns
// (designation, quantity, unit price and amount) remain aligned.
function ppOCRBlocksToRowsPP(blocks){
    const words=[];
    (Array.isArray(blocks)?blocks:[]).forEach(block=>{
        (block?.paragraphs||[]).forEach(paragraph=>{
            (paragraph?.lines||[]).forEach(line=>{
                (line?.words||[]).forEach(word=>{
                    const box=word?.bbox||{};
                    const text=String(word?.text||"").trim();
                    const x0=Number(box.x0),x1=Number(box.x1);
                    const y0=Number(box.y0),y1=Number(box.y1);
                    if(!text||![x0,x1,y0,y1].every(Number.isFinite))return;
                    words.push({
                        text,
                        confidence:Number(word?.confidence||0),
                        x0,x1,y0,y1,
                        x:(x0+x1)/2,
                        y:(y0+y1)/2,
                        height:Math.max(1,y1-y0)
                    });
                });
            });
        });
    });
    if(!words.length)return [];

    const heights=words.map(word=>word.height).sort((a,b)=>a-b);
    const medianHeight=heights[Math.floor(heights.length/2)]||18;
    const tolerance=Math.max(6,medianHeight*0.55);
    const rows=[];
    words.sort((a,b)=>a.y-b.y||a.x0-b.x0).forEach(word=>{
        let row=null;
        let distance=Infinity;
        rows.forEach(candidate=>{
            const current=Math.abs(candidate.y-word.y);
            if(current<=tolerance&&current<distance){row=candidate;distance=current;}
        });
        if(!row){
            row={words:[],y:word.y,x0:word.x0,x1:word.x1};
            rows.push(row);
        }
        row.words.push(word);
        row.y=row.words.reduce((sum,item)=>sum+item.y,0)/row.words.length;
        row.x0=Math.min(row.x0,word.x0);
        row.x1=Math.max(row.x1,word.x1);
    });

    return rows
        .sort((a,b)=>a.y-b.y)
        .map(row=>{
            row.words.sort((a,b)=>a.x0-b.x0);
            return {
                text:row.words.map(word=>word.text).join(" ").replace(/\s+/g," ").trim(),
                words:row.words,
                y:row.y,
                x0:row.x0,
                x1:row.x1
            };
        })
        .filter(row=>row.text);
}

async function ppGetOCRWorkerPP(){
    if(ppOCRWorkerPP)return ppOCRWorkerPP;
    if(ppOCRWorkerPromisePP)return ppOCRWorkerPromisePP;
    if(typeof Tesseract==="undefined"||typeof Tesseract.createWorker!=="function"){
        throw new Error("Le moteur OCR Tesseract est indisponible.");
    }
    ppOCRWorkerPromisePP=(async()=>{
        const worker=await Tesseract.createWorker("fra+eng",1,{
            logger(message){
                if(message?.status==="recognizing text"){
                    const percent=Math.max(1,Math.min(99,Math.round(Number(message.progress||0)*100)));
                    showPDFTextProgress(`${ppOCRProgressLabelPP}...`,percent);
                }
            }
        });
        ppOCRWorkerPP=worker;
        return worker;
    })();
    try{return await ppOCRWorkerPromisePP;}
    catch(error){ppOCRWorkerPromisePP=null;ppOCRWorkerPP=null;throw error;}
}

function ppScoreOCRTextPP(text){
    const value=String(text||"").trim();
    if(!value)return 0;
    const letters=(value.match(/[A-Za-zÀ-ÿ]/g)||[]).length;
    const numbers=(value.match(/\d/g)||[]).length;
    const words=(value.match(/[A-Za-zÀ-ÿ]{3,}/g)||[]).length;
    const normalized=normalizeText(value);
    let score=Math.min(45,letters/8)+Math.min(25,numbers/2)+Math.min(20,words/2);
    ["facture","designation","article","quantite","prix","total","tva","ttc","ice"].forEach(keyword=>{
        if(normalized.includes(keyword))score+=8;
    });
    const replacementChars=(value.match(/[�]/g)||[]).length;
    score-=replacementChars*5;
    return Math.max(0,score);
}

function ppBestOCRCandidatePP(candidates){
    return [...(candidates||[])].sort((a,b)=>b.score-a.score||b.text.length-a.text.length)[0]||null;
}

function ppRotateCanvasPP(sourceCanvas,degrees){
    const swap=Math.abs(degrees)%180===90;
    const canvas=document.createElement("canvas");
    canvas.width=swap?sourceCanvas.height:sourceCanvas.width;
    canvas.height=swap?sourceCanvas.width:sourceCanvas.height;
    const ctx=canvas.getContext("2d");
    ctx.fillStyle="#fff";
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.translate(canvas.width/2,canvas.height/2);
    ctx.rotate(degrees*Math.PI/180);
    ctx.drawImage(sourceCanvas,-sourceCanvas.width/2,-sourceCanvas.height/2);
    return canvas;
}


/* =========================================================
   PREPROCESS
========================================================= */

function preprocessCanvas(sourceCanvas,binary=false){
    const canvas=document.createElement("canvas");
    canvas.width=sourceCanvas.width;
    canvas.height=sourceCanvas.height;
    const ctx=canvas.getContext("2d",{willReadFrequently:true});
    ctx.drawImage(sourceCanvas,0,0);
    const imageData=ctx.getImageData(0,0,canvas.width,canvas.height);
    const data=imageData.data;
    const histogram=new Uint32Array(256);
    for(let index=0;index<data.length;index+=4){
        const gray=Math.max(0,Math.min(255,Math.round(data[index]*0.299+data[index+1]*0.587+data[index+2]*0.114)));
        histogram[gray]++;
    }
    const pixels=Math.max(1,data.length/4);
    let low=0,high=255,total=0;
    const lowTarget=pixels*0.01,highTarget=pixels*0.99;
    for(let i=0;i<256;i++){total+=histogram[i];if(total<=lowTarget)low=i;if(total<highTarget)high=i;}
    if(high-low<45){low=Math.max(0,low-25);high=Math.min(255,high+25);}
    const threshold=ppOtsuThresholdPP(histogram,pixels);
    const span=Math.max(1,high-low);
    for(let index=0;index<data.length;index+=4){
        let gray=data[index]*0.299+data[index+1]*0.587+data[index+2]*0.114;
        gray=Math.max(0,Math.min(255,(gray-low)*255/span));
        gray=Math.round(255*Math.pow(gray/255,0.88));
        if(binary)gray=gray<Math.max(115,Math.min(220,threshold))?0:255;
        data[index]=data[index+1]=data[index+2]=gray;
        data[index+3]=255;
    }
    ctx.putImageData(imageData,0,0);
    return canvas;
}

function ppOtsuThresholdPP(histogram,totalPixels){
    let sum=0;
    for(let i=0;i<256;i++)sum+=i*histogram[i];
    let backgroundWeight=0,backgroundSum=0,maxVariance=0,threshold=180;
    for(let i=0;i<256;i++){
        backgroundWeight+=histogram[i];
        if(!backgroundWeight)continue;
        const foregroundWeight=totalPixels-backgroundWeight;
        if(!foregroundWeight)break;
        backgroundSum+=i*histogram[i];
        const meanBackground=backgroundSum/backgroundWeight;
        const meanForeground=(sum-backgroundSum)/foregroundWeight;
        const variance=backgroundWeight*foregroundWeight*Math.pow(meanBackground-meanForeground,2);
        if(variance>maxVariance){maxVariance=variance;threshold=i;}
    }
    return threshold;
}


function canvasToBlob(canvas){

    return new Promise(function(resolve){

        canvas.toBlob(

            resolve,

            "image/png",

            1

        );

    });

}


/* =========================================================
   FINISH SCAN
========================================================= */

function finishScan(){

    scannedInvoiceData =
        extractInvoiceData(
            scannedInvoiceText
        );


    renderScanResult();

}


/* =========================================================
   MAIN PARSER
========================================================= */

function extractInvoiceData(text){

    const clean =
        normalizeOCRText(
            text
        );


    let detectedProducts =
        [];


    let structuredTotals = {

        totalHT:
            0,

        tvaAmount:
            0,

        totalTTC:
            0

    };


    let structuredSupplier =
        "";


    let vatSummary =
        [];


    if(
        Array.isArray(
            scannedPDFPages
        )
        &&
        scannedPDFPages.length
    ){

        detectedProducts =
            extractProductsFromStructuredPDF(
                scannedPDFPages
            );


        structuredTotals =
            extractStructuredTotals(
                scannedPDFPages
            );


        structuredSupplier =
            extractHeaderSupplier(
                scannedPDFPages
            );


        vatSummary =
            extractStructuredVatSummary(
                scannedPDFPages
            );

    }


    if(!detectedProducts.length){
        const positionedProducts=extractProductsFromPositionedOCR(
            ppInvoiceLiveScanPages
        );
        const textProducts=extractProductsFromTextTable(clean);

        const reliableTextRows=textProducts.filter(
            product=>product?.ocrSource==="unit-column"
        ).length;

        // A unit-anchored text row is safer than raw coordinates for this
        // invoice layout: table totals can visually resemble product rows.
        // Prefer the text table when most rows are anchored by KG/UNITE/SAC;
        // retain positional OCR as a fallback for other supplier layouts.
        const reliableTextTable=
            reliableTextRows>=2
            &&
            reliableTextRows>=Math.ceil(textProducts.length*0.7);
        detectedProducts=reliableTextTable
            ?textProducts
            :(
                ppOCRProductSetScorePP(textProducts)>=ppOCRProductSetScorePP(positionedProducts)
                ?textProducts
                :positionedProducts
            );
    }


    const textTotalHT =
        extractTotalHT(
            clean
        );


    const textTVA =
        extractTVAAmount(
            clean
        );


    const textTTC =
        extractTotalTTC(
            clean
        );


    let totalHT =
        structuredTotals.totalHT
        ||
        textTotalHT;


    let tvaAmount =
        structuredTotals.tvaAmount
        ||
        textTVA;


    let totalTTC =
        structuredTotals.totalTTC
        ||
        textTTC;


    /*
       FALLBACK:
       if HT and TTC exist but TVA doesn't,
       calculate total TVA
    */

    if(
        !tvaAmount
        &&
        totalHT > 0
        &&
        totalTTC > 0
        &&
        totalTTC >= totalHT
    ){

        tvaAmount =
            roundMoney(
                totalTTC -
                totalHT
            );

    }


    /*
       If no per-product TVA is available,
       DON'T invent one.
       Keep product vatRate at 0,
       but keep real VAT summary separately.
    */


    return {

        number:
            extractInvoiceNumber(
                clean
            ),

        date:
            extractInvoiceDate(
                clean
            ),

        supplier:
            detectSupplier(
                clean,
                structuredSupplier
            ),

        detectedSupplierName:
            structuredSupplier
            ||
            extractSupplierName(
                clean
            ),

        totalHT:
            totalHT,

        tvaAmount:
            tvaAmount,

        totalTTC:
            totalTTC,

        vatSummary:
            vatSummary,

        products:
            detectedProducts,

        rawText:
            clean

    };

}


/* =========================================================
   HEADER SUPPLIER
========================================================= */

function extractHeaderSupplier(pages){
    const firstPage=pages?.[0]; if(!firstPage||!Array.isArray(firstPage.rows)) return "";
    const cities=["biougra","agadir","ait melloul","aït melloul","casablanca","marrakech","rabat","kenitra","kénitra","tanger","fes","fès","meknes","meknès","tetouan","tétouan","sale","salé"];
    const tableIndex=firstPage.rows.findIndex(r=>isTableHeader(normalizeText(r.text||""))); const limit=tableIndex>0?tableIndex:Math.min(firstPage.rows.length,25);
    const savedNames=suppliers.filter(s=>!isOurRestaurantName(normalizeText(s.name))).map(s=>({raw:s.name,norm:normalizeText(s.name)}));
    for(const row of firstPage.rows.slice(0,limit)){const norm=normalizeText(row.text||"");for(const s of savedNames){if(s.norm&&norm.includes(s.norm))return s.raw;}}
    const candidates=[];
    firstPage.rows.slice(0,limit).forEach((row,index)=>{const chunks=(row.columns||[]).map(c=>String(c.text||'').trim()).filter(Boolean);for(const chunk of chunks){const n=normalizeText(chunk);if(!n||n.length<3||isOurRestaurantName(n)||cities.includes(n)||looksLikeAddressLine(n)||isAdministrativeText(n)||/\d{2,}/.test(n)||/^(facture|client|adresse|tel|ice|if|rc|date)/.test(n))continue;let score=Math.max(0,35-index);if(chunk.length<=35)score+=20;if(chunk===chunk.toUpperCase()&&/[A-ZÀ-Ÿ]{4,}/.test(chunk))score+=35;if(/sarl|sarl au|soci[eé]t[eé]|\bste\b/i.test(chunk))score+=30;if(/novamar|gastromixte/i.test(chunk))score+=100;candidates.push({text:chunk,score});}}
    );
    candidates.sort((a,b)=>b.score-a.score); return candidates[0]?.text||"";
}


/* =========================================================
   ADDRESS DETECTION
========================================================= */

function looksLikeAddressLine(normalized){

    const words = [

        "route",
        "avenue",
        "boulevard",
        "quartier",
        "lot ",
        "lotissement",
        "zone industrielle",
        "bp ",
        "rue ",
        "km ",
        "hay ",
        "douar",
        "tel ",
        "tél ",
        "telephone",
        "téléphone",
        "mobile",
        "fax",
        "email",
        "e-mail",
        "ice ",
        "if ",
        "rc ",
        "patente"

    ];


    return words.some(function(word){

        return normalized.includes(
            normalizeText(
                word
            )
        );

    });

}


/* =========================================================
   STRUCTURED TVA SUMMARY
========================================================= */

function extractStructuredVatSummary(pages){

    const result =
        [];


    pages.forEach(function(page){

        if(
            !page
            ||
            !Array.isArray(
                page.rows
            )
        ){

            return;

        }


        let vatTableFound =
            false;


        page.rows.forEach(function(row,index){

            const normalized =
                normalizeText(
                    row.text
                );


            /*
               detect VAT summary header
            */

            if(
                normalized.includes(
                    "taux"
                )
                &&
                (
                    normalized.includes(
                        "tva"
                    )
                    ||
                    normalized.includes(
                        "base"
                    )
                )
            ){

                vatTableFound =
                    true;

                return;

            }


            if(!vatTableFound){

                return;

            }


            /*
               Stop when we leave summary block
            */

            if(
                normalized.includes(
                    "arretee"
                )
                ||
                normalized.includes(
                    "arrêtée"
                )
                ||
                normalized.includes(
                    "condition de paiement"
                )
                ||
                normalized.includes(
                    "references bancaires"
                )
            ){

                vatTableFound =
                    false;

                return;

            }


            const values =
                extractNumericValuesFromColumns(
                    row.columns
                );


            if(
                values.length <
                2
            ){

                return;

            }


            /*
               Find allowed VAT rate in this row
            */

            const rate =
                values.find(function(value){

                    return isAllowedVatRate(
                        value
                    );

                });


            if(
                rate ===
                undefined
            ){

                return;

            }


            let base =
                0;


            let amount =
                0;


            /*
               Common structure:
               Base | Taux | TVA
            */

            const remaining =
                values.filter(function(value){

                    return Number(
                        value
                    ) !==
                    Number(
                        rate
                    );

                });


            if(
                remaining.length >=
                1
            ){

                base =
                    remaining[0];

            }


            if(
                remaining.length >=
                2
            ){

                amount =
                    remaining[
                        remaining.length -
                        1
                    ];

            }


            if(
                base > 0
                ||
                amount > 0
            ){

                result.push({

                    rate:
                        Number(
                            rate
                        ),

                    base:
                        Number(
                            base
                        ),

                    amount:
                        Number(
                            amount
                        )

                });

            }

        });

    });


    return result;

}


/* =========================================================
   STRUCTURED TOTALS
========================================================= */

function extractStructuredTotals(pages){

    const result = {

        totalHT:
            0,

        tvaAmount:
            0,

        totalTTC:
            0

    };


    pages.forEach(function(page){

        page.rows.forEach(function(row,index){

            const normalized =
                normalizeText(
                    row.text
                );


            const values =
                extractNumericValuesFromColumns(
                    row.columns
                );


            if(
                normalized.includes(
                    "total ht"
                )
                &&
                values.length
            ){

                result.totalHT =
                    values[
                        values.length -
                        1
                    ];

            }


            if(
                (
                    normalized.includes(
                        "total tva"
                    )
                    ||
                    normalized.includes(
                        "montant tva"
                    )
                )
                &&
                values.length
            ){

                result.tvaAmount =
                    values[
                        values.length -
                        1
                    ];

            }


            if(
                (
                    normalized.includes(
                        "total ttc"
                    )
                    ||
                    normalized.includes(
                        "net a payer"
                    )
                    ||
                    normalized.includes(
                        "total a payer"
                    )
                )
                &&
                values.length
            ){

                result.totalTTC =
                    values[
                        values.length -
                        1
                    ];

            }


            if(
                normalized ===
                "total ht"
                &&
                !result.totalHT
            ){

                result.totalHT =
                    findAmountInNextRows(
                        page.rows,
                        index
                    );

            }


            if(
                normalized ===
                "total tva"
                &&
                !result.tvaAmount
            ){

                result.tvaAmount =
                    findAmountInNextRows(
                        page.rows,
                        index
                    );

            }


            if(
                (
                    normalized ===
                    "total ttc"
                    ||
                    normalized ===
                    "net a payer"
                )
                &&
                !result.totalTTC
            ){

                result.totalTTC =
                    findAmountInNextRows(
                        page.rows,
                        index
                    );

            }

        });

    });


    return result;

}


function findAmountInNextRows(
    rows,
    index
){

    for(
        let i = index + 1;
        i <= index + 3;
        i++
    ){

        if(!rows[i]){

            break;

        }


        const values =
            extractNumericValuesFromColumns(
                rows[i].columns
            );


        if(values.length){

            return values[
                values.length -
                1
            ];

        }

    }


    return 0;

}


function extractNumericValuesFromColumns(columns){

    return columns
        .map(function(column){

            const raw =
                String(
                    column.text ||
                    ""
                )
                .replace(
                    /\s/g,
                    ""
                )
                .replace(
                    /%/g,
                    ""
                )
                .trim();


            if(
                /^-?\d+(?:[.,]\d+)?$/.test(
                    raw
                )
            ){

                return parseNumber(
                    raw
                );

            }


            return null;

        })
        .filter(function(value){

            return value !==
                null;

        });

}


/* =========================================================
   STRUCTURED PRODUCTS
========================================================= */

function extractProductsFromStructuredPDF(pages){

    const result =
        [];


    let tableActive =
        false;


    pages.forEach(function(page){

        page.rows.forEach(function(row){

            const normalized =
                normalizeText(
                    row.text
                );


            if(
                isTableHeader(
                    normalized
                )
            ){

                tableActive =
                    true;

                return;

            }


            if(
                tableActive
                &&
                isProductTableEnd(
                    normalized
                )
            ){

                tableActive =
                    false;

                return;

            }


            if(!tableActive){

                return;

            }


            const product =
                parseStructuredPDFRow(
                    row.columns
                );


            if(product){

                result.push(
                    product
                );

            }

        });

    });


    return result;

}


function isTableHeader(normalized){
    const value=normalizeText(normalized);
    const hasName=/(designation|description|article|produit|libelle)/.test(value);
    const hasQuantity=/(quantite|qte|qty)/.test(value);
    const hasPrice=/(prix|p\s*[.]?\s*u|unitaire|montant)/.test(value);
    return hasName&&(hasQuantity||hasPrice);

}


function isProductTableEnd(normalized){

    return [

        "total ht",
        "total tva",
        "total ttc",
        "net a payer",
        "total a payer",
        "montant ht",
        "taux taxe",
        "t.v.a.",
        "tva",
        "base taux",
        "condition de paiement",
        "conditions de paiement",
        "references bancaires",
        "arretee"

    ]
    .some(function(value){

        return normalized.startsWith(
            normalizeText(
                value
            )
        );

    });

}


function parseStructuredPDFRow(columns){

    if(
        !Array.isArray(
            columns
        )
        ||
        columns.length <
        2
    ){

        return null;

    }


    const sorted =
        [...columns]
        .sort(function(a,b){

            return Number(
                a.x ||
                0
            )
            -
            Number(
                b.x ||
                0
            );

        });


    const fullLine =
        sorted
        .map(function(column){

            return String(
                column.text ||
                ""
            ).trim();

        })
        .join(
            " "
        );


    const normalized =
        normalizeText(
            fullLine
        );


    if(
        isAdministrativeText(
            normalized
        )
        ||
        isProductTableEnd(
            normalized
        )
    ){

        return null;

    }


    const numeric =
        sorted
        .map(function(column){

            const raw =
                String(
                    column.text ||
                    ""
                )
                .replace(
                    /\s/g,
                    ""
                )
                .trim();


            if(
                /^-?\d+(?:[.,]\d+)?%?$/.test(
                    raw
                )
            ){

                return {

                    x:
                        Number(
                            column.x ||
                            0
                        ),

                    raw:
                        raw,

                    value:
                        parseNumber(
                            raw
                        ),

                    isPercent:
                        raw.includes(
                            "%"
                        )

                };

            }


            return null;

        })
        .filter(Boolean);


    if(
        numeric.length <
        2
    ){

        return null;

    }


    const firstNumericX =
        Math.min(
            ...numeric.map(function(item){

                return item.x;

            })
        );


    const name =
        cleanProductName(

            sorted
            .filter(function(column){

                return (

                    Number(
                        column.x ||
                        0
                    )
                    <
                    firstNumericX

                    &&

                    /[A-Za-zÀ-ÿ]/.test(
                        column.text
                    )

                );

            })
            .map(function(column){

                return column.text;

            })
            .join(
                " "
            )

        );


    if(
        !isValidProductName(
            name
        )
    ){

        return null;

    }


    /*
       VAT is only accepted if it is clearly
       present in the product row.
       Otherwise 0 = unknown/not assigned.
    */

    let vatRate =
        0;


    const explicitPercent =
        numeric.find(function(item){

            return (

                item.isPercent

                &&

                isAllowedVatRate(
                    item.value
                )

            );

        });


    if(explicitPercent){

        vatRate =
            Number(
                explicitPercent.value
            );

    }


    let business =
        numeric.filter(function(item){

            return !item.isPercent;

        });


    /*
       If no explicit percentage:
       DO NOT treat random 20/14/10 value as TVA
       unless row is clearly a VAT-column invoice.
    */

    if(
        business.length <
        2
    ){

        return null;

    }


    const quantity =
        Number(
            business[0].value
        );


    const price =
        Number(
            business[1].value
        );


    if(
        quantity <= 0
        ||
        price < 0
    ){

        return null;

    }


    let totalHT =
        quantity *
        price;


    if(
        business.length >=
        3
        &&
        business[2].value >
        0
    ){

        totalHT =
            Number(
                business[2].value
            );

    }


    const vatAmount =
        totalHT *
        vatRate /
        100;


    const totalTTC =
        totalHT +
        vatAmount;


    return {

        name:
            name,

        quantity:
            quantity,

        unit:
            detectUnitFromText(
                fullLine
            ),

        price:
            price,

        vatRate:
            vatRate,

        // True only when a VAT percentage was explicitly present on this product row.
        vatDetected:
            Boolean(explicitPercent),

        vatAmount:
            vatAmount,

        totalHT:
            totalHT,

        totalTTC:
            totalTTC,

        category:
            guessCategory(
                name
            )

    };

}


/* =========================================================
   TEXT TABLE FALLBACK
========================================================= */

// Parse scanned invoices from the actual word positions returned by
// Tesseract.  This is more reliable than flattened OCR text because numbers
// keep their original quantity / unit-price / amount columns.
function ppOCRProductSetScorePP(items){
    return (Array.isArray(items)?items:[]).reduce((score,item)=>{
        const letters=(String(item?.name||"").match(/[A-Za-zÀ-ÿ]/g)||[]).length;
        const quantity=Number(item?.quantity||0);
        const price=Number(item?.price||0);
        const total=Number(item?.totalHT||0);
        return score
            +100
            +Math.min(20,letters)
            +(quantity>0?15:0)
            +(price>0?15:0)
            +(total>0?15:0);
    },0);
}

function extractProductsFromPositionedOCR(pages){
    const result=[];
    (Array.isArray(pages)?pages:[]).forEach(page=>{
        const rows=Array.isArray(page?.rows)?page.rows:[];
        if(!rows.length)return;

        let columns=null;
        let tableActive=false;
        let pendingName="";

        rows.forEach((row,rowIndex)=>{
            const normalized=normalizeText(row?.text||"");
            const nextRow=rows[rowIndex+1];
            const combinedHeaderRow=nextRow?{
                text:`${row?.text||""} ${nextRow?.text||""}`,
                words:[...(row?.words||[]),...(nextRow?.words||[])]
            }:row;
            const detectedColumns=
                ppDetectOCRTableColumnsPP(row)
                ||
                ppDetectOCRTableColumnsPP(combinedHeaderRow);
            if(detectedColumns){
                columns=detectedColumns;
                tableActive=true;
                pendingName="";
                return;
            }
            if(!tableActive||!columns)return;
            const partialHeaderRoles=(row?.words||[])
                .map(word=>ppOCRHeaderRolePP(word.text))
                .filter(Boolean);
            if(new Set(partialHeaderRoles).size>=2)return;
            if(isProductTableEnd(normalized)){
                tableActive=false;
                pendingName="";
                return;
            }
            if(ppLooksLikeNonProductDocumentRowPP(row?.text||"")){
                pendingName="";
                return;
            }

            let product=ppParsePositionedProductRowPP(row,columns);
            if(product){
                if(pendingName){
                    product.name=cleanProductName(`${pendingName} ${product.name}`);
                    product.category=guessCategory(product.name);
                }
                pendingName="";
                result.push(product);
                return;
            }

            const line=String(row?.text||"");
            const possibleName=cleanProductName(line);
            const letterCount=(possibleName.match(/[A-Za-zÀ-ÿ]/g)||[]).length;
            if(!/\d/.test(line)&&letterCount>=3&&isValidProductName(possibleName)){
                pendingName=possibleName;
            }
        });
    });
    return result;
}

function ppOCRHeaderRolePP(value){
    const normalized=normalizeText(value).replace(/[^a-z0-9]+/g,"");
    if(/(design|descript|articl|produ|libell)/.test(normalized))return "name";
    if(/^(q|qte|ate|qty|quant|quantite)$/.test(normalized)||normalized.startsWith("quant"))return "quantity";
    if(/^(prix|prlx|pu|puht|prixht|unitaire|prixunitaire)$/.test(normalized)||normalized.startsWith("unitair"))return "price";
    if(/^(montant|montantht|total|totalht|valeur)$/.test(normalized)||/^(montan|totai)/.test(normalized))return "amount";
    if(/^(tva|taxe|taux)$/.test(normalized))return "vat";
    if(/^(unite|unit|u|conditionnement)$/.test(normalized))return "unit";
    return "";
}

function ppDetectOCRTableColumnsPP(row){
    if(!row||!Array.isArray(row.words))return null;
    const rolePoints={};
    row.words.forEach(word=>{
        const role=ppOCRHeaderRolePP(word.text);
        if(!role)return;
        if(!rolePoints[role])rolePoints[role]=[];
        rolePoints[role].push(Number(word.x));
    });
    const anchors=Object.entries(rolePoints)
        .map(([role,points])=>({
            role,
            x:points.reduce((sum,value)=>sum+value,0)/points.length
        }))
        .filter(anchor=>Number.isFinite(anchor.x))
        .sort((a,b)=>a.x-b.x);
    const roles=new Set(anchors.map(anchor=>anchor.role));
    const numericRoleCount=["quantity","price","amount"].filter(role=>roles.has(role)).length;
    if(!roles.has("name")||numericRoleCount<2||(!roles.has("price")&&!roles.has("amount")))return null;
    return anchors;
}

function ppCellsFromOCRRowPP(row,columns){
    const cells={name:[],quantity:[],unit:[],price:[],vat:[],amount:[]};
    const anchors=[...(columns||[])].sort((a,b)=>a.x-b.x);
    if(!anchors.length)return cells;
    (row?.words||[]).forEach(word=>{
        const center=Number(word.x);
        let selected=anchors[0];
        for(let index=0;index<anchors.length-1;index++){
            const boundary=(anchors[index].x+anchors[index+1].x)/2;
            if(center<=boundary){selected=anchors[index];break;}
            selected=anchors[index+1];
        }
        if(cells[selected.role])cells[selected.role].push(word.text);
    });
    Object.keys(cells).forEach(key=>{cells[key]=cells[key].join(" ").trim();});
    return cells;
}

function ppCellNumbersPP(value){
    const text=String(value||"")
        .replace(/(\d)\s+([.,])\s*(\d)/g,"$1$2$3")
        .replace(/(\d)\s+(?=\d{3}(?:\D|$))/g,"$1");
    return [...text.matchAll(/-?\d+(?:[.,]\d+)?/g)]
        .map(match=>parseNumber(match[0]))
        .filter(number=>Number.isFinite(number));
}

function ppParsePositionedProductRowPP(row,columns){
    const fullLine=String(row?.text||"");
    if(ppLooksLikeNonProductDocumentRowPP(fullLine))return null;
    const cells=ppCellsFromOCRRowPP(row,columns);
    let name=cleanProductName(
        String(cells.name||"")
            .replace(/^\s*(?:[A-Z]{1,5}[-/.]?)?\d{3,}[A-Z0-9\-/.]*\s+/i,"")
    );
    if(!isValidProductName(name)||ppLooksLikeDocumentReferencePP(name,fullLine))return null;

    const quantities=ppCellNumbersPP(cells.quantity);
    const prices=ppCellNumbersPP(cells.price);
    const amounts=ppCellNumbersPP(cells.amount);
    let quantity=Number(quantities[0]||0);
    let price=Number(prices[0]||0);
    const explicitTotal=Number(amounts[amounts.length-1]||0);
    if(quantity<=0&&price>0&&explicitTotal>0)quantity=explicitTotal/price;
    if(price<=0&&quantity>0&&explicitTotal>0)price=explicitTotal/quantity;
    if(quantity<=0||quantity>1000000||price<0||price>10000000)return null;

    if(explicitTotal>0&&price>0){
        const calculated=quantity*price;
        const tolerance=Math.max(0.1,explicitTotal*0.06);
        if(Math.abs(calculated-explicitTotal)>tolerance){
            price=explicitTotal/quantity;
        }
    }

    const vatText=String(cells.vat||"");
    const vatMatch=vatText.match(/\b(0|7|10|14|20)(?:[.,]00)?\s*%?/);
    const vatRate=vatMatch?Number(vatMatch[1]):0;
    const totalHT=explicitTotal||quantity*price;
    const vatAmount=totalHT*vatRate/100;
    return {
        name,
        quantity,
        unit:detectUnitFromText(cells.unit||fullLine),
        price,
        vatRate,
        vatDetected:Boolean(vatMatch),
        vatAmount,
        totalHT,
        totalTTC:totalHT+vatAmount,
        category:guessCategory(name)
    };
}

function ppLooksLikeDocumentReferencePP(name,line){
    const value=String(name||"").trim();
    const compact=normalizeText(value).replace(/\s+/g,"");
    if(/^(?:fa|fac|fact|facture|bl|bc|devis|bon)[/#.\-]?\d/.test(compact))return true;
    if(/\b\d{1,2}[/.\-]\d{1,2}[/.\-](?:19|20)?\d{2}\b/.test(String(line||"")))return true;
    const letters=(value.match(/[A-Za-zÀ-ÿ]/g)||[]).length;
    const digits=(value.match(/\d/g)||[]).length;
    const separators=(value.match(/[/.#\-]/g)||[]).length;
    return separators>=2&&digits>=4&&letters<5;
}

function ppLooksLikeNonProductDocumentRowPP(line){
    const value=String(line||"").trim();
    const normalized=normalizeText(value).replace(/^[^a-z0-9]+/,"");
    if(!normalized)return true;
    if(isAdministrativeText(normalized)||looksLikeAddressLine(normalized))return true;
    // BL/BC references are allowed here because suppliers often print the
    // delivery-note number at the beginning of the first product row.
    if(/^(?:fa|fac|fact|facture|devis)[\s:/#.\-]*(?:n|no|numero)?[°ºo\s:/#.\-]*\d/i.test(value))return true;
    if(/\b(?:date|echeance|numero|facture|client|fournisseur|ice|if|rc)\b/.test(normalized))return true;
    if(/\b\d{1,2}[/.\-]\d{1,2}[/.\-](?:19|20)?\d{2}\b/.test(value))return true;
    return false;
}

function extractProductsFromTextTable(text){

    const pageChunks=String(text||"")
        .split(/^\s*=+\s*PAGE\s+\d+\s*=+\s*$/gmi)
        .map(chunk=>chunk.trim())
        .filter(Boolean);

    if(pageChunks.length>1){
        return pageChunks.flatMap(chunk=>extractProductsFromTextTable(chunk));
    }

    const lines =
        getCleanLines(
            text
        );


    let start =
        -1;


    let end =
        lines.length;


    for(
        let i = 0;
        i < lines.length;
        i++
    ){

        if(
            isTableHeader(
                normalizeText(
                    lines[i]
                )
            )
        ){

            start =
                i + 1;

            break;

        }

    }


    // OCR can deform a table header even when product rows remain readable.
    // In that case analyse all plausible rows instead of returning nothing.
    if(start === -1)start=0;


    for(
        let i = start;
        i < lines.length;
        i++
    ){

        if(
            isProductTableEnd(
                normalizeText(
                    lines[i]
                )
            )
        ){

            end =
                i;

            break;

        }

    }


    return lines
        .slice(
            start,
            end
        )
        .map(function(line){

            return parseTextProductLine(
                line
            );

        })
        .filter(Boolean);

}


function parseTextProductLine(line){

    const normalized =
        normalizeText(
            line
        );


    if(
        isAdministrativeText(
            normalized
        )
        ||
        looksLikeAddressLine(
            normalized
        )
        ||
        ppLooksLikeNonProductDocumentRowPP(
            line
        )
    ){

        return null;

    }


    // Scanned supplier invoices usually keep the unit column readable even
    // when table borders or decimal separators are damaged. Use that column
    // as a stable anchor before falling back to the generic number parser.
    const unitAnchoredProduct=ppParseUnitAnchoredOCRProductPP(line);
    if(unitAnchoredProduct)return unitAnchoredProduct;


    const matches =
        [...line.matchAll(
            /\d+(?:[.,]\d+)?%?/g
        )];


    if(
        matches.length <
        2
    ){

        return null;

    }


    const values =
        matches.map(function(match){

            return {

                value:
                    parseNumber(
                        match[0]
                    ),

                index:
                    match.index,

                raw:
                    match[0]

            };

        });

    const business=values.filter(value=>!String(value.raw).includes("%"));
    if(business.length<2)return null;

    let quantityItem=business[business.length-2];
    let priceItem=business[business.length-1];
    let detectedLineTotal=0;
    if(business.length>=3){
        const possibleQuantity=business[business.length-3];
        const possiblePrice=business[business.length-2];
        const possibleTotal=business[business.length-1];
        const calculated=Number(possibleQuantity.value)*Number(possiblePrice.value);
        const tolerance=Math.max(0.08,Math.abs(Number(possibleTotal.value))*0.04);
        if(calculated>0&&Math.abs(calculated-Number(possibleTotal.value))<=tolerance){
            quantityItem=possibleQuantity;
            priceItem=possiblePrice;
            detectedLineTotal=Number(possibleTotal.value);
        }
    }

    const name = cleanProductName(
        line.substring(0,quantityItem.index)
            .replace(/^\s*(?:[A-Z]{1,4}[-/.]?)?\d{3,}[A-Z0-9\-/.]*\s+/i,"")
    );


    if(
        !isValidProductName(
            name
        )
        ||
        ppLooksLikeDocumentReferencePP(
            name,
            line
        )
    ){

        return null;

    }


    let vatRate =
        0;


    const vatMatch =
        line.match(
            /\b(0|7|10|14|20)(?:[.,]00)?\s*%/
        );


    if(vatMatch){

        vatRate =
            Number(
                vatMatch[1]
            );

    }


    const quantity=Number(quantityItem.value);
    const price=Number(priceItem.value);
    if(quantity<=0||quantity>1000000||price<0||price>10000000)return null;
    const totalHT=detectedLineTotal||quantity*price;


    const vatAmount =
        totalHT *
        vatRate /
        100;


    return {

        name:
            name,

        quantity:
            quantity,

        unit:
            detectUnitFromText(
                line
            ),

        price:
            price,

        vatRate:
            vatRate,

        // True only when a VAT percentage was explicitly present on this product row.
        vatDetected:
            Boolean(vatMatch),

        vatAmount:
            vatAmount,

        totalHT:
            totalHT,

        totalTTC:
            totalHT +
            vatAmount,

        category:
            guessCategory(
                name
            )

    };

}

function ppOCRNumericTokensPP(value){
    const text=String(value||"");
    return [...text.matchAll(/-?\d{1,3}(?:[ .]\d{3})+(?:,\d+)?|-?\d+(?:[.,]\d+)?/g)]
        .map(match=>{
            let raw=String(match[0]||"").replace(/\s+/g,"");
            let normalized=raw;
            if(raw.includes(",")){
                normalized=raw.replace(/\./g,"").replace(",",".");
            }else if(/^\-?\d{1,3}(?:\.\d{3})+$/.test(raw)){
                normalized=raw.replace(/\./g,"");
            }
            const number=Number(normalized.replace(/[^0-9.-]/g,""));
            return {
                raw:match[0],
                index:Number(match.index||0),
                value:Number.isFinite(number)?number:0
            };
        });
}

function ppParseUnitAnchoredOCRProductPP(line){
    const value=String(line||"");
    const units=[...value.matchAll(/\b(KGS?|KG|LITRES?|LTR|ML|SACS?|UNITE(?:S)?|UNITÉ(?:S)?|PCS?|PI[EÈ]CES?|CTN|CARTONS?|PAQUETS?)\b/gi)];
    if(!units.length)return null;

    // The last unit is the invoice unit column. Earlier occurrences can be
    // part of a designation, e.g. "MAYONAISE JAP 1 KG ... 1 UNITE".
    const unitMatch=units[units.length-1];
    const left=value.slice(0,unitMatch.index);
    const right=value.slice(Number(unitMatch.index)+String(unitMatch[0]).length);
    const leftNumbers=ppOCRNumericTokensPP(left);
    const rightNumbers=ppOCRNumericTokensPP(right);
    if(!leftNumbers.length||!rightNumbers.length)return null;

    const quantityToken=leftNumbers[leftNumbers.length-1];
    let name=cleanProductName(
        left.slice(0,quantityToken.index)
            .replace(/\s+\d{1,2}\s*$/g,"")
            .replace(/[|‘’`~_—–-]+\s*$/g,"")
    )
        .replace(/\s+[‘’`'"]?\s*(?:mit|en)\.?\s*$/i,"")
        .replace(/[.,;:]+\s*$/g,"")
        .trim();
    if(!isValidProductName(name)||ppLooksLikeDocumentReferencePP(name,value))return null;

    let quantity=Number(quantityToken.value||0);
    const price=Number(rightNumbers[0]?.value||0);
    const explicitTotal=rightNumbers.length>=2
        ?Number(rightNumbers[rightNumbers.length-1]?.value||0)
        :0;
    if(price<=0||price>10000000)return null;

    // Repair OCR decimals such as "400| KG 60,00 240,00" (4,00 KG)
    // and "470| KG 240,00 1.128,00" (4,70 KG) from the line arithmetic.
    if(explicitTotal>0){
        const inferredQuantity=explicitTotal/price;
        if(inferredQuantity>0&&inferredQuantity<=1000000){
            quantity=Math.round(inferredQuantity*1000)/1000;
        }
    }
    if(quantity<=0||quantity>1000000)return null;

    const totalHT=explicitTotal||quantity*price;
    return {
        name,
        quantity,
        unit:detectUnitFromText(unitMatch[0]),
        price,
        vatRate:0,
        vatDetected:false,
        vatAmount:0,
        totalHT,
        totalTTC:totalHT,
        category:guessCategory(name),
        ocrSource:"unit-column"
    };
}


/* =========================================================
   SUPPLIER MATCHING
========================================================= */

function detectSupplier(
    text,
    detectedHeaderName = ""
){

    const normalizedText =
        normalizeText(
            text
        );


    const normalizedHeader =
        normalizeText(
            detectedHeaderName
        );


    /*
       First: match saved supplier with header name
    */

    if(normalizedHeader){

        const byHeader =
            suppliers.find(function(supplier){

                const name =
                    normalizeText(
                        supplier.name
                    );


                return (

                    name

                    &&

                    (
                        normalizedHeader.includes(
                            name
                        )

                        ||

                        name.includes(
                            normalizedHeader
                        )
                    )

                );

            });


        if(byHeader){

            return byHeader;

        }

    }


    /*
       Second: search full document,
       excluding our restaurant name
    */

    let best =
        null;


    let bestScore =
        0;


    suppliers.forEach(function(supplier){

        const name =
            normalizeText(
                supplier.name
            );


        if(
            !name
            ||
            isOurRestaurantName(
                name
            )
        ){

            return;

        }


        if(
            normalizedText.includes(
                name
            )
            &&
            name.length >
            bestScore
        ){

            best =
                supplier;

            bestScore =
                name.length;

        }

    });


    return best;

}


function extractSupplierName(text){

    const lines =
        getCleanLines(
            text
        );


    const candidates =
        lines
        .slice(
            0,
            15
        )
        .filter(function(line){

            const normalized =
                normalizeText(
                    line
                );


            return (

                !isOurRestaurantName(
                    normalized
                )

                &&

                !/(facture|invoice|avoir|bon de livraison)/.test(
                    normalized
                )

                &&

                !looksLikeAddressLine(
                    normalized
                )

                &&

                !isAdministrativeText(
                    normalized
                )

                &&

                /[A-Za-zÀ-ÿ]{3,}/.test(
                    line
                )

            );

        });


    if(!candidates.length){

        return "";

    }


    candidates.sort(function(a,b){

        return supplierCandidateScore(
            b
        )
        -
        supplierCandidateScore(
            a
        );

    });


    return cleanSupplierName(
        candidates[0]
    );

}


/* =========================================================
   INVOICE NUMBER + DATE
========================================================= */

function extractInvoiceNumber(text){

    const direct=String(text||"").match(
        /(?:facture|invoice)\s*(?:n(?:[°ºo]|umero)?|no|#)?\s*[:\-]?\s*([A-Z0-9][A-Z0-9/_.-]{2,})/i
    );

    if(direct&&/\d/.test(direct[1]))return direct[1];

    const lines =
        getCleanLines(
            text
        );


    for(
        let i = 0;
        i < lines.length - 1;
        i++
    ){

        const normalized =
            normalizeText(
                lines[i]
            );


        if(
            normalized.includes(
                "numero"
            )
            &&
            normalized.includes(
                "date"
            )
        ){

            const next =
                lines[
                    i + 1
                ];


            const date =
                next.match(
                    /\b\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}\b/
                );


            const beforeDate =
                date
                ?
                next.substring(
                    0,
                    date.index
                )
                :
                next;


            const matches =
                beforeDate.match(
                    /[A-Z0-9][A-Z0-9\/_.-]{2,}/gi
                )
                ||
                [];


            for(
                const candidate
                of matches
            ){

                if(
                    /\d/.test(
                        candidate
                    )
                ){

                    return candidate;

                }

            }

        }

    }


    const fa =
        text.match(
            /\bFA[\/\-][A-Z0-9\/_.-]+\b/i
        );


    if(fa){

        return fa[0];

    }


    return "";

}


function extractInvoiceDate(text){

    const match =
        text.match(
            /\b([0-3]?\d[\/.-][01]?\d[\/.-]\d{4})\b/
        );


    return match
        ?
        match[1]
        :
        "";

}


/* =========================================================
   TEXT TOTALS FALLBACK
========================================================= */

function extractTotalHT(text){

    return extractNamedAmount(
        text,
        [
            "TOTAL HT",
            "MONTANT HT"
        ]
    );

}


function extractTVAAmount(text){

    return extractNamedAmount(
        text,
        [
            "TOTAL TVA",
            "MONTANT TVA",
            "T.V.A.",
            "TVA"
        ]
    );

}


function extractTotalTTC(text){

    return extractNamedAmount(
        text,
        [
            "TOTAL TTC",
            "NET A PAYER",
            "TOTAL A PAYER"
        ]
    );

}


function extractNamedAmount(
    text,
    labels
){

    const lines =
        getCleanLines(
            text
        );


    for(
        const line
        of lines
    ){

        const normalized =
            normalizeText(
                line
            );


        if(
            labels.some(function(label){

                return normalized.includes(
                    normalizeText(
                        label
                    )
                );

            })
        ){

            const numbers =
                line.match(
                    /\d[\d\s]*(?:[.,]\d+)?/g
                )
                ||
                [];


            if(numbers.length){

                return parseNumber(
                    numbers[
                        numbers.length -
                        1
                    ]
                );

            }

        }

    }


    return 0;

}


/* =========================================================
   SCAN RESULT
========================================================= */

function renderScanResult(){

    const preview =
        document.getElementById(
            "scanPreview"
        );


    if(!preview){

        return;

    }

    const livePageCount=ppInvoiceLiveScanPages.length;
    const rawOCRText=String(scannedInvoiceText||"").trim();
    const hasUsefulData=Boolean(
        scannedInvoiceData.products.length||scannedInvoiceData.number||scannedInvoiceData.date||
        scannedInvoiceData.totalHT||scannedInvoiceData.tvaAmount||scannedInvoiceData.totalTTC
    );


    const supplierName =
        scannedInvoiceData.supplier
        ?
        scannedInvoiceData.supplier.name
        :
        scannedInvoiceData.detectedSupplierName
        ||
        "Non détecté";


    const vatSummaryDisplay =
        scannedInvoiceData.vatSummary
        &&
        scannedInvoiceData.vatSummary.length
        ?
        scannedInvoiceData.vatSummary
            .map(function(item){

                return (
                    item.rate
                    +
                    "%"
                );

            })
            .join(
                " / "
            )
        :
        buildVatSummary(
            scannedInvoiceData.products
        );


    preview.innerHTML = `

        <div class="scan-result">

            <h3>
                ✅ Facture analysée
            </h3>

            ${livePageCount?`
                <div class="pp-ocr-pages-guidance">
                    <strong>${livePageCount} page(s) intégrée(s).</strong>
                    Si la facture continue, cliquez sur « Scanner la page suivante » avant d'utiliser les informations.
                </div>
            `:""}

            ${!hasUsefulData?`
                <div class="pp-ocr-warning">
                    ⚠️ L'OCR a lu ${rawOCRText.length} caractère(s), mais aucune donnée fiable n'a été reconnue.
                    Vérifiez l'aperçu de la page, le sens du document et le réglage 300 DPI.
                </div>
            `:""}


            <div class="ocr-summary">

                <p>
                    <strong>Fournisseur :</strong>
                    ${escapeHTML(supplierName)}
                </p>

                <p>
                    <strong>N° Facture :</strong>
                    ${
                        escapeHTML(
                            scannedInvoiceData.number ||
                            "Non détecté"
                        )
                    }
                </p>

                <p>
                    <strong>Date :</strong>
                    ${
                        escapeHTML(
                            scannedInvoiceData.date ||
                            "Non détectée"
                        )
                    }
                </p>

                <p>
                    <strong>Produits détectés :</strong>
                    ${scannedInvoiceData.products.length}
                </p>

                <p>
                    <strong>TVA détectée :</strong>
                    ${escapeHTML(vatSummaryDisplay)}
                </p>

                <p>
                    <strong>Total HT détecté :</strong>
                    ${
                        scannedInvoiceData.totalHT
                        ?
                        formatMoney(
                            scannedInvoiceData.totalHT
                        )
                        :
                        "Non détecté"
                    }
                </p>

                <p>
                    <strong>Total TVA détecté :</strong>
                    ${
                        scannedInvoiceData.tvaAmount
                        ?
                        formatMoney(
                            scannedInvoiceData.tvaAmount
                        )
                        :
                        "Non détecté"
                    }
                </p>

                <p>
                    <strong>Total TTC détecté :</strong>
                    ${
                        scannedInvoiceData.totalTTC
                        ?
                        formatMoney(
                            scannedInvoiceData.totalTTC
                        )
                        :
                        "Non détecté"
                    }
                </p>

            </div>


            <div class="ocr-products-block">

                <strong>
                    Produits détectés :
                </strong>


                <div class="ocr-products-list">

                    ${
                        scannedInvoiceData.products.length
                        ? scannedInvoiceData.products
                        .map(function(product){

                            return `

                                <div class="ocr-product-item">

                                    <strong>
                                        ${escapeHTML(product.name)}
                                    </strong>

                                    <br>

                                    Quantité :

                                    ${formatNumber(product.quantity)}

                                    ${escapeHTML(product.unit)}

                                    —

                                    PU HT :

                                    ${formatMoney(product.price)}

                                    ${
                                        product.vatRate > 0
                                        ?
                                        `— TVA : ${product.vatRate}%`
                                        :
                                        ""
                                    }

                                </div>

                            `;

                        })
                        .join("")
                        : `<div class="ocr-product-item">Aucun article détecté sur les pages analysées.</div>`
                    }

                </div>

            </div>

            <details class="pp-ocr-details">
                <summary>Afficher le texte réellement lu par l'OCR (${rawOCRText.length} caractères)</summary>
                <div class="ocr-raw-text">${escapeHTML(rawOCRText||"Aucun texte lu.")}</div>
            </details>


            <button
                type="button"
                class="btn primary"
                style="margin-top:18px;"
                onclick="useScannedInvoiceData()"
                ${hasUsefulData?"":"disabled"}
            >

                ➕ Utiliser ces informations

            </button>

        </div>

    `;

}


/* =========================================================
   IMPORT SCAN DATA
========================================================= */

function useScannedInvoiceData(){

    if(!scannedInvoiceData){

        return;

    }


    const data =
        scannedInvoiceData;


    /*
       Determine a reliable default VAT rate for OCR lines.
       Some supplier PDFs expose VAT only in the totals/summary,
       not on each product row. In that case we infer the rate from
       Total TVA / Total HT and fall back to the detected VAT summary.
    */
    const supportedVatRates = [0, 7, 10, 14, 20];

    let detectedDefaultVatRate = 0;

    if(
        Number(data.totalHT) > 0
        &&
        Number(data.tvaAmount) >= 0
    ){

        const effectiveRate =
            Number(data.tvaAmount)
            /
            Number(data.totalHT)
            *
            100;

        const nearestRate = supportedVatRates.reduce(function(best, rate){

            return Math.abs(rate - effectiveRate) < Math.abs(best - effectiveRate)
                ? rate
                : best;

        }, supportedVatRates[0]);

        if(Math.abs(nearestRate - effectiveRate) <= 0.75){

            detectedDefaultVatRate = nearestRate;

        }

    }

    if(
        !detectedDefaultVatRate
        &&
        Array.isArray(data.vatSummary)
        &&
        data.vatSummary.length
    ){

        const validRates = data.vatSummary
            .map(function(item){ return Number(item.rate); })
            .filter(function(rate){ return supportedVatRates.includes(rate); });

        if(validRates.length === 1){

            detectedDefaultVatRate = validRates[0];

        }

    }

    if(!detectedDefaultVatRate){

        detectedDefaultVatRate = parseNumber(
            getValue(
                "invoiceTVARate"
            )
        );

    }


    closeModal(
        "scanModal"
    );


    openInvoiceModal();


    if(document.getElementById("invoiceTVARate")){

        setValue(
            "invoiceTVARate",
            detectedDefaultVatRate
        );

    }


    if(data.number){

        setValue(
            "invoiceNumber",
            data.number
        );

    }


    if(data.date){

        const converted =
            convertDateToInput(
                data.date
            );


        if(converted){

            setValue(
                "invoiceDate",
                converted
            );

        }

    }


    if(data.supplier){

        setValue(
            "invoiceSupplier",
            data.supplier.id
        );

    }


    if(
        data.products.length
    ){

        document.getElementById(
            "invoiceLines"
        ).innerHTML =
            "";


        data.products.forEach(function(product){

            const existing =
                findProductByName(
                    product.name
                );


            addInvoiceLine({

                productId:
                    existing
                    ?
                    existing.id
                    :
                    null,

                name:
                    existing
                    ?
                    existing.name
                    :
                    product.name,

                category:
                    existing
                    ?
                    existing.category
                    :
                    product.category,

                unit:
                    existing
                    ?
                    existing.unit
                    :
                    product.unit,

                quantity:
                    product.quantity,

                price:
                    product.price,

                vatRate:
                    Number(product.vatRate) > 0
                    ?
                    Number(product.vatRate)
                    :
                    detectedDefaultVatRate

            });

        });

    }


    updateInvoiceTotals();

}


/* =========================================================
   HELPERS
========================================================= */

function findProductByName(name){

    const normalized =
        normalizeText(
            name
        );


    return products.find(function(product){

        return normalizeText(
            product.name
        )
        ===
        normalized;

    })
    ||
    null;

}



function ppNormalizeInvoiceDesignationPP(value){
    return normalizeText(
        cleanProductName(value || "")
    )
    .replace(/[^a-z0-9]+/g," ")
    .replace(/\s+/g," ")
    .trim();
}

function ppInvoiceAliasesForProductPP(product){
    if(!product)return [];
    if(!Array.isArray(product.invoiceAliases))product.invoiceAliases=[];
    return product.invoiceAliases;
}

function ppRememberInvoiceAliasPP(product, designation, supplierId){
    if(!product)return false;
    const raw=String(designation||"").trim();
    const normalized=ppNormalizeInvoiceDesignationPP(raw);
    const canonical=ppNormalizeInvoiceDesignationPP(product.name);
    if(!normalized || normalized===canonical)return false;

    const supplierKey=Number(supplierId)||null;
    const aliases=ppInvoiceAliasesForProductPP(product);
    const existing=aliases.find(alias=>
        ppNormalizeInvoiceDesignationPP(alias?.designation||alias?.name||alias?.normalized||"")===normalized
        && (Number(alias?.supplierId)||null)===supplierKey
    );

    if(existing){
        existing.designation=raw;
        existing.normalized=normalized;
        existing.updatedAt=new Date().toISOString();
        return false;
    }

    aliases.push({
        supplierId:supplierKey,
        designation:raw,
        normalized,
        updatedAt:new Date().toISOString()
    });
    return true;
}

function ppFindProductByInvoiceAliasPP(designation, supplierId){
    const normalized=ppNormalizeInvoiceDesignationPP(designation);
    if(!normalized)return null;
    const supplierKey=Number(supplierId)||null;

    // Prefer an alias learned from this exact supplier.
    for(const product of products){
        const aliases=ppInvoiceAliasesForProductPP(product);
        const found=aliases.find(alias=>{
            const aliasNormalized=ppNormalizeInvoiceDesignationPP(
                alias?.designation||alias?.name||alias?.normalized||""
            );
            return aliasNormalized===normalized
                && (Number(alias?.supplierId)||null)===supplierKey;
        });
        if(found)return product;
    }

    // Fallback for aliases saved before the supplier was known.
    for(const product of products){
        const aliases=ppInvoiceAliasesForProductPP(product);
        const found=aliases.find(alias=>{
            const aliasNormalized=ppNormalizeInvoiceDesignationPP(
                alias?.designation||alias?.name||alias?.normalized||""
            );
            return aliasNormalized===normalized
                && !Number(alias?.supplierId);
        });
        if(found)return product;
    }

    // When OCR did not recognize the supplier, accept the alias only when it
    // points unambiguously to one stock article across all suppliers.
    const anySupplierMatches=products.filter(product=>
        ppInvoiceAliasesForProductPP(product).some(alias=>
            ppNormalizeInvoiceDesignationPP(
                alias?.designation||alias?.name||alias?.normalized||""
            )===normalized
        )
    );
    if(anySupplierMatches.length===1)return anySupplierMatches[0];

    return null;
}

function ppFindProductByInvoiceDesignationPP(designation, supplierId){
    const exact=findProductByName(designation);
    if(exact)return exact;

    const learned=ppFindProductByInvoiceAliasPP(designation,supplierId);
    if(learned)return learned;

    // Conservative automatic match: all words of one existing article must
    // appear as complete words in the scanned designation, and the result
    // must be unique. Example: "Surimi bâtonnet" -> "Surimi".
    const scanned=ppNormalizeInvoiceDesignationPP(designation);
    if(!scanned)return null;
    const scannedTokens=new Set(scanned.split(" ").filter(token=>token.length>=3));
    const candidates=products.filter(product=>{
        const canonical=ppNormalizeInvoiceDesignationPP(product.name);
        const tokens=canonical.split(" ").filter(token=>token.length>=3);
        return tokens.length>0 && tokens.every(token=>scannedTokens.has(token));
    });

    if(candidates.length===1)return candidates[0];
    return null;
}

function cleanProductName(name){

    return String(
        name ||
        ""
    )
    // Remove delivery-note / BL references accidentally captured before the designation.
    // Examples: "BL26-05157 SURIMI...", "BL 26/05157 - SURIMI...", "BL N° 2605157 SURIMI...".
    .replace(
        /^\s*B\.?\s*L\.?\s*(?:N(?:[°ºo]|O)?\s*)?[A-Z0-9][A-Z0-9\-\/.]*\s*[-:–—]?\s*/i,
        ""
    )
    .replace(
        /^[^A-Za-zÀ-ÿ0-9]+/,
        ""
    )
    .replace(
        /[^A-Za-zÀ-ÿ0-9()\-_'\/,.% ]+$/g,
        ""
    )
    .replace(
        /\s+/g,
        " "
    )
    .trim();

}


function isValidProductName(name){

    const normalized =
        normalizeText(
            name
        );


    if(
        !normalized
        ||
        normalized.length <
        2
        ||
        (String(name||"").match(/[A-Za-zÀ-ÿ]/g)||[]).length<2
    ){

        return false;

    }


    return !isAdministrativeText(
        normalized
    );

}


function detectUnitFromText(text){

    const match =
        String(
            text ||
            ""
        )
        .match(
            /\b(KG|KGS?|G|L|LTR|LITRE|ML|SACS?|PCS?|PC|PI[EÈ]CES?|UNITE|UNITÉ|UNITES|UNITÉS|CTN|CARTONS?|PAQUETS?)\b/i
        );


    if(!match){

        return "pièce";

    }


    return normalizeUnit(
        match[1]
    );

}


function normalizeUnit(unit){

    const value =
        normalizeText(
            unit
        );


    if(
        value === "kg"
        ||
        value === "kgs"
    ){

        return "kg";

    }


    if(value === "g"){

        return "g";

    }


    if(
        value === "l"
        ||
        value === "ltr"
        ||
        value === "litre"
    ){

        return "L";

    }


    if(value === "ml"){

        return "ml";

    }


    if(value === "sac"||value === "sacs"){

        return "sac";

    }


    if(
        value.includes(
            "carton"
        )
        ||
        value === "ctn"
    ){

        return "carton";

    }


    return "pièce";

}


function guessCategory(name){

    const value =
        normalizeText(
            name
        );


    if(
        [
            "saumon",
            "thon",
            "crevette",
            "poisson",
            "calamar",
            "surimi",
            "moule",
            "rascasse",
            "anchois",
            "poulpe"
        ]
        .some(function(word){

            return value.includes(
                word
            );

        })
    ){

        return "Poissons";

    }


    if(
        value.includes(
            "mozzarella"
        )
        ||
        value.includes(
            "fromage"
        )
        ||
        value.includes(
            "lait"
        )
    ){

        return "Produits laitiers";

    }


    return "Épicerie";

}


function deduplicateScannedProducts(items){

    const groups =
        new Map();


    (items || []).forEach(function(item){

        if(!item){
            return;
        }


        const cleanedName =
            cleanProductName(
                item.name || ""
            );


        if(!cleanedName){
            return;
        }


        const quantity =
            Number(item.quantity || 0);


        const unit =
            item.unit || "pièce";


        const vatRate =
            Number(item.vatRate || 0);


        const vatDetected =
            item.vatDetected === true;


        /*
           Same designation + same unit = same article.
           If OCR explicitly detected two different VAT rates for the same
           designation, keep them separate to avoid changing invoice VAT.
        */
        const baseKey =
            normalizeText(cleanedName)
            + "||"
            + normalizeText(unit);


        let key =
            baseKey;


        if(vatDetected){

            const existingSameArticle =
                [...groups.entries()]
                .find(function(entry){

                    return entry[1].baseKey === baseKey;

                });


            if(
                existingSameArticle
                &&
                existingSameArticle[1].vatDetected
                &&
                Number(existingSameArticle[1].vatRate) !== vatRate
            ){

                key =
                    baseKey
                    + "||vat:"
                    + vatRate;

            }

        }


        const lineHT =
            Number.isFinite(Number(item.totalHT))
            &&
            Number(item.totalHT) >= 0
            ?
            Number(item.totalHT)
            :
            quantity * Number(item.price || 0);


        const lineVatAmount =
            Number.isFinite(Number(item.vatAmount))
            ?
            Number(item.vatAmount)
            :
            lineHT * vatRate / 100;


        if(!groups.has(key)){

            groups.set(key,{
                ...item,
                name:cleanedName,
                quantity:quantity,
                price:quantity > 0 ? lineHT / quantity : Number(item.price || 0),
                totalHT:lineHT,
                vatRate:vatRate,
                vatDetected:vatDetected,
                vatAmount:lineVatAmount,
                totalTTC:lineHT + lineVatAmount,
                baseKey:baseKey
            });

            return;

        }


        const current =
            groups.get(key);


        const newQuantity =
            Number(current.quantity || 0)
            +
            quantity;


        const newTotalHT =
            Number(current.totalHT || 0)
            +
            lineHT;


        const newVatAmount =
            Number(current.vatAmount || 0)
            +
            lineVatAmount;


        current.quantity =
            newQuantity;


        // Weighted average: total value / total quantity.
        current.price =
            newQuantity > 0
            ?
            newTotalHT / newQuantity
            :
            0;


        current.totalHT =
            newTotalHT;


        current.vatAmount =
            newVatAmount;


        current.totalTTC =
            newTotalHT + newVatAmount;


        // Prefer an explicitly detected VAT over an unknown row.
        if(!current.vatDetected && vatDetected){
            current.vatRate = vatRate;
            current.vatDetected = true;
        }


        // Keep the most useful metadata when one duplicate row has it.
        if(
            (!current.category || current.category === "Autre")
            &&
            item.category
        ){
            current.category = item.category;
        }

    });


    return [...groups.values()]
        .map(function(item){

            const copy = {...item};
            delete copy.baseKey;
            return copy;

        });

}


function isAdministrativeText(normalized){
    const value=normalizeText(normalized).replace(/^[^a-z0-9]+/i,"");
    return [

        "total",
        "facture",
        "numero",
        "numéro",
        "date",
        "page",
        "client",
        "adresse",
        "telephone",
        "téléphone",
        "ice",
        "siege social",
        "siège social",
        "capital",
        "condition de paiement",
        "references bancaires"

    ]
    .some(function(prefix){
        const normalizedPrefix=normalizeText(prefix);
        if(value===normalizedPrefix)return true;
        const next=value.charAt(normalizedPrefix.length);
        return value.startsWith(normalizedPrefix)
            &&
            (!next||/[^a-z0-9]/i.test(next));

    });

}


function isAllowedVatRate(value){

    return [
        0,
        7,
        10,
        14,
        20
    ]
    .includes(
        Number(
            value
        )
    );

}


function buildVatSummary(list){

    const rates =
        [
            ...new Set(

                list
                    .map(function(product){

                        return Number(
                            product.vatRate ||
                            0
                        );

                    })
                    .filter(function(rate){

                        return rate >
                            0;

                    })

            )
        ]
        .sort(function(a,b){

            return a -
                b;

        });


    return rates.length
        ?
        rates
        .map(function(rate){

            return rate +
                "%";

        })
        .join(
            " / "
        )
        :
        "Non détectée";

}


function isOurRestaurantName(normalized){

    return (

        normalized.includes(
            "pause plate"
        )

        ||

        normalized.includes(
            "pause & plate"
        )

        ||

        normalized.includes(
            "pause and plate"
        )

    );

}


function supplierCandidateScore(text){

    const normalized =
        normalizeText(
            text
        );


    let score =
        0;


    if(
        normalized.includes(
            "sarl"
        )
        ||
        normalized.includes(
            "societe"
        )
    ){

        score +=
            30;

    }


    if(
        text.length <=
        40
    ){

        score +=
            20;

    }


    if(
        isOurRestaurantName(
            normalized
        )
    ){

        score -=
            200;

    }


    return score;

}


function cleanSupplierName(value){

    return String(
        value ||
        ""
    )
    .replace(
        /\|/g,
        " "
    )
    .replace(
        /\s+/g,
        " "
    )
    .trim();

}



