/* =========================================================
   GENERIC HELPERS
========================================================= */

function createId(){

    return Date.now()
        +
        Math.floor(
            Math.random() *
            1000000
        );

}


function getValue(id){

    return String(
        document
        .getElementById(
            id
        )
        ?.value
        ??
        ""
    );

}


function setValue(
    id,
    value
){

    const element =
        document.getElementById(
            id
        );


    if(element){

        element.value =
            value;

    }

}


function setText(
    id,
    value
){

    const element =
        document.getElementById(
            id
        );


    if(element){

        element.textContent =
            value;

    }

}


function formatMoney(value){

    return Number(
        value ||
        0
    )
    .toLocaleString(
        "fr-FR",
        {

            minimumFractionDigits:
                2,

            maximumFractionDigits:
                2

        }
    )
    +
    " DH";

}


function formatNumber(value){

    return Number(
        value ||
        0
    )
    .toLocaleString(
        "fr-FR",
        {

            maximumFractionDigits:
                4

        }
    );

}


function formatDate(value){

    if(!value){

        return "-";

    }


    const date =
        new Date(
            value
        );


    if(
        Number.isNaN(
            date.getTime()
        )
    ){

        return value;

    }


    return date.toLocaleDateString(
        "fr-FR"
    );

}


function parseNumber(value){

    let text =
        String(
            value ??
            ""
        )
        .trim()
        .replace(
            /%/g,
            ""
        )
        .replace(
            /\s/g,
            ""
        );


    if(
        text.includes(
            "."
        )
        &&
        text.includes(
            ","
        )
    ){

        if(
            text.lastIndexOf(
                ","
            )
            >
            text.lastIndexOf(
                "."
            )
        ){

            text =
                text
                .replace(
                    /\./g,
                    ""
                )
                .replace(
                    ",",
                    "."
                );

        }
        else{

            text =
                text.replace(
                    /,/g,
                    ""
                );

        }

    }
    else{

        text =
            text.replace(
                ",",
                "."
            );

    }


    return Number(
        text.replace(
            /[^0-9.-]/g,
            ""
        )
    )
    ||
    0;

}


function normalizeOCRText(text){

    return String(
        text ||
        ""
    )
    .replace(
        /\r/g,
        ""
    )
    .replace(
        /\u00A0/g,
        " "
    );

}


function normalizeText(value){

    return String(
        value ||
        ""
    )
    .normalize(
        "NFD"
    )
    .replace(
        /[\u0300-\u036f]/g,
        ""
    )
    .toLowerCase()
    .replace(
        /\|/g,
        " "
    )
    .replace(
        /\s+/g,
        " "
    )
    .trim();

}


function getCleanLines(text){

    return String(
        text ||
        ""
    )
    .split(
        "\n"
    )
    .map(function(line){

        return line
            .replace(
                /\|/g,
                " "
            )
            .replace(
                /\s+/g,
                " "
            )
            .trim();

    })
    .filter(Boolean);

}


function convertDateToInput(value){

    const parts =
        String(
            value ||
            ""
        )
        .split(
            /[\/.-]/
        );


    if(
        parts.length !==
        3
    ){

        return "";

    }


    return (

        parts[2]

        +

        "-"

        +

        parts[1]
        .padStart(
            2,
            "0"
        )

        +

        "-"

        +

        parts[0]
        .padStart(
            2,
            "0"
        )

    );

}


function roundMoney(value){

    return Math.round(
        Number(
            value ||
            0
        )
        *
        100
    )
    /
    100;

}


function escapeHTML(value){

    return String(
        value ??
        ""
    )
    .replace(
        /&/g,
        "&amp;"
    )
    .replace(
        /</g,
        "&lt;"
    )
    .replace(
        />/g,
        "&gt;"
    )
    .replace(
        /"/g,
        "&quot;"
    )
    .replace(
        /'/g,
        "&#039;"
    );

}


function sleep(ms){

    return new Promise(function(resolve){

        setTimeout(
            resolve,
            ms
        );

    });

}


