function ppNormalizeTreasuryTransferPP(raw={}){
    return {
        id:raw.id??createId(),
        type:'cash-deposit',
        date:String(raw.date||'').slice(0,10),
        amount:Math.max(Number(raw.amount||0),0),
        reference:String(raw.reference||''),
        bankName:String(raw.bankName||''),
        note:String(raw.note||''),
        createdAt:raw.createdAt||new Date().toISOString(),
        updatedAt:raw.updatedAt||raw.createdAt||new Date().toISOString()
    };
}

function ppBankModeLabelPP(mode){
    const value=String(mode||'').trim();
    return value||'Opération bancaire';
}

function ppBankSourceLabelDetailedPP(source){
    const labels={
        'supplier-payment':'Règlement fournisseur',
        'client-payment':'Encaissement client',
        'sale-payment':'Encaissement vente',
        'expense-payment':'Règlement dépense',
        'cash-deposit':'Versement espèces',
        'manual':'Écriture manuelle',
        'opening':'Solde d’ouverture'
    };
    return labels[source]||'Opération banque';
}

function ppLinkedBankRowsPP(){
    const matchedKeys=new Set(bankStatementTransactionsPP.filter(tx=>tx.matchedAccountingKey).map(tx=>String(tx.matchedAccountingKey)));
    const rows=[];
    ppAccountingJournalPP().forEach(entry=>{
        entry.lines.forEach((line,index)=>{
            if(String(line.account)!=='5141')return;
            const amount=Number(line.debit||0)-Number(line.credit||0);
            if(Math.abs(amount)<0.005)return;
            const key=`${String(entry.id)}::${index}`;
            rows.push({
                key,date:entry.date,journal:entry.journal||'BQ',piece:entry.piece||'',label:line.label||entry.label||'',
                entryLabel:entry.label||'',source:entry.source||'manual',sourceId:entry.sourceId,amount,
                matched:matchedKeys.has(key)
            });
        });
    });
    return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.piece).localeCompare(String(a.piece),'fr'));
}

let ppBankJournalStatusFilterPP='';
function ppSetBankJournalStatusPP(value){ppBankJournalStatusFilterPP=String(value||'');renderAccountingPP();}

function ppFilteredLinkedBankRowsPP(){
    const {from,to}=ppAccountingRangePP(),query=normalizeText(getValue('ppAccSearch'));
    const status=ppBankJournalStatusFilterPP;
    return ppLinkedBankRowsPP().filter(row=>{
        if(from&&row.date<from)return false;if(to&&row.date>to)return false;
        if(status==='matched'&&!row.matched)return false;if(status==='unmatched'&&row.matched)return false;
        if(query&&!normalizeText(`${row.piece} ${row.label} ${row.entryLabel} ${ppBankSourceLabelDetailedPP(row.source)}`).includes(query))return false;
        return true;
    });
}

function renderLinkedBankJournalPP(){
    ensureTreasuryTransferModalPP();
    const rows=ppFilteredLinkedBankRowsPP(),incoming=rows.filter(r=>r.amount>0).reduce((s,r)=>s+r.amount,0),outgoing=-rows.filter(r=>r.amount<0).reduce((s,r)=>s+r.amount,0),unmatched=rows.filter(r=>!r.matched);
    const balance=ppAccountingTreasuryBalancePP('5141',ppAccountingRangePP().to);
    return `<div class="pp-acc-toolbar"><div><h3 style="margin:0">🏦 Journal banque</h3></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" onclick="openTreasuryTransferPP()">➕ Versement espèces</button><button class="btn print" onclick="printLinkedBankJournalPP()">🖨️ Imprimer</button></div></div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin-bottom:16px">
        <div class="stat-card" style="padding:15px"><small>Solde banque actuel</small><strong style="display:block;font-size:22px">${formatMoney(balance)}</strong></div>
        <div class="stat-card" style="padding:15px"><small>Entrées période</small><strong class="pp-acc-positive" style="display:block;font-size:22px">${formatMoney(incoming)}</strong></div>
        <div class="stat-card" style="padding:15px"><small>Sorties période</small><strong class="pp-acc-negative" style="display:block;font-size:22px">${formatMoney(outgoing)}</strong></div>
        <div class="stat-card" style="padding:15px"><small>À rapprocher</small><strong style="display:block;font-size:22px">${unmatched.length}</strong></div>
      </div>
      <div class="pp-acc-panel"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px"><h3 style="margin:0">Toutes les opérations liées</h3><select id="ppBankJournalStatus" onchange="ppSetBankJournalStatusPP(this.value)" style="max-width:240px"><option value="" ${!ppBankJournalStatusFilterPP?'selected':''}>Tous les statuts</option><option value="unmatched" ${ppBankJournalStatusFilterPP==='unmatched'?'selected':''}>À rapprocher</option><option value="matched" ${ppBankJournalStatusFilterPP==='matched'?'selected':''}>Rapprochées</option></select></div><table style="min-width:1050px"><thead><tr><th>Date</th><th>Origine</th><th>Pièce / Référence</th><th>Libellé</th><th>Entrée</th><th>Sortie</th><th>Rapprochement</th><th></th></tr></thead><tbody>${rows.map(row=>`<tr><td>${formatDate(row.date)}</td><td><strong>${escapeHTML(ppBankSourceLabelDetailedPP(row.source))}</strong></td><td>${escapeHTML(row.piece||'-')}</td><td>${escapeHTML(row.entryLabel||row.label||'-')}</td><td class="pp-acc-positive">${row.amount>0?formatMoney(row.amount):'-'}</td><td class="pp-acc-negative">${row.amount<0?formatMoney(-row.amount):'-'}</td><td>${row.matched?'<span class="pp-bank-status matched">✓ Rapprochée</span>':'<span class="pp-bank-status unmatched">À rapprocher</span>'}</td><td>${row.source==='cash-deposit'?`<div class="action-buttons"><button class="btn small edit" onclick="openTreasuryTransferPP('${row.sourceId}')">✏️</button><button class="btn small danger" onclick="deleteTreasuryTransferPP('${row.sourceId}')">🗑️</button></div>`:''}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Aucune opération bancaire sur cette période.</td></tr>'}</tbody></table></div>
      <div style="font-size:12px;color:#667085;background:#f8fafc;border:1px solid #e4e7ec;border-radius:12px;padding:12px">Les paiements en espèces restent dans la caisse. Seul le versement espèces transfère le montant de la caisse vers la banque, sans créer de produit ni de charge.</div>`;
}

function ensureTreasuryTransferModalPP(){
    if(document.getElementById('ppTreasuryTransferModal'))return;
    const modal=document.createElement('div');modal.id='ppTreasuryTransferModal';modal.className='modal-overlay';
    modal.innerHTML=`<div class="modal"><div class="modal-header"><h2 id="ppTreasuryTransferTitle">🏦 Versement espèces en banque</h2><button onclick="closeModal('ppTreasuryTransferModal')">×</button></div><form id="ppTreasuryTransferForm"><input type="hidden" id="ppTreasuryTransferId"><div class="form-grid"><div><label>Date *</label><input id="ppTreasuryTransferDate" type="date" required></div><div><label>Montant *</label><input id="ppTreasuryTransferAmount" type="number" min="0.01" step="0.01" required></div><div><label>Banque / compte</label><input id="ppTreasuryTransferBank" placeholder="Ex. Attijariwafa bank"></div><div><label>Référence bordereau</label><input id="ppTreasuryTransferRef" placeholder="N° bordereau / remise"></div></div><div><label>Observation</label><textarea id="ppTreasuryTransferNote" rows="2"></textarea></div><div style="padding:10px 12px;background:#f4faf7;border:1px solid #cfe6da;border-radius:10px;margin-top:12px;font-size:13px">Écriture automatique : <strong>Débit Banque 5141 / Crédit Caisse 5161</strong>.</div><div class="modal-actions"><button type="button" class="btn" onclick="closeModal('ppTreasuryTransferModal')">Annuler</button><button type="submit" class="btn primary">Enregistrer le versement</button></div></form></div>`;
    document.body.appendChild(modal);document.getElementById('ppTreasuryTransferForm').addEventListener('submit',event=>{event.preventDefault();saveTreasuryTransferPP();});
}

function openTreasuryTransferPP(id=null){
    ensureTreasuryTransferModalPP();const item=id?treasuryTransfersPP.find(x=>String(x.id)===String(id)):null;
    setText('ppTreasuryTransferTitle',item?'✏️ Modifier le versement':'🏦 Versement espèces en banque');
    setValue('ppTreasuryTransferId',item?.id||'');setValue('ppTreasuryTransferDate',item?.date||new Date().toISOString().slice(0,10));setValue('ppTreasuryTransferAmount',item?.amount||'');setValue('ppTreasuryTransferBank',item?.bankName||'');setValue('ppTreasuryTransferRef',item?.reference||'');setValue('ppTreasuryTransferNote',item?.note||'');openModal('ppTreasuryTransferModal');
}

function saveTreasuryTransferPP(){
    const id=getValue('ppTreasuryTransferId')||null,amount=Math.max(Number(getValue('ppTreasuryTransferAmount')||0),0),date=getValue('ppTreasuryTransferDate');
    if(!date||!(amount>0)){alert('Saisissez la date et un montant supérieur à 0.');return;}
    const old=id?treasuryTransfersPP.find(x=>String(x.id)===String(id)):null,now=new Date().toISOString();
    const item=ppNormalizeTreasuryTransferPP({id:old?.id||createId(),date,amount,bankName:getValue('ppTreasuryTransferBank').trim(),reference:getValue('ppTreasuryTransferRef').trim(),note:getValue('ppTreasuryTransferNote').trim(),createdAt:old?.createdAt||now,updatedAt:now});
    if(old){const index=treasuryTransfersPP.findIndex(x=>String(x.id)===String(id));treasuryTransfersPP[index]=item;}else treasuryTransfersPP.unshift(item);
    saveData();closeModal('ppTreasuryTransferModal');renderAccountingPP();
}

function deleteTreasuryTransferPP(id){
    const item=treasuryTransfersPP.find(x=>String(x.id)===String(id));if(!item||!confirm('Supprimer ce versement espèces ? La banque et la caisse seront recalculées automatiquement.'))return;
    treasuryTransfersPP=treasuryTransfersPP.filter(x=>String(x.id)!==String(id));saveData();renderAccountingPP();
}

function printLinkedBankJournalPP(){
    const rows=ppFilteredLinkedBankRowsPP(),body=rows.map(row=>`<tr><td>${formatDate(row.date)}</td><td>${escapeHTML(ppBankSourceLabelDetailedPP(row.source))}</td><td>${escapeHTML(row.piece||'-')}</td><td>${escapeHTML(row.entryLabel||row.label||'-')}</td><td>${row.amount>0?formatMoney(row.amount):'-'}</td><td>${row.amount<0?formatMoney(-row.amount):'-'}</td><td>${row.matched?'Rapprochée':'À rapprocher'}</td></tr>`).join('');
    printDocument('Journal banque lié',`<div class="doc-head"><h1>Pause & Plate</h1><p>Journal banque</p></div><table><thead><tr><th>Date</th><th>Origine</th><th>Pièce</th><th>Libellé</th><th>Entrée</th><th>Sortie</th><th>Statut</th></tr></thead><tbody>${body||'<tr><td colspan="7">Aucune opération.</td></tr>'}</tbody></table>`);
}

function ppScheduleStatusPP(dueDate,remaining){
    const date=String(dueDate||'').slice(0,10),today=ppTodayISOPP();if(remaining<=0.005)return {code:'paid',label:'Soldée',days:0};
    if(!date)return {code:'undated',label:'Sans échéance',days:null};
    if(date<today){const days=ppDaysBetweenISOPP(date,today);return {code:'overdue',label:`En retard de ${days} j`,days:-days};}
    if(date===today)return {code:'today',label:"Échéance aujourd’hui",days:0};
    const days=ppDaysBetweenISOPP(today,date);return days<=7?{code:'soon',label:`Dans ${days} j`,days}:{code:'upcoming',label:`Dans ${days} j`,days};
}

function ppScheduleRowsPP(){
    const rows=[];
    invoices.forEach(inv=>{const info=ppInvoiceDeadlineInfoPP(inv),status=ppScheduleStatusPP(info.dueDate,info.remaining);rows.push({id:`supplier:${inv.id}`,kind:'supplier',flow:'payable',type:'Facture fournisseur',party:inv.supplierName||'-',number:inv.number||'-',date:inv.date,dueDate:info.dueDate,total:info.total,paid:info.paid,remaining:info.remaining,status,sourceId:inv.id});});
    expensesPP.forEach(expense=>{const totals=ppExpensePaymentTotalsPP(expense),dueDate=String(expense.dueDate||expense.date||'').slice(0,10),status=ppScheduleStatusPP(dueDate,totals.due);rows.push({id:`expense:${expense.id}`,kind:'expense',flow:'payable',type:'Dépense / charge',party:expense.beneficiary||expense.category||'-',number:expense.reference||`DEP-${expense.id}`,date:expense.date,dueDate,total:totals.total,paid:totals.paid,remaining:totals.due,status,sourceId:expense.id});});
    clientInvoicesPP.forEach(inv=>{const total=Math.max(Number(inv.totalTTC||0),0),paid=Math.min(Math.max(Number(inv.paid||0),0),total),remaining=Math.max(total-paid,0),dueDate=String(inv.dueDate||inv.date||'').slice(0,10),status=ppScheduleStatusPP(dueDate,remaining);rows.push({id:`client:${inv.id}`,kind:'client',flow:'receivable',type:'Facture client',party:inv.clientName||'-',number:inv.number||'-',date:inv.date,dueDate,total,paid,remaining,status,sourceId:inv.id});});
    return rows.sort((a,b)=>String(a.dueDate||'9999').localeCompare(String(b.dueDate||'9999'))||String(a.party).localeCompare(String(b.party),'fr'));
}

let ppScheduleFiltersPP={flow:'',kind:'',status:'',from:'',to:'',search:''};
function ppSetScheduleFilterPP(field,value){if(Object.prototype.hasOwnProperty.call(ppScheduleFiltersPP,field))ppScheduleFiltersPP[field]=String(value||'');renderAccountingPP();}

function ppFilteredScheduleRowsPP(){
    const {flow,kind,status,from,to,search}=ppScheduleFiltersPP,q=normalizeText(search);
    return ppScheduleRowsPP().filter(row=>{
        if(flow&&row.flow!==flow)return false;if(kind&&row.kind!==kind)return false;if(status&&row.status.code!==status)return false;
        if(from&&row.dueDate&&row.dueDate<from)return false;if(to&&row.dueDate&&row.dueDate>to)return false;
        if(q&&!normalizeText(`${row.party} ${row.number} ${row.type}`).includes(q))return false;return true;
    });
}

function ppScheduleBadgePP(status){
    const classes={paid:'success',overdue:'danger',today:'warning',soon:'warning',upcoming:'info',undated:'warning'};return `<span class="status ${classes[status.code]||'info'}">${escapeHTML(status.label)}</span>`;
}

function renderUnifiedSchedulePP(){
    const rows=ppFilteredScheduleRowsPP(),open=rows.filter(r=>r.remaining>0.005),payables=open.filter(r=>r.flow==='payable'),receivables=open.filter(r=>r.flow==='receivable'),overduePay=payables.filter(r=>r.status.code==='overdue'),overdueReceive=receivables.filter(r=>r.status.code==='overdue'),soon=open.filter(r=>['today','soon'].includes(r.status.code));
    return `<div class="pp-acc-toolbar"><div><h3 style="margin:0">📅 État d’échéancier</h3></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn print" onclick="printUnifiedSchedulePP()">🖨️ Imprimer</button><button class="btn" onclick="exportUnifiedScheduleExcelPP()">📊 Excel</button></div></div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:16px"><div class="stat-card" style="padding:15px"><small>À décaisser</small><strong class="pp-acc-negative" style="display:block;font-size:21px">${formatMoney(payables.reduce((s,r)=>s+r.remaining,0))}</strong></div><div class="stat-card" style="padding:15px"><small>À encaisser</small><strong class="pp-acc-positive" style="display:block;font-size:21px">${formatMoney(receivables.reduce((s,r)=>s+r.remaining,0))}</strong></div><div class="stat-card" style="padding:15px"><small>Retards fournisseurs / charges</small><strong style="display:block;font-size:21px;color:#b42318">${formatMoney(overduePay.reduce((s,r)=>s+r.remaining,0))}</strong></div><div class="stat-card" style="padding:15px"><small>Retards clients</small><strong style="display:block;font-size:21px;color:#b42318">${formatMoney(overdueReceive.reduce((s,r)=>s+r.remaining,0))}</strong></div><div class="stat-card" style="padding:15px"><small>Échéances ≤ 7 jours</small><strong style="display:block;font-size:21px">${soon.length}</strong></div></div>
      <div class="pp-acc-filters" style="display:grid"><div><label>Flux</label><select id="ppScheduleFlow" onchange="ppSetScheduleFilterPP('flow',this.value)"><option value="" ${!ppScheduleFiltersPP.flow?'selected':''}>À payer + à encaisser</option><option value="payable" ${ppScheduleFiltersPP.flow==='payable'?'selected':''}>À décaisser</option><option value="receivable" ${ppScheduleFiltersPP.flow==='receivable'?'selected':''}>À encaisser</option></select></div><div><label>Nature</label><select id="ppScheduleKind" onchange="ppSetScheduleFilterPP('kind',this.value)"><option value="" ${!ppScheduleFiltersPP.kind?'selected':''}>Toutes</option><option value="supplier" ${ppScheduleFiltersPP.kind==='supplier'?'selected':''}>Factures fournisseurs</option><option value="expense" ${ppScheduleFiltersPP.kind==='expense'?'selected':''}>Dépenses / charges</option><option value="client" ${ppScheduleFiltersPP.kind==='client'?'selected':''}>Factures clients</option></select></div><div><label>Situation</label><select id="ppScheduleStatus" onchange="ppSetScheduleFilterPP('status',this.value)"><option value="" ${!ppScheduleFiltersPP.status?'selected':''}>Toutes</option><option value="overdue" ${ppScheduleFiltersPP.status==='overdue'?'selected':''}>En retard</option><option value="today" ${ppScheduleFiltersPP.status==='today'?'selected':''}>Aujourd’hui</option><option value="soon" ${ppScheduleFiltersPP.status==='soon'?'selected':''}>≤ 7 jours</option><option value="upcoming" ${ppScheduleFiltersPP.status==='upcoming'?'selected':''}>À venir</option><option value="paid" ${ppScheduleFiltersPP.status==='paid'?'selected':''}>Soldées</option><option value="undated" ${ppScheduleFiltersPP.status==='undated'?'selected':''}>Sans échéance</option></select></div><div><label>Échéance du</label><input id="ppScheduleFrom" type="date" value="${escapeHTML(ppScheduleFiltersPP.from)}" onchange="ppSetScheduleFilterPP('from',this.value)"></div><div><label>Au</label><input id="ppScheduleTo" type="date" value="${escapeHTML(ppScheduleFiltersPP.to)}" onchange="ppSetScheduleFilterPP('to',this.value)"></div><div><label>Recherche</label><input id="ppScheduleSearch" value="${escapeHTML(ppScheduleFiltersPP.search)}" placeholder="Tiers, facture, référence…" oninput="ppSetScheduleFilterPP('search',this.value)"></div></div>
      <div class="pp-acc-panel"><table style="min-width:1250px"><thead><tr><th>Flux</th><th>Nature</th><th>Tiers</th><th>Pièce</th><th>Date</th><th>Échéance</th><th>Total</th><th>Réglé / encaissé</th><th>Reste</th><th>Situation</th><th>Action</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${row.flow==='payable'?'<span class="status danger">À décaisser</span>':'<span class="status success">À encaisser</span>'}</td><td>${escapeHTML(row.type)}</td><td><strong>${escapeHTML(row.party)}</strong></td><td>${escapeHTML(row.number)}</td><td>${formatDate(row.date)}</td><td><strong>${row.dueDate?formatDate(row.dueDate):'-'}</strong></td><td>${formatMoney(row.total)}</td><td>${formatMoney(row.paid)}</td><td class="${row.flow==='payable'?'pp-acc-negative':'pp-acc-positive'}"><strong>${formatMoney(row.remaining)}</strong></td><td>${ppScheduleBadgePP(row.status)}</td><td>${row.kind==='supplier'?`<button class="btn small view" onclick="viewInvoice(${row.sourceId})">👁️</button>`:row.kind==='expense'?`<button class="btn small edit" onclick="openExpensePP(${row.sourceId})">✏️</button>`:`<button class="btn small edit" onclick="openClientInvoicePP(${row.sourceId})">✏️</button>`}</td></tr>`).join('')||'<tr><td colspan="11" class="empty">Aucune échéance pour les filtres sélectionnés.</td></tr>'}</tbody></table></div>`;
}

function printUnifiedSchedulePP(){
    const rows=ppFilteredScheduleRowsPP(),body=rows.map(row=>`<tr><td>${row.flow==='payable'?'À décaisser':'À encaisser'}</td><td>${escapeHTML(row.type)}</td><td>${escapeHTML(row.party)}</td><td>${escapeHTML(row.number)}</td><td>${formatDate(row.date)}</td><td>${row.dueDate?formatDate(row.dueDate):'-'}</td><td>${formatMoney(row.total)}</td><td>${formatMoney(row.paid)}</td><td>${formatMoney(row.remaining)}</td><td>${escapeHTML(row.status.label)}</td></tr>`).join('');
    printDocument('État d’échéancier',`<div class="doc-head"><h1>Pause & Plate</h1><p>État d’échéancier</p></div><table><thead><tr><th>Flux</th><th>Nature</th><th>Tiers</th><th>Pièce</th><th>Date</th><th>Échéance</th><th>Total</th><th>Réglé</th><th>Reste</th><th>Situation</th></tr></thead><tbody>${body||'<tr><td colspan="10">Aucune échéance.</td></tr>'}</tbody></table>`);
}

function exportUnifiedScheduleExcelPP(){
    if(typeof XLSX==='undefined'){alert('La bibliothèque Excel n’est pas chargée.');return;}const rows=ppFilteredScheduleRowsPP().map(row=>({Flux:row.flow==='payable'?'À décaisser':'À encaisser',Nature:row.type,Tiers:row.party,Piece:row.number,Date:row.date,Echeance:row.dueDate,Total:row.total,Regle_Encaisse:row.paid,Reste:row.remaining,Situation:row.status.label}));
    const sheet=XLSX.utils.json_to_sheet(rows),book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,sheet,'Echeancier');XLSX.writeFile(book,`echeancier-${ppTodayISOPP()}.xlsx`);
}

let ppAuth = null;
let ppDb = null;
let ppCurrentUser = null;
let ppCurrentRole = "admin";
let ppCloudReady = false;
let ppCloudSaveTimer = null;
let ppCloudSaving = false;
let ppCloudListeners = [];
let ppApplyingCloudState = false;
let ppCloudDirty = false;
let ppCloudSaveAgain = false;
let ppCloudChangeVersion = 0;
let ppCloudBaseState = {};
let ppCloudProfileSignature = "";

const PP_CLOUD_DATASETS = {
    products: () => products,
    movements: () => movements,
    suppliers: () => suppliers,
    invoices: () => invoices,
    supplierPayments: () => supplierPaymentsPP,
    clients: () => clientsPP,
    clientInvoices: () => clientInvoicesPP,
    clientPayments: () => clientPaymentsPP,
    sales: () => salesPP,
    expenses: () => expensesPP,
    recipes: () => recipesPP,
    dailySalesScans: () => dailySalesScansPP,
    accountingEntries: () => accountingEntriesPP,
    accountingSettings: () => accountingSettingsPP,
    bankStatementTransactions: () => bankStatementTransactionsPP,
    bankReconciliations: () => bankReconciliationsPP,
    treasuryTransfers: () => treasuryTransfersPP
};

// Employees only receive the datasets required by the two modules that can be
// delegated to them.  Everything else stays admin-only, both in the browser
// and in Firestore Security Rules.
const PP_EMPLOYEE_CLOUD_DATASETS = {
    stock: ["products", "movements"],
    expenses: ["expenses"]
};

function ppFirebaseAvailable(){
    return typeof firebase !== "undefined" && firebase.apps !== undefined;
}

function ppDataDoc(key){
    return ppDb.collection("companies").doc(PP_COMPANY_ID).collection("data").doc(key);
}

function ppMetaDoc(){
    return ppDb.collection("companies").doc(PP_COMPANY_ID).collection("meta").doc("app");
}

function ppUserDoc(uid){
    return ppDb.collection("users").doc(uid);
}

function ppUsernameToAuthEmail(username){
    const u=String(username||"").trim().toLowerCase();
    if(!u)return "";
    // Keep admin simple: username "admin" uses the existing real Firebase admin account.
    if(u==="admin" || u==="asma" || u==="asmaabd1987-ui")return PP_ADMIN_EMAIL;
    // Backward-compatible: an email can still be used by the administrator if needed.
    if(u.includes("@"))return u;
    // Employees never see this internal technical email.
    const safe=u.replace(/[^a-z0-9._-]/g,"").replace(/^[._-]+|[._-]+$/g,"");
    return safe ? `${safe}@pauseplate-employee.com` : "";
}

function ppShowLogin(message=""){
    let overlay=document.getElementById("ppFirebaseLogin");
    if(!overlay){
        overlay=document.createElement("div");
        overlay.id="ppFirebaseLogin";
        overlay.innerHTML=`
          <div class="pp-cloud-login-card">
            <div class="pp-cloud-logo">Pause & Plate</div>
            <div class="pp-cloud-subtitle">MANAGER — Connexion</div>
            <form id="ppCloudLoginForm">
              <label>Utilisateur</label>
              <input id="ppCloudUsername" type="text" autocomplete="username" placeholder="Ex: admin, ahmed, stock1" required>
              <label>Mot de passe</label>
              <input id="ppCloudPassword" type="password" autocomplete="current-password" required>
              <div id="ppCloudLoginMessage" class="pp-cloud-message"></div>
              <button class="btn primary" type="submit">Se connecter</button>
            </form>
          </div>`;
        document.body.appendChild(overlay);
        document.getElementById("ppCloudUsername").value=localStorage.getItem("pause_plate_last_username")||"admin";
        document.getElementById("ppCloudLoginForm").addEventListener("submit",async e=>{
            e.preventDefault();
            const username=getValue("ppCloudUsername").trim();
            const email=ppUsernameToAuthEmail(username);
            const password=getValue("ppCloudPassword");
            const msg=document.getElementById("ppCloudLoginMessage");
            if(!email){msg.textContent="Nom d'utilisateur invalide.";return;}
            msg.textContent="Connexion...";
            try{
                localStorage.setItem("pause_plate_last_username",username);
                await ppAuth.signInWithEmailAndPassword(email,password);
            }catch(err){
                console.error(err);
                msg.textContent=ppFriendlyAuthError(err);
            }
        });
    }
    const msg=document.getElementById("ppCloudLoginMessage");
    if(msg)msg.textContent=message;
    overlay.style.display="flex";
    document.querySelector(".app")?.classList.add("pp-cloud-locked");
}

function ppHideLogin(){
    const overlay=document.getElementById("ppFirebaseLogin");
    if(overlay)overlay.style.display="none";
    document.querySelector(".app")?.classList.remove("pp-cloud-locked");
}

function ppFriendlyAuthError(err){
    const code=String(err?.code||"");
    if(code.includes("invalid-credential")||code.includes("wrong-password")||code.includes("user-not-found")) return "Utilisateur ou mot de passe incorrect.";
    if(code.includes("too-many-requests")) return "Trop de tentatives. Réessayez plus tard.";
    if(code.includes("network")) return "Connexion internet indisponible.";
    return "Connexion impossible: "+(err?.message||"Erreur inconnue");
}

function ppAddCloudHeader(){
    const profile=document.querySelector(".profile");
    if(!profile||document.getElementById("ppCloudUserBox"))return;
    const box=document.createElement("div");
    box.id="ppCloudUserBox";
    box.className="pp-cloud-user-box";
    box.innerHTML=`<span id="ppCloudStatus">☁️ Cloud</span><small id="ppCloudUser"></small><button type="button" onclick="ppLogout()">Déconnexion</button>`;
    profile.parentNode?.insertBefore(box,profile);
}

async function ppLogout(){
    if(ppAuth)await ppAuth.signOut();
}

async function ppEnsureUserProfile(user){
    const profileRef=ppDb.collection("userProfiles").doc(user.uid);
    const legacyRef=ppUserDoc(user.uid);
    let profile=null;

    try{
        const snap=await profileRef.get();
        if(snap.exists)profile=snap.data()||{};
    }catch(_){}

    if(!profile){
        const legacySnap=await legacyRef.get();
        if(legacySnap.exists)profile=legacySnap.data()||{};
    }

    if(!profile){
        const isAdmin=String(user.email||"").toLowerCase()===PP_ADMIN_EMAIL.toLowerCase();
        profile={
            name:isAdmin?"Admin":"Utilisateur",
            username:isAdmin?"admin":"",
            email:user.email||"",
            role:isAdmin?"admin":"employee",
            active:true,
            permissions:{stock:true,expenses:true,shiftClosings:isAdmin}
        };
        await profileRef.set({
            ...profile,
            createdAt:firebase.firestore.FieldValue.serverTimestamp()
        },{merge:true});
        await legacyRef.set({
            email:user.email||"",
            role:profile.role,
            active:true,
            createdAt:firebase.firestore.FieldValue.serverTimestamp()
        },{merge:true});
    }

    if(profile.active===false){
        await ppAuth.signOut();
        throw new Error("Ce compte est désactivé. Contactez l’administrateur.");
    }

    ppCurrentRole=String(profile.role||"employee");
    ppCurrentUserProfile={
        ...profile,
        role:ppCurrentRole,
        permissions:profile.permissions||(ppCurrentRole==="admin"?{stock:true,expenses:true,shiftClosings:true}:{stock:false,expenses:false,shiftClosings:false})
    };
    ppCloudProfileSignature=ppProfileScopeSignaturePP(ppCurrentUserProfile);

    // Keep last login trace.
    try{
        await profileRef.set({
            lastLoginAt:firebase.firestore.FieldValue.serverTimestamp()
        },{merge:true});
    }catch(_){}
}

function ppProfileScopeSignaturePP(profile){
    const value=profile||{};
    return JSON.stringify({
        role:String(value.role||"employee"),
        active:value.active!==false,
        deleted:value.deleted===true,
        name:String(value.name||""),
        username:String(value.username||""),
        permissions:{
            stock:value.permissions?.stock===true,
            expenses:value.permissions?.expenses===true,
            shiftClosings:value.permissions?.shiftClosings===true
        }
    });
}

function ppCloudAllowedDatasetKeysPP(){
    const allKeys=Object.keys(PP_CLOUD_DATASETS);
    if(ppIsAdmin())return allKeys;
    const permissions=ppCurrentUserProfile?.permissions||{};
    const allowed=[];
    if(permissions.stock===true)allowed.push(...PP_EMPLOYEE_CLOUD_DATASETS.stock);
    if(permissions.expenses===true)allowed.push(...PP_EMPLOYEE_CLOUD_DATASETS.expenses);
    return [...new Set(allowed)].filter(key=>allKeys.includes(key));
}

function ppCloudCanAccessDatasetPP(key){
    return ppCloudAllowedDatasetKeysPP().includes(String(key||""));
}

function ppEnforceLocalDatasetScopePP(){
    if(ppIsAdmin())return;
    const allowed=new Set(ppCloudAllowedDatasetKeysPP());
    Object.keys(PP_CLOUD_DATASETS).forEach(key=>{
        if(!allowed.has(key))ppSetDataset(key,[]);
    });

    // A shared computer must not expose an administrator's cached audit trail
    // after an employee signs in. Employees keep only their own authorized log.
    if(typeof ppAuditTrail!=="undefined"){
        const uid=String(ppCurrentUser?.uid||"");
        const allowedModules=new Set([
            ...(ppCurrentUserProfile?.permissions?.stock===true?["stock"]:[]),
            ...(ppCurrentUserProfile?.permissions?.expenses===true?["expenses"]:[]),
            ...(ppCurrentUserProfile?.permissions?.shiftClosings===true?["shiftClosings"]:[])
        ]);
        ppAuditTrail=(Array.isArray(ppAuditTrail)?ppAuditTrail:[]).filter(entry=>
            allowedModules.has(String(entry?.module||""))&&String(entry?.user?.uid||"")===uid
        );
        localStorage.setItem("pause_plate_audit_trail",JSON.stringify(ppAuditTrail));
    }
}

function ppStateSnapshot(){
    const out={};
    Object.entries(PP_CLOUD_DATASETS).forEach(([key,getter])=>out[key]=getter());
    return out;
}

function ppCloudClonePP(value){
    return JSON.parse(JSON.stringify(value??null));
}

function ppCloudCanonicalPP(value){
    if(Array.isArray(value))return `[${value.map(ppCloudCanonicalPP).join(",")}]`;
    if(value&&typeof value==="object"){
        return `{${Object.keys(value).sort().map(key=>`${JSON.stringify(key)}:${ppCloudCanonicalPP(value[key])}`).join(",")}}`;
    }
    return JSON.stringify(value);
}

function ppCloudHashPP(value){
    const text=ppCloudCanonicalPP(value);let hash=2166136261;
    for(let index=0;index<text.length;index++){
        hash^=text.charCodeAt(index);
        hash=Math.imul(hash,16777619);
    }
    return (hash>>>0).toString(36);
}

function ppCloudEnsureRecordIdsPP(key,items){
    return (Array.isArray(items)?items:[]).map((item,index)=>{
        if(!item||typeof item!=="object")return item;
        if(item.id!==undefined&&item.id!==null&&String(item.id)!=="")return item;
        if(key==="accountingSettings")return {...item,id:"accounting-settings"};
        return {...item,id:`legacy-${key}-${ppCloudHashPP(item)}-${index}`};
    });
}

function ppCloudRecordKeyPP(key,item,index=0){
    if(item&&typeof item==="object"&&item.id!==undefined&&item.id!==null&&String(item.id)!=="")return `id:${String(item.id)}`;
    if(key==="accountingSettings")return "singleton:accounting-settings";
    return `legacy:${index}:${ppCloudCanonicalPP(item)}`;
}

function ppCloudDatasetDeltaPP(key,baseItems,localItems){
    const base=ppCloudEnsureRecordIdsPP(key,baseItems);
    const local=ppCloudEnsureRecordIdsPP(key,localItems);
    const baseMap=new Map(base.map((item,index)=>[ppCloudRecordKeyPP(key,item,index),item]));
    const localMap=new Map(local.map((item,index)=>[ppCloudRecordKeyPP(key,item,index),item]));
    const upserts=[];
    localMap.forEach((item,recordKey)=>{
        const previous=baseMap.get(recordKey);
        if(previous===undefined||ppCloudCanonicalPP(previous)!==ppCloudCanonicalPP(item))upserts.push({recordKey,item});
    });
    const deletes=[];
    baseMap.forEach((_,recordKey)=>{if(!localMap.has(recordKey))deletes.push(recordKey);});
    return {local,upserts,deletes};
}

function ppCloudMergeDatasetPP(key,remoteItems,delta){
    const remote=ppCloudEnsureRecordIdsPP(key,remoteItems);
    const mergedMap=new Map(remote.map((item,index)=>[ppCloudRecordKeyPP(key,item,index),item]));
    delta.deletes.forEach(recordKey=>mergedMap.delete(recordKey));
    delta.upserts.forEach(({recordKey,item})=>mergedMap.set(recordKey,item));

    const ordered=[],seen=new Set();
    delta.local.forEach((item,index)=>{
        const recordKey=ppCloudRecordKeyPP(key,item,index);
        if(mergedMap.has(recordKey)&&!seen.has(recordKey)){
            ordered.push(mergedMap.get(recordKey));seen.add(recordKey);
        }
    });
    remote.forEach((item,index)=>{
        const recordKey=ppCloudRecordKeyPP(key,item,index);
        if(mergedMap.has(recordKey)&&!seen.has(recordKey)){
            ordered.push(mergedMap.get(recordKey));seen.add(recordKey);
        }
    });
    mergedMap.forEach((item,recordKey)=>{if(!seen.has(recordKey))ordered.push(item);});
    return ordered;
}

function ppSetDataset(key,items){
    const safe=ppCloudEnsureRecordIdsPP(key,items);
    switch(key){
        case "products": products=safe; break;
        case "movements": movements=safe; break;
        case "suppliers": suppliers=safe.map(ppNormalizeSupplierPaymentTermPP); break;
        case "invoices": invoices=safe.map(ppNormalizeInvoiceDeadlinePP); break;
        case "supplierPayments": supplierPaymentsPP=safe.map(ppNormalizeSupplierPaymentMaturityPP); break;
        case "clients": clientsPP=safe; break;
        case "clientInvoices": clientInvoicesPP=safe; break;
        case "clientPayments": clientPaymentsPP=safe; break;
        case "sales": salesPP=safe; break;
        case "expenses": expensesPP=safe.map(ppNormalizeExpensePP); break;
        case "recipes": recipesPP=safe; break;
        case "dailySalesScans": dailySalesScansPP=safe; break;
        case "accountingEntries": accountingEntriesPP=safe; break;
        case "accountingSettings": accountingSettingsPP=safe; break;
        case "bankStatementTransactions": bankStatementTransactionsPP=safe.map(ppNormalizeBankTransactionPP); break;
        case "bankReconciliations": bankReconciliationsPP=safe.map(ppNormalizeBankReconciliationPP); break;
        case "treasuryTransfers": treasuryTransfersPP=safe.map(ppNormalizeTreasuryTransferPP); break;
    }
}

function ppSaveLocalOnly(){
    localStorage.setItem(STORAGE_KEYS.products,JSON.stringify(products));
    localStorage.setItem(STORAGE_KEYS.movements,JSON.stringify(movements));
    localStorage.setItem(STORAGE_KEYS.suppliers,JSON.stringify(suppliers));
    localStorage.setItem(STORAGE_KEYS.invoices,JSON.stringify(invoices));
    localStorage.setItem(PP_EXTRA_KEYS.supplierPayments,JSON.stringify(supplierPaymentsPP));
    localStorage.setItem(PP_EXTRA_KEYS.clients,JSON.stringify(clientsPP));
    localStorage.setItem(PP_EXTRA_KEYS.clientInvoices,JSON.stringify(clientInvoicesPP));
    localStorage.setItem(PP_EXTRA_KEYS.clientPayments,JSON.stringify(clientPaymentsPP));
    localStorage.setItem(PP_EXTRA_KEYS.sales,JSON.stringify(salesPP));
    localStorage.setItem(PP_EXTRA_KEYS.expenses,JSON.stringify(expensesPP));
    localStorage.setItem(PP_EXTRA_KEYS.recipes,JSON.stringify(recipesPP));
    localStorage.setItem(PP_EXTRA_KEYS.dailySalesScans,JSON.stringify(dailySalesScansPP));
    localStorage.setItem(PP_EXTRA_KEYS.accountingEntries,JSON.stringify(accountingEntriesPP));
    localStorage.setItem(PP_EXTRA_KEYS.accountingSettings,JSON.stringify(accountingSettingsPP));
    localStorage.setItem(PP_EXTRA_KEYS.bankStatementTransactions,JSON.stringify(bankStatementTransactionsPP));
    localStorage.setItem(PP_EXTRA_KEYS.bankReconciliations,JSON.stringify(bankReconciliationsPP));
    localStorage.setItem(PP_EXTRA_KEYS.treasuryTransfers,JSON.stringify(treasuryTransfersPP));
}

function ppLocalHasData(){
    return products.length||movements.length||suppliers.length||invoices.length||supplierPaymentsPP.length||clientsPP.length||clientInvoicesPP.length||clientPaymentsPP.length||salesPP.length||expensesPP.length||recipesPP.length||dailySalesScansPP.length||accountingEntriesPP.length||accountingSettingsPP.length||bankStatementTransactionsPP.length||bankReconciliationsPP.length||treasuryTransfersPP.length;
}

async function ppCloudHasData(){
    // Employee accounts are created by the administrator after the company
    // space is initialized. They must not read the admin-only meta document.
    if(!ppIsAdmin())return true;
    const meta=await ppMetaDoc().get();
    if(meta.exists&&meta.data()?.initialized)return true;
    const productDoc=await ppDataDoc("products").get();
    return productDoc.exists;
}

async function ppUploadAllLocalToCloud(){
    if(!ppIsAdmin())throw new Error("Initialisation Cloud réservée à l’administrateur.");
    Object.keys(PP_CLOUD_DATASETS).forEach(key=>ppSetDataset(key,PP_CLOUD_DATASETS[key]()));
    const state=ppStateSnapshot();
    const batch=ppDb.batch();
    Object.entries(state).forEach(([key,items])=>{
        batch.set(ppDataDoc(key),{items,updatedAt:firebase.firestore.FieldValue.serverTimestamp(),updatedBy:ppCurrentUser?.uid||null});
    });
    batch.set(ppMetaDoc(),{
        initialized:true,
        migratedAt:firebase.firestore.FieldValue.serverTimestamp(),
        migratedBy:ppCurrentUser?.uid||null,
        schemaVersion:1
    },{merge:true});
    await batch.commit();
    ppCloudBaseState=ppCloudClonePP(state);
    ppCloudDirty=false;
}

async function ppLoadAllCloud(){
    ppApplyingCloudState=true;
    try{
        ppEnforceLocalDatasetScopePP();
        const allowedKeys=ppCloudAllowedDatasetKeysPP();
        ppCloudBaseState={};
        for(const key of allowedKeys){
            const snap=await ppDataDoc(key).get();
            ppSetDataset(key,snap.exists?snap.data()?.items||[]:[]);
            ppCloudBaseState[key]=ppCloudClonePP(PP_CLOUD_DATASETS[key]());
        }
        ppSaveLocalOnly();
        ppCloudDirty=false;
    }finally{ppApplyingCloudState=false;}
}

function ppStopCloudListeners(){
    ppCloudListeners.forEach(fn=>{try{fn();}catch(_){}});
    ppCloudListeners=[];
}

function ppStartCloudListeners(){
    ppStopCloudListeners();
    ppCloudAllowedDatasetKeysPP().forEach(key=>{
        const unsub=ppDataDoc(key).onSnapshot(snap=>{
            if(!ppCloudReady||ppCloudSaving||ppCloudDirty||!snap.exists)return;
            const remote=snap.data()?.items;
            if(!Array.isArray(remote))return;
            ppApplyingCloudState=true;
            try{
                ppSetDataset(key,remote);
                ppSaveLocalOnly();
                ppCloudBaseState[key]=ppCloudClonePP(PP_CLOUD_DATASETS[key]());
                renderAll();
            }finally{ppApplyingCloudState=false;}
        },err=>console.error("Firestore listener",key,err));
        ppCloudListeners.push(unsub);
    });

    // Permissions and account status are live: an administrator can revoke a
    // module or disable an account without waiting for the employee to reconnect.
    if(ppCurrentUser?.uid){
        const profileUnsub=ppDb.collection("userProfiles").doc(ppCurrentUser.uid).onSnapshot(async snap=>{
            if(!snap.exists)return;
            const profile=snap.data()||{};
            if(profile.active===false||profile.deleted===true){
                await ppAuth.signOut();
                return;
            }
            const nextSignature=ppProfileScopeSignaturePP(profile);
            if(nextSignature===ppCloudProfileSignature)return;
            ppCloudProfileSignature=nextSignature;
            ppCurrentRole=String(profile.role||"employee");
            ppCurrentUserProfile={...profile,role:ppCurrentRole,permissions:profile.permissions||{stock:false,expenses:false,shiftClosings:false}};
            ppCloudReady=false;
            ppStopCloudListeners();
            ppEnforceLocalDatasetScopePP();
            await ppLoadAllCloud();
            ppCloudReady=true;
            const userText=document.getElementById("ppCloudUser");
            if(userText)userText.textContent=(ppCurrentUserProfile?.name||ppCurrentUserProfile?.username||"Utilisateur")+" — "+ppCurrentRole;
            ppApplyPermissionsUI();
            renderAll();
            ppStartCloudListeners();
        },err=>console.error("Firestore profile listener",err));
        ppCloudListeners.push(profileUnsub);
    }
}

async function ppSaveCloudNow(){
    if(!ppCloudReady||!ppCurrentUser||ppApplyingCloudState)return;
    if(ppCloudSaving){ppCloudSaveAgain=true;return;}
    if(!ppCloudDirty)return;
    ppCloudSaving=true;
    ppCloudSaveAgain=false;
    clearTimeout(ppCloudSaveTimer);
    ppCloudSaveTimer=null;
    const saveVersion=ppCloudChangeVersion;
    const localState=ppCloudClonePP(ppStateSnapshot());
    const baseState=ppCloudClonePP(ppCloudBaseState||{});
    let mergedState={};
    const status=document.getElementById("ppCloudStatus");
    if(status)status.textContent="☁️ Synchronisation...";
    try{
        const keys=ppCloudAllowedDatasetKeysPP();
        if(!keys.length){
            ppCloudDirty=false;
            if(status)status.textContent="✅ Synchronisé";
            return;
        }
        const refs=keys.map(key=>ppDataDoc(key));
        await ppDb.runTransaction(async transaction=>{
            const snapshots=await Promise.all(refs.map(ref=>transaction.get(ref)));
            const nextState={};
            keys.forEach((key,index)=>{
                const remote=snapshots[index].exists?snapshots[index].data()?.items||[]:[];
                const delta=ppCloudDatasetDeltaPP(key,baseState[key]||[],localState[key]||[]);
                const changed=delta.upserts.length>0||delta.deletes.length>0;
                const merged=changed?ppCloudMergeDatasetPP(key,remote,delta):ppCloudEnsureRecordIdsPP(key,remote);
                nextState[key]=merged;
                // Do not rewrite untouched documents: this is required for
                // least-privilege Firestore rules and reduces overwrite risks.
                if(changed){
                    transaction.set(refs[index],{
                        items:merged,
                        updatedAt:firebase.firestore.FieldValue.serverTimestamp(),
                        updatedBy:ppCurrentUser.uid
                    },{merge:true});
                }
            });
            mergedState=nextState;
        });

        ppCloudBaseState=ppCloudClonePP(mergedState);
        if(ppCloudChangeVersion===saveVersion){
            ppApplyingCloudState=true;
            try{
                Object.entries(mergedState).forEach(([key,items])=>ppSetDataset(key,items));
                ppSaveLocalOnly();
                ppCloudBaseState=ppCloudClonePP(ppStateSnapshot());
                ppCloudDirty=false;
                renderAll();
            }finally{ppApplyingCloudState=false;}
        }else{
            ppCloudDirty=true;
            ppCloudSaveAgain=true;
        }
        if(status)status.textContent="✅ Synchronisé";
    }catch(err){
        console.error("Cloud save failed",err);
        ppCloudDirty=true;
        if(status)status.textContent="⚠️ Hors ligne — sauvegarde locale";
        if(String(err?.code||"").includes("permission-denied"))ppWriteSecurityEventPP("firestore-denied",err?.message||"Écriture Firebase refusée");
    }finally{
        ppCloudSaving=false;
        if(ppCloudSaveAgain||ppCloudChangeVersion!==saveVersion){
            ppCloudSaveAgain=false;
            clearTimeout(ppCloudSaveTimer);
            ppCloudSaveTimer=setTimeout(ppSaveCloudNow,250);
        }
    }
}

function ppScheduleCloudSave(){
    if(!ppCloudReady||ppApplyingCloudState)return;
    ppCloudDirty=true;
    ppCloudChangeVersion++;
    if(ppCloudSaving){ppCloudSaveAgain=true;return;}
    clearTimeout(ppCloudSaveTimer);
    ppCloudSaveTimer=setTimeout(ppSaveCloudNow,500);
}

// Upgrade the existing saveData: local immediately, cloud in background.
const ppLegacySaveData = saveData;
saveData = function(){
    ppEnforceLocalDatasetScopePP();
    ppLegacySaveData();
    ppScheduleCloudSave();
};

async function ppBootstrapCloud(user){
    ppCurrentUser=user;
    await ppEnsureUserProfile(user);
    ppEnforceLocalDatasetScopePP();
    ppSaveLocalOnly();
    const cloudHas=await ppCloudHasData();
    if(!cloudHas){
        if(ppLocalHasData()){
            const ok=confirm("Première connexion Cloud. Copier les données de cet ordinateur vers Firebase ?\n\nChoisissez OK sur l’ordinateur qui contient la version la plus complète des données.");
            if(ok)await ppUploadAllLocalToCloud();
            else await ppMetaDoc().set({initialized:true,schemaVersion:1,createdAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});
        }else{
            await ppUploadAllLocalToCloud();
        }
    }else{
        await ppLoadAllCloud();
    }
    ppCloudReady=true;
    if(ppIsAdmin())importFichesTechniquesPP(false,false);
    ppAddCloudHeader();
    const userText=document.getElementById("ppCloudUser");
    if(userText)userText.textContent=(ppCurrentUserProfile?.name||ppCurrentUserProfile?.username||"Utilisateur")+" — "+ppCurrentRole;
    ppHideLogin();
    setTimeout(ppEnsureUserManagerButton,100);
    ensurePPExtraUI();
    renderAll();
    ppStartCloudListeners();
}

function ppInitFirebase(){
    if(!ppFirebaseAvailable()){
        alert("Firebase n'a pas pu être chargé. Vérifiez la connexion Internet.");
        importFichesTechniquesPP(false,false);ensurePPExtraUI();renderAll();return;
    }
    ppFirebaseApp=firebase.apps.length?firebase.app():firebase.initializeApp(PP_FIREBASE_CONFIG);
    ppAuth=firebase.auth();
    ppDb=firebase.firestore();
    try{ppDb.enablePersistence({synchronizeTabs:true}).catch(()=>{});}catch(_){ }

    ppShowLogin();
    ppAuth.onAuthStateChanged(async user=>{
        if(!user){
            ppCloudReady=false;ppCurrentUser=null;ppStopCloudListeners();ppShowLogin();return;
        }
        const msg=document.getElementById("ppCloudLoginMessage");if(msg)msg.textContent="Chargement des données Cloud...";
        try{await ppBootstrapCloud(user);}catch(err){
            console.error(err);
            ppShowLogin("Erreur Firebase: "+(err?.message||err));
        }
    });
}

document.addEventListener("DOMContentLoaded",ppInitFirebase);


/* =========================================================
   USERS / PERMISSIONS / AUDIT TRAIL — PAUSE & PLATE
   Phase 1: Admin + Employé Stock & Dépenses
========================================================= */

const PP_ACCESS = {
    ADMIN: 'admin',
    EMPLOYEE: 'employee'
};

let ppCurrentUserProfile = null;
let ppAuditTrail = JSON.parse(localStorage.getItem('pause_plate_audit_trail') || '[]');

function ppCurrentFirebaseUser(){
    try{
        return (typeof ppAuth!=='undefined' && ppAuth && ppAuth.currentUser) ? ppAuth.currentUser : null;
    }catch(e){ return null; }
}

function ppUserIdentity(){
    const u=ppCurrentFirebaseUser();
    return {
        uid: u?.uid || 'local',
        email: u?.email || 'Utilisateur local',
        name: ppCurrentUserProfile?.name || u?.displayName || u?.email || 'Utilisateur',
        role: ppCurrentUserProfile?.role || PP_ACCESS.ADMIN
    };
}

function ppIsAdmin(){
    return (ppCurrentUserProfile?.role || PP_ACCESS.ADMIN) === PP_ACCESS.ADMIN;
}

function ppCan(module,action='view'){
    if(ppIsAdmin()) return true;
    const perms=ppCurrentUserProfile?.permissions || {};
    if(module==='stock') return perms.stock !== false;
    if(module==='expenses') return perms.expenses !== false;
    if(module==='shiftClosings') return perms.shiftClosings === true;
    return false;
}

function ppAuditSnapshot(value){
    if(value===undefined) return null;
    try{return JSON.parse(JSON.stringify(value));}catch(e){return String(value);}
}

function ppAuditDiff(before,after){
    const b=before||{},a=after||{},changes=[];
    const keys=new Set([...Object.keys(b),...Object.keys(a)]);
    keys.forEach(k=>{
        if(['updatedAt','createdAt','auditCount'].includes(k))return;
        const bv=JSON.stringify(b[k]??null), av=JSON.stringify(a[k]??null);
        if(bv!==av) changes.push({field:k,before:b[k]??null,after:a[k]??null});
    });
    return changes;
}

async function ppWriteAudit(module,entityId,action,before,after,label=''){
    const who=ppUserIdentity();
    const previous=ppAuditTrail.filter(x=>x.module===module && String(x.entityId)===String(entityId));
    const entry={
        id:Date.now()+Math.floor(Math.random()*100000),
        module,
        entityId:String(entityId),
        label:String(label||''),
        action,
        version:previous.length+1,
        user:who,
        at:new Date().toISOString(),
        before:ppAuditSnapshot(before),
        after:ppAuditSnapshot(after),
        changes:ppAuditDiff(before,after)
    };
    ppAuditTrail.push(entry);
    localStorage.setItem('pause_plate_audit_trail',JSON.stringify(ppAuditTrail));

    // Firestore: separate immutable-ish audit documents; main app sync remains untouched.
    try{
        if(typeof ppDb!=='undefined' && ppDb && who.uid!=='local' && typeof firebase!=='undefined' && firebase.firestore){
            await ppDb.collection('auditLogs').add(entry);
        }
    }catch(e){
        console.warn('Audit cloud différé:',e);
    }
    return entry;
}

async function ppWriteSecurityEventPP(action,details=''){
    const who=ppUserIdentity();
    if(!ppDb||who.uid==='local')return;
    const entry={
        id:Date.now()+Math.floor(Math.random()*100000),
        module:'security',
        entityId:String(who.uid),
        label:String(details||'Accès refusé').slice(0,500),
        action:String(action||'denied').slice(0,80),
        version:1,
        user:who,
        at:new Date().toISOString(),
        before:null,
        after:null,
        changes:[]
    };
    try{await ppDb.collection('auditLogs').add(entry);}catch(_){ }
}

function ppAuditCount(module,id){
    return ppAuditTrail.filter(x=>x.module===module && String(x.entityId)===String(id)).length;
}


function ppAuditFieldLabel(field){
    const labels={
        productName:"Produit",
        type:"Type",
        quantity:"Quantité",
        unit:"Unité",
        reason:"Motif",
        note:"Note"
    };
    return labels[field]||field;
}

function ppFormatAuditValue(v){
    if(v===null||v===undefined||v==='')return '—';
    if(typeof v==='object')return escapeHTML(JSON.stringify(v));
    return escapeHTML(String(v));
}

function ppShowAudit(module,id,title='Historique'){
    const rows=ppAuditTrail
      .filter(x=>x.module===module && String(x.entityId)===String(id))
      .sort((a,b)=>new Date(b.at)-new Date(a.at));

    let body='';
    if(!rows.length){
        body='<div class="empty">Aucun historique enregistré pour cette opération.</div>';
    }else{
        body=rows.map(x=>{
            const changes=(x.changes||[]).length
              ? `<table style="width:100%;margin-top:8px"><thead><tr><th>Champ</th><th>Avant</th><th>Après</th></tr></thead><tbody>${x.changes.map(c=>`<tr><td>${escapeHTML(ppAuditFieldLabel(c.field))}</td><td>${ppFormatAuditValue(c.before)}</td><td>${ppFormatAuditValue(c.after)}</td></tr>`).join('')}</tbody></table>`
              : '<div style="color:#667085;margin-top:6px">Création de l’opération.</div>';
            const act=x.action==='create'?'Création':x.action==='update'?'Modification':x.action==='delete'?'Suppression':x.action;
            return `<div style="border:1px solid #e5e7eb;border-radius:12px;padding:12px;margin-bottom:10px">
                <div style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap">
                  <strong>Version ${x.version} — ${act}</strong>
                  <span>${new Date(x.at).toLocaleString('fr-FR')}</span>
                </div>
                <div style="margin-top:5px">👤 ${escapeHTML(x.user?.name||x.user?.email||'Utilisateur')} ${x.user?.email && x.user?.email!==x.user?.name?`(${escapeHTML(x.user.email)})`:''}</div>
                ${changes}
              </div>`;
        }).join('');
    }

    const modalId='ppAuditModal';
    let m=document.getElementById(modalId);
    if(!m){
        m=document.createElement('div');m.id=modalId;m.className='modal-overlay';
        m.innerHTML=`<div class="modal" style="max-width:1000px"><div class="modal-header"><h2 id="ppAuditTitle">Historique</h2><button onclick="closeModal('${modalId}')">×</button></div><div id="ppAuditBody"></div><div class="modal-actions"><button class="btn" onclick="closeModal('${modalId}')">Fermer</button></div></div>`;
        document.body.appendChild(m);
    }
    document.getElementById('ppAuditTitle').textContent=title;
    document.getElementById('ppAuditBody').innerHTML=body;
    openModal(modalId);
}

function ppAuditMovement(id){ ppShowAudit('stock',id,'Historique de l’opération stock'); }
function ppAuditExpense(id){ ppShowAudit('expenses',id,'Historique de la dépense'); }

/* ---------- STOCK: permissions ---------- */
const ppBaseOpenMovementModal = openMovementModal;
openMovementModal = function(type,id=null){
    if(!ppCan('stock','edit')){
        alert('Accès non autorisé.');
        return;
    }
    return ppBaseOpenMovementModal(type,id);
};

/* ---------- DEPENSES: audit create/update/delete ---------- */
const ppBaseOpenExpensePP = openExpensePP;
openExpensePP = function(id=null){
    if(!ppCan('expenses','edit')){alert('Accès non autorisé.');return;}
    return ppBaseOpenExpensePP(id);
};

const ppBaseSaveExpensePP = saveExpensePP;
saveExpensePP = function(){
    if(!ppCan('expenses','edit')){alert('Accès non autorisé.');return;}
    const id=Number(document.getElementById('ppExpenseId')?.value||0);
    const before=id?ppAuditSnapshot(expensesPP.find(x=>Number(x.id)===id)):null;
    const beforeIds=new Set(expensesPP.map(x=>String(x.id)));
    const result=ppBaseSaveExpensePP();
    setTimeout(()=>{
        let after=null, entityId=id;
        if(id) after=expensesPP.find(x=>Number(x.id)===id);
        else{
            after=expensesPP.find(x=>!beforeIds.has(String(x.id))) || expensesPP[0] || expensesPP[expensesPP.length-1];
            entityId=after?.id;
        }
        if(after && entityId!=null){
            after.auditCount=ppAuditCount('expenses',entityId)+1;
            ppWriteAudit('expenses',entityId,before?'update':'create',before,after,after.description||after.category||'Dépense');
            try{saveData();}catch(e){}
        }
    },0);
    return result;
};

const ppBaseDeleteExpensePP = deleteExpensePP;
deleteExpensePP = function(id){
    if(!ppCan('expenses','delete')){alert('Accès non autorisé.');return;}
    const before=ppAuditSnapshot(expensesPP.find(x=>Number(x.id)===Number(id)));
    const countBefore=expensesPP.length;
    const result=ppBaseDeleteExpensePP(id);
    setTimeout(()=>{
        if(before && expensesPP.length<countBefore && !expensesPP.some(x=>Number(x.id)===Number(id))){
            ppWriteAudit('expenses',id,'delete',before,null,before.description||before.category||'Dépense');
        }
    },0);
    return result;
};

const ppBaseOpenExpensePaymentPP = openExpensePaymentPP;
openExpensePaymentPP = function(expenseId){
    if(!ppCan('expenses','edit')){alert('Accès non autorisé.');return;}
    return ppBaseOpenExpensePaymentPP(expenseId);
};

const ppBaseSaveExpensePaymentPP = saveExpensePaymentPP;
saveExpensePaymentPP = function(){
    if(!ppCan('expenses','edit')){alert('Accès non autorisé.');return;}
    const expenseId=Number(document.getElementById('ppExpensePaymentExpenseId')?.value||0);
    const before=ppAuditSnapshot(expensesPP.find(x=>Number(x.id)===expenseId));
    const result=ppBaseSaveExpensePaymentPP();
    const after=expensesPP.find(x=>Number(x.id)===expenseId);
    if(before&&after&&JSON.stringify(before)!==JSON.stringify(ppAuditSnapshot(after))){
        ppWriteAudit('expenses',expenseId,'update',before,after,'Ajout règlement dépense');
    }
    return result;
};

const ppBaseDeleteExpensePaymentPP = deleteExpensePaymentPP;
deleteExpensePaymentPP = function(expenseId,paymentId){
    if(!ppCan('expenses','edit')){alert('Accès non autorisé.');return;}
    const before=ppAuditSnapshot(expensesPP.find(x=>Number(x.id)===Number(expenseId)));
    const result=ppBaseDeleteExpensePaymentPP(expenseId,paymentId);
    const after=expensesPP.find(x=>Number(x.id)===Number(expenseId));
    if(before&&after&&JSON.stringify(before)!==JSON.stringify(ppAuditSnapshot(after))){
        ppWriteAudit('expenses',expenseId,'update',before,after,'Suppression règlement dépense');
    }
    return result;
};

/* ---------- Add Historique buttons after each render ---------- */
function ppInjectAuditButtons(){
    // Stock movement table: identify edit/delete buttons that carry movement IDs.
    document.querySelectorAll('button[onclick*="openMovementModal("]').forEach(btn=>{
        const oc=btn.getAttribute('onclick')||'';
        const m=oc.match(/openMovementModal\([^,]+,\s*(\d+)\)/);
        if(!m)return;
        const id=m[1],group=btn.closest('.action-buttons')||btn.parentElement;
        if(!group || group.querySelector(`[data-audit-stock="${id}"]`))return;
        const b=document.createElement('button');
        b.type='button';b.className='btn small view';b.dataset.auditStock=id;
        b.innerHTML=`🕘 ${ppAuditCount('stock',id)}`;
        b.title='Historique complet';
        b.onclick=()=>ppAuditMovement(id);
        group.appendChild(b);
    });

    // Expense table.
    document.querySelectorAll('button[onclick^="openExpensePP("]').forEach(btn=>{
        const oc=btn.getAttribute('onclick')||'';
        const m=oc.match(/openExpensePP\((\d+)\)/);
        if(!m)return;
        const id=m[1],group=btn.closest('.action-buttons')||btn.parentElement;
        if(!group || group.querySelector(`[data-audit-expense="${id}"]`))return;
        const b=document.createElement('button');
        b.type='button';b.className='btn small view';b.dataset.auditExpense=id;
        b.innerHTML=`🕘 ${ppAuditCount('expenses',id)}`;
        b.title='Historique complet';
        b.onclick=()=>ppAuditExpense(id);
        group.appendChild(b);
    });
}

const ppAuditObserver=new MutationObserver(()=>ppInjectAuditButtons());
if(document.body) ppAuditObserver.observe(document.body,{childList:true,subtree:true});
setTimeout(ppInjectAuditButtons,500);

/* ---------- Role-aware navigation ---------- */
function ppApplyPermissionsUI(){
    if(ppIsAdmin())return;
    const allowed=[];
    const permissions=ppCurrentUserProfile?.permissions||{};
    if(permissions.stock!==false)allowed.push('stock');
    if(permissions.expenses!==false)allowed.push('expenses');
    if(permissions.shiftClosings===true)allowed.push('shift');
    document.querySelectorAll('[data-page]').forEach(el=>{
        const page=String(el.dataset.page||'').toLowerCase();
        if(page && !allowed.some(x=>page.includes(x))) el.style.display='none';
    });
    // Fallback for sidebar links/buttons without data-page.
    document.querySelectorAll('.sidebar button,.sidebar a,.nav-item').forEach(el=>{
        const t=(el.textContent||'').toLowerCase();
        if(!t)return;
        if(!(t.includes('stock')||t.includes('dépense')||t.includes('depense')||t.includes('clôture shift')||t.includes('cloture shift')||t.includes('déconnexion')||t.includes('logout'))){
            el.style.display='none';
        }
    });
}

/*
  Profiles:
  Admin remains the default for the account that already existed before roles.
  Employee profiles can later be stored as:
  userProfiles/{uid} = {
    role:"employee",
    name:"...",
    permissions:{stock:true,expenses:true,shiftClosings:true}
  }
*/
async function ppLoadUserProfile(){
    const u=ppCurrentFirebaseUser();
    if(!u){ppCurrentUserProfile=null;return;}
    try{
        const snap=await ppDb.collection('userProfiles').doc(u.uid).get();
        if(snap.exists)ppCurrentUserProfile=snap.data();
        else ppCurrentUserProfile={
            role:String(u.email||'').toLowerCase()===PP_ADMIN_EMAIL.toLowerCase()?PP_ACCESS.ADMIN:PP_ACCESS.EMPLOYEE,
            name:u.email,
            active:true,
            permissions:{stock:true,expenses:true,shiftClosings:false}
        };
    }catch(e){
        console.warn('Profil utilisateur:',e);
    }
    ppApplyPermissionsUI();
}
setTimeout(ppLoadUserProfile,700);


