function ppRenderGlobalAudit(){
    const body=document.getElementById("ppGlobalAuditBody");
    if(!body)return;

    const search=String(document.getElementById("ppAuditSearch")?.value||"").trim().toLowerCase();
    const module=String(document.getElementById("ppAuditModule")?.value||"");
    const action=String(document.getElementById("ppAuditAction")?.value||"");
    const date=String(document.getElementById("ppAuditDate")?.value||"");

    let rows=(Array.isArray(ppAuditTrail)?ppAuditTrail:[]).slice().sort((a,b)=>new Date(b.at)-new Date(a.at));
    rows=rows.filter(x=>{
        if(module && x.module!==module)return false;
        if(action && x.action!==action)return false;
        if(date && String(x.at||"").slice(0,10)!==date)return false;
        if(search){
            const hay=[
                x.label,x.module,x.action,x.entityId,
                x.user?.name,x.user?.email,x.user?.role
            ].join(" ").toLowerCase();
            if(!hay.includes(search))return false;
        }
        return true;
    });

    if(!rows.length){
        body.innerHTML='<div class="empty-state"><div>🕘</div><h3>Aucune opération</h3><p>Aucune activité ne correspond aux filtres.</p></div>';
        return;
    }

    const actionLabel={create:"Création",update:"Modification",delete:"Suppression",activate:"Activation",deactivate:"Désactivation"};
    const moduleLabel={stock:"Stock",expenses:"Dépenses",shiftClosings:"Clôtures Shift",users:"Utilisateurs"};

    body.innerHTML=`
      <div class="table-wrapper">
        <table>
          <thead>
            <tr>
              <th>Date & heure</th>
              <th>Utilisateur</th>
              <th>Module</th>
              <th>Opération</th>
              <th>Élément</th>
              <th>Version</th>
              <th>Détails</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map(x=>`
              <tr>
                <td>${escapeHTML(new Date(x.at).toLocaleString("fr-FR"))}</td>
                <td><strong>${escapeHTML(x.user?.name||x.user?.email||"Utilisateur")}</strong></td>
                <td>${escapeHTML(moduleLabel[x.module]||x.module||"-")}</td>
                <td>${escapeHTML(actionLabel[x.action]||x.action||"-")}</td>
                <td>${escapeHTML(x.label||x.entityId||"-")}</td>
                <td>${Number(x.version||1)}</td>
                <td>
                  ${(x.module==="stock"||x.module==="expenses"||x.module==="shiftClosings")
                    ? `<button class="btn small view" type="button" onclick="ppShowAudit('${String(x.module).replace(/'/g,"")}','${String(x.entityId).replace(/'/g,"")}','Historique complet')">👁 Voir</button>`
                    : "—"}
                </td>
              </tr>`).join("")}
          </tbody>
        </table>
      </div>`;
}

// Refresh after login/profile loading and on startup.
const ppOldApplyPermissionsUI=ppApplyPermissionsUI;
ppApplyPermissionsUI=function(){
    const result=ppOldApplyPermissionsUI.apply(this,arguments);
    ppRefreshAdminSidebar();
    return result;
};

setTimeout(ppRefreshAdminSidebar,1000);


/* =========================================================
   FIX STRICT EMPLOYEE PERMISSIONS
   Employé = Stock + Dépenses uniquement
========================================================= */

// Never assume Admin while the profile is not loaded.
ppIsAdmin = function(){
    if(ppCurrentUserProfile?.role) return ppCurrentUserProfile.role === PP_ACCESS.ADMIN;
    const u=ppCurrentFirebaseUser();
    return !!u && String(u.email||"").toLowerCase() === PP_ADMIN_EMAIL.toLowerCase();
};

function ppPageNameFromElement(el){
    return String(el?.dataset?.page||"").toLowerCase();
}

function ppEmployeeAllowedPages(){
    const perms=ppCurrentUserProfile?.permissions||{};
    const allowed=[];
    if(perms.stock!==false)allowed.push("stock");
    if(perms.expenses!==false)allowed.push("expenses");
    if(perms.shiftClosings===true)allowed.push("shift");
    return allowed;
}

ppApplyPermissionsUI = function(){
    const admin=ppIsAdmin();
    const adminBox=document.getElementById("ppAdminSidebar");
    if(adminBox)adminBox.style.display=admin?"block":"none";

    const manageBtn=document.getElementById("ppManageUsersBtn");
    if(manageBtn)manageBtn.style.display=admin?"":"none";

    const allNav=[...document.querySelectorAll(".sidebar [data-page]")];

    if(admin){
        allNav.forEach(el=>el.style.display="");
        document.querySelectorAll(".sidebar .menu-title").forEach(el=>el.style.display="");
        return;
    }

    const allowed=ppEmployeeAllowedPages();

    allNav.forEach(el=>{
        const page=ppPageNameFromElement(el);
        el.style.display=allowed.includes(page)?"":"none";
    });

    // Administration is always hidden for employees.
    if(adminBox)adminBox.style.display="none";

    // Hide section titles that no longer contain a visible menu entry.
    document.querySelectorAll(".sidebar .menu-title").forEach(title=>{
        let next=title.nextElementSibling;
        let hasVisible=false;
        while(next && !next.classList.contains("menu-title")){
            if(next.matches?.("[data-page]") && next.style.display!=="none"){hasVisible=true;break;}
            if(next.id==="ppAdminSidebar" && next.style.display!=="none"){hasVisible=true;break;}
            next=next.nextElementSibling;
        }
        title.style.display=hasVisible?"":"none";
    });

    // Employee must never stay on Dashboard/Purchases/etc after login.
    const active=document.querySelector(".nav-item.active[data-page]");
    const activePage=ppPageNameFromElement(active);
    if(!allowed.includes(activePage)){
        const target=allowed.includes("stock")?"stock":allowed[0];
        if(target){
            const btn=document.querySelector(`.sidebar [data-page="${target}"]`);
            if(btn)btn.click();
        }
    }
};

// Guard sidebar navigation even if a hidden/restricted page is triggered manually.
document.addEventListener("click",function(e){
    const nav=e.target.closest?.("[data-page]");
    if(!nav || ppIsAdmin())return;
    const page=ppPageNameFromElement(nav);
    if(!ppEmployeeAllowedPages().includes(page)){
        e.preventDefault();
        e.stopImmediatePropagation();
        ppWriteSecurityEventPP("navigation-denied",`Page refusée : ${page||"inconnue"}`);
        alert("Accès non autorisé.");
    }
},true);

function ppFinalizeRoleUI(){
    ppApplyPermissionsUI();
    if(!ppIsAdmin()){
        const b=document.getElementById("ppManageUsersBtn");
        if(b)b.remove();
    }else{
        try{ppEnsureUserManagerButton();}catch(_){}
    }
}

// Re-run permissions after Firebase actually finishes loading the profile.
const ppOldBootstrapCloudPermissions = ppBootstrapCloud;
ppBootstrapCloud = async function(user){
    await ppOldBootstrapCloudPermissions(user);
    ppFinalizeRoleUI();
};

// Also refresh on delayed UI renders/listeners.
setTimeout(ppFinalizeRoleUI,1500);
setTimeout(ppFinalizeRoleUI,3000);


/* =========================================================
   RECHERCHE ARTICLE — ENTRÉE / SORTIE DE STOCK
   Interface uniquement : le select movementProduct original
   reste la source utilisée par saveMovement().
========================================================= */
(function(){
    "use strict";

    const PP_MOVEMENT_SEARCH_STYLE_ID = "ppMovementProductSearchStyle";
    const PP_MOVEMENT_SEARCH_INPUT_ID = "movementProductSearch";
    const PP_MOVEMENT_SEARCH_RESULTS_ID = "movementProductSearchResults";

    function ppNormalizeMovementSearchPP(value){
        return String(value||"")
            .normalize("NFD")
            .replace(/[\u0300-\u036f]/g,"")
            .toLowerCase()
            .replace(/\s+/g," ")
            .trim();
    }

    function ppInstallMovementSearchStylePP(){
        if(document.getElementById(PP_MOVEMENT_SEARCH_STYLE_ID))return;

        const style=document.createElement("style");
        style.id=PP_MOVEMENT_SEARCH_STYLE_ID;
        style.textContent=`
            .pp-movement-product-search{
                position:relative;
                width:100%;
                margin-bottom:14px;
            }
            #${PP_MOVEMENT_SEARCH_INPUT_ID}{
                width:100%;
                min-height:46px;
                padding:11px 42px 11px 13px;
                border:1px solid var(--border,#dfe5e1);
                border-radius:10px;
                background:#fff;
                color:var(--text,#26332c);
                font:inherit;
                outline:none;
                transition:border-color .18s ease,box-shadow .18s ease;
            }
            #${PP_MOVEMENT_SEARCH_INPUT_ID}:focus{
                border-color:var(--green,#094b2d);
                box-shadow:0 0 0 3px rgba(9,75,45,.12);
            }
            .pp-movement-product-search::after{
                content:"⌕";
                position:absolute;
                top:11px;
                right:14px;
                color:var(--green,#094b2d);
                font-size:21px;
                line-height:1;
                pointer-events:none;
            }
            #${PP_MOVEMENT_SEARCH_RESULTS_ID}{
                position:absolute;
                z-index:10050;
                top:calc(100% + 6px);
                left:0;
                right:0;
                display:none;
                max-height:280px;
                overflow:auto;
                padding:6px;
                border:1px solid var(--border,#dfe5e1);
                border-radius:12px;
                background:#fff;
                box-shadow:0 14px 35px rgba(24,37,27,.18);
            }
            #${PP_MOVEMENT_SEARCH_RESULTS_ID}.is-open{
                display:block;
            }
            .pp-movement-search-option{
                display:block;
                width:100%;
                padding:11px 12px;
                border:0;
                border-radius:9px;
                background:transparent;
                color:var(--text,#26332c);
                text-align:left;
                font:inherit;
                cursor:pointer;
            }
            .pp-movement-search-option:hover,
            .pp-movement-search-option.is-active{
                background:var(--green-light,#eaf3ee);
            }
            .pp-movement-search-option strong{
                display:block;
                margin-bottom:3px;
            }
            .pp-movement-search-option small{
                display:block;
                color:var(--muted,#7a857e);
            }
            .pp-movement-search-empty{
                padding:14px 12px;
                color:var(--muted,#7a857e);
                text-align:center;
            }
            @media(max-width:550px){
                #${PP_MOVEMENT_SEARCH_RESULTS_ID}{
                    max-height:42vh;
                }
            }
        `;
        document.head.appendChild(style);
    }

    function ppMovementProductLabelPP(product){
        return String(product?.name||"");
    }

    function ppMovementProductMetaPP(product){
        const stock=typeof formatNumber==="function"
            ? formatNumber(Number(product?.stock||0))
            : String(Number(product?.stock||0));
        return `Stock actuel : ${stock} ${String(product?.unit||"")}`.trim();
    }

    function ppGetMovementProductPP(id){
        return Array.isArray(products)
            ? products.find(product=>Number(product.id)===Number(id))
            : null;
    }

    function ppCloseMovementSearchPP(){
        document.getElementById(PP_MOVEMENT_SEARCH_RESULTS_ID)
            ?.classList.remove("is-open");
    }

    function ppSelectMovementProductPP(productId,focusQuantity=false){
        const select=document.getElementById("movementProduct");
        const input=document.getElementById(PP_MOVEMENT_SEARCH_INPUT_ID);
        const product=ppGetMovementProductPP(productId);
        if(!select || !input || !product)return;

        select.value=String(product.id);
        input.value=ppMovementProductLabelPP(product);
        input.dataset.selectedId=String(product.id);
        select.dispatchEvent(new Event("change",{bubbles:true}));
        ppCloseMovementSearchPP();

        if(focusQuantity){
            document.getElementById("movementQuantity")?.focus();
        }
    }

    function ppRenderMovementSearchResultsPP(query=""){
        const box=document.getElementById(PP_MOVEMENT_SEARCH_RESULTS_ID);
        if(!box)return;

        const normalized=ppNormalizeMovementSearchPP(query);
        const matches=(Array.isArray(products)?products:[])
            .filter(product=>ppNormalizeMovementSearchPP(product.name).includes(normalized))
            .sort((a,b)=>String(a.name||"").localeCompare(String(b.name||""),"fr",{sensitivity:"base"}))
            .slice(0,80);

        box.replaceChildren();

        if(!matches.length){
            const empty=document.createElement("div");
            empty.className="pp-movement-search-empty";
            empty.textContent="Aucun article trouvé.";
            box.appendChild(empty);
            box.classList.add("is-open");
            return;
        }

        matches.forEach((product,index)=>{
            const button=document.createElement("button");
            button.type="button";
            button.className="pp-movement-search-option"+(index===0?" is-active":"");
            button.dataset.productId=String(product.id);

            const name=document.createElement("strong");
            name.textContent=ppMovementProductLabelPP(product);

            const meta=document.createElement("small");
            meta.textContent=ppMovementProductMetaPP(product);

            button.append(name,meta);
            button.addEventListener("mousedown",event=>{
                event.preventDefault();
                ppSelectMovementProductPP(product.id,true);
            });
            box.appendChild(button);
        });

        box.classList.add("is-open");
    }

    function ppSyncMovementSearchFromSelectPP(){
        const select=document.getElementById("movementProduct");
        const input=document.getElementById(PP_MOVEMENT_SEARCH_INPUT_ID);
        if(!select || !input)return;

        const product=ppGetMovementProductPP(select.value);
        input.value=product ? ppMovementProductLabelPP(product) : "";
        input.dataset.selectedId=product ? String(product.id) : "";
    }

    function ppEnsureMovementProductSearchPP(){
        const select=document.getElementById("movementProduct");
        if(!select)return null;

        ppInstallMovementSearchStylePP();

        let input=document.getElementById(PP_MOVEMENT_SEARCH_INPUT_ID);
        if(!input){
            const wrapper=document.createElement("div");
            wrapper.className="pp-movement-product-search";

            input=document.createElement("input");
            input.id=PP_MOVEMENT_SEARCH_INPUT_ID;
            input.type="search";
            input.autocomplete="off";
            input.spellcheck=false;
            input.placeholder="Rechercher un article...";
            input.setAttribute("aria-label","Rechercher un article");
            input.setAttribute("aria-controls",PP_MOVEMENT_SEARCH_RESULTS_ID);

            const results=document.createElement("div");
            results.id=PP_MOVEMENT_SEARCH_RESULTS_ID;
            results.setAttribute("role","listbox");

            wrapper.append(input,results);
            select.parentNode.insertBefore(wrapper,select);
            select.style.display="none";
            select.setAttribute("aria-hidden","true");

            input.addEventListener("focus",()=>{
                ppRenderMovementSearchResultsPP(input.value);
            });

            input.addEventListener("input",()=>{
                const selected=ppGetMovementProductPP(input.dataset.selectedId);
                if(!selected || ppNormalizeMovementSearchPP(input.value)!==ppNormalizeMovementSearchPP(selected.name)){
                    select.value="";
                    input.dataset.selectedId="";
                }
                ppRenderMovementSearchResultsPP(input.value);
            });

            input.addEventListener("keydown",event=>{
                if(event.key==="Escape"){
                    ppCloseMovementSearchPP();
                    return;
                }

                if(event.key==="ArrowDown"){
                    event.preventDefault();
                    const options=[...document.querySelectorAll(".pp-movement-search-option")];
                    if(!options.length)return;
                    const active=document.querySelector(".pp-movement-search-option.is-active");
                    const current=Math.max(options.indexOf(active),0);
                    options.forEach(option=>option.classList.remove("is-active"));
                    options[Math.min(current+1,options.length-1)].classList.add("is-active");
                    options[Math.min(current+1,options.length-1)].scrollIntoView({block:"nearest"});
                    return;
                }

                if(event.key==="ArrowUp"){
                    event.preventDefault();
                    const options=[...document.querySelectorAll(".pp-movement-search-option")];
                    if(!options.length)return;
                    const active=document.querySelector(".pp-movement-search-option.is-active");
                    const current=Math.max(options.indexOf(active),0);
                    options.forEach(option=>option.classList.remove("is-active"));
                    options[Math.max(current-1,0)].classList.add("is-active");
                    options[Math.max(current-1,0)].scrollIntoView({block:"nearest"});
                    return;
                }

                if(event.key==="Enter"){
                    const active=document.querySelector(".pp-movement-search-option.is-active");
                    if(active){
                        event.preventDefault();
                        ppSelectMovementProductPP(active.dataset.productId,true);
                    }
                }
            });

            select.addEventListener("change",ppSyncMovementSearchFromSelectPP);

            document.addEventListener("mousedown",event=>{
                if(!event.target.closest(".pp-movement-product-search")){
                    ppCloseMovementSearchPP();
                }
            });

            document.getElementById("movementForm")?.addEventListener("submit",()=>{
                if(select.value)return;
                const exact=(Array.isArray(products)?products:[]).find(product=>
                    ppNormalizeMovementSearchPP(product.name)===ppNormalizeMovementSearchPP(input.value)
                );
                if(exact)ppSelectMovementProductPP(exact.id,false);
            },true);
        }

        ppSyncMovementSearchFromSelectPP();
        return input;
    }

    const ppOpenMovementModalSearchBasePP=window.openMovementModal;
    if(typeof ppOpenMovementModalSearchBasePP==="function"){
        window.openMovementModal=function(){
            const result=ppOpenMovementModalSearchBasePP.apply(this,arguments);

            requestAnimationFrame(()=>{
                const input=ppEnsureMovementProductSearchPP();
                ppSyncMovementSearchFromSelectPP();

                window.setTimeout(()=>{
                    input?.focus();
                    ppRenderMovementSearchResultsPP(input?.value||"");
                },80);
            });

            return result;
        };
    }

    if(document.readyState==="loading"){
        document.addEventListener("DOMContentLoaded",ppEnsureMovementProductSearchPP,{once:true});
    }else{
        ppEnsureMovementProductSearchPP();
    }
})();


/* =========================================================
   VENTES — RECHERCHE RAPIDE DANS LES FICHES / AFFECTATIONS
   Ajout ciblé : conserve les selects d'origine comme source de vérité.
========================================================= */

function ppEnsureSalesQuickSearchStylesPP(){
    if(document.getElementById('ppSalesQuickSearchStyles'))return;
    const style=document.createElement('style');
    style.id='ppSalesQuickSearchStyles';
    style.textContent=`
      .pp-sales-search-wrap{position:relative;min-width:0}
      .pp-sales-search-input{width:100%;min-height:42px;padding:10px 12px;border:1px solid #d0d5dd;border-radius:10px;background:#fff;color:#18251b;font:inherit}
      .pp-sales-search-input:focus{outline:none;border-color:#094B2D;box-shadow:0 0 0 3px rgba(9,75,45,.12)}
      .pp-sales-search-menu{display:none;position:absolute;z-index:10050;left:0;right:0;top:calc(100% + 5px);max-height:280px;overflow:auto;background:#fff;border:1px solid #d0d5dd;border-radius:12px;box-shadow:0 14px 35px rgba(16,24,40,.16);padding:5px}
      .pp-sales-search-menu.is-open{display:block}
      .pp-sales-search-option{display:block;width:100%;border:0;background:transparent;text-align:left;padding:9px 10px;border-radius:8px;cursor:pointer;color:#18251b;font:inherit}
      .pp-sales-search-option:hover,.pp-sales-search-option.is-active{background:#f2f7f4}
      .pp-sales-search-option strong{display:block;white-space:normal}
      .pp-sales-search-option small{display:block;color:#667085;margin-top:2px;white-space:normal}
      .pp-sales-search-empty{padding:12px;color:#667085;text-align:center}
      .pp-sales-search-native{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important}
      @media(max-width:700px){.pp-sales-search-menu{position:fixed;left:12px;right:12px;top:auto;bottom:12px;max-height:48vh}.pp-sale-recipe-line{grid-template-columns:1fr!important}}
    `;
    document.head.appendChild(style);

    if(!document.body.dataset.ppSalesSearchOutsideInstalled){
        document.body.dataset.ppSalesSearchOutsideInstalled='1';
        document.addEventListener('click',event=>{
            if(event.target.closest('.pp-sales-search-wrap'))return;
            document.querySelectorAll('.pp-sales-search-menu.is-open').forEach(menu=>menu.classList.remove('is-open'));
        });
    }
}

function ppSalesSearchTextPP(value){
    return normalizeText(String(value||''));
}

function ppSalesSearchMovePP(input,direction){
    const wrap=input.closest('.pp-sales-search-wrap');
    const menu=wrap?.querySelector('.pp-sales-search-menu');
    if(!menu)return;
    const options=[...menu.querySelectorAll('.pp-sales-search-option')];
    if(!options.length)return;
    let index=options.findIndex(option=>option.classList.contains('is-active'));
    index=index<0?(direction>0?0:options.length-1):(index+direction+options.length)%options.length;
    options.forEach((option,i)=>option.classList.toggle('is-active',i===index));
    options[index].scrollIntoView({block:'nearest'});
}

function ppSalesSearchKeydownPP(event){
    const input=event.currentTarget;
    const menu=input.closest('.pp-sales-search-wrap')?.querySelector('.pp-sales-search-menu');
    if(event.key==='ArrowDown'){
        event.preventDefault();
        if(!menu?.classList.contains('is-open'))ppOpenSalesSearchPP(input);
        ppSalesSearchMovePP(input,1);
    }else if(event.key==='ArrowUp'){
        event.preventDefault();
        if(!menu?.classList.contains('is-open'))ppOpenSalesSearchPP(input);
        ppSalesSearchMovePP(input,-1);
    }else if(event.key==='Enter'){
        const active=menu?.querySelector('.pp-sales-search-option.is-active');
        const options=[...(menu?.querySelectorAll('.pp-sales-search-option')||[])];
        const target=active||(options.length===1?options[0]:null);
        if(target){event.preventDefault();target.click();}
    }else if(event.key==='Escape'){
        menu?.classList.remove('is-open');
    }
}

function ppOpenSalesSearchPP(input){
    ppEnsureSalesQuickSearchStylesPP();
    if(input.classList.contains('pp-sale-recipe-search')){
        ppRenderSaleRecipeSuggestionsPP(input);
    }else if(input.classList.contains('pp-daily-assignment-search')){
        ppRenderDailyAssignmentSuggestionsPP(input);
    }
}

function ppRenderSaleRecipeSuggestionsPP(input){
    const wrap=input.closest('.pp-sales-search-wrap');
    const menu=wrap?.querySelector('.pp-sales-search-menu');
    if(!menu)return;
    const q=ppSalesSearchTextPP(input.value);
    const list=recipesPP.slice()
        .sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'fr'))
        .filter(recipe=>!q||ppSalesSearchTextPP([recipe.name,recipe.category,recipe.description].join(' ')).includes(q))
        .slice(0,80);
    menu.innerHTML=list.length?list.map(recipe=>`
      <button type="button" class="pp-sales-search-option" data-value="${recipe.id}" onclick="ppChooseSaleRecipePP(this)">
        <strong>${escapeHTML(recipe.name||'Sans nom')}</strong>
        <small>${escapeHTML(recipe.category||'Fiche technique')} · ${formatMoney(recipe.salePrice||0)}</small>
      </button>`).join(''):'<div class="pp-sales-search-empty">Aucune fiche technique trouvée.</div>';
    menu.classList.add('is-open');
}

function ppChooseSaleRecipePP(button){
    const wrap=button.closest('.pp-sales-search-wrap');
    const row=button.closest('.pp-sale-recipe-line');
    const select=row?.querySelector('.pp-sale-recipe');
    const input=wrap?.querySelector('.pp-sale-recipe-search');
    const recipe=recipesPP.find(item=>Number(item.id)===Number(button.dataset.value));
    if(!select||!input||!recipe)return;
    select.value=String(recipe.id);
    input.value=recipe.name;
    input.dataset.selectedId=String(recipe.id);
    wrap.querySelector('.pp-sales-search-menu')?.classList.remove('is-open');
    updateSaleRecipeLinePP(select);
}

function ppSaleRecipeTypingPP(input){
    input.dataset.selectedId='';
    const select=input.closest('.pp-sale-recipe-line')?.querySelector('.pp-sale-recipe');
    if(select)select.value='';
    ppRenderSaleRecipeSuggestionsPP(input);
    if(select)updateSaleRecipeLinePP(select);
}

/* Override ciblé : le select reste présent mais caché pour préserver tout le calcul existant. */
function addSaleRecipeLinePP(data={}){
    ppEnsureSalesQuickSearchStylesPP();
    const box=document.getElementById('ppSaleRecipeLines');if(!box)return;
    const selectedRecipe=recipesPP.find(item=>Number(item.id)===Number(data.recipeId));
    const row=document.createElement('div');row.className='pp-sale-recipe-line';
    row.style.cssText='display:grid;grid-template-columns:minmax(260px,2fr) minmax(110px,.7fr) minmax(130px,.8fr) minmax(130px,.8fr) 55px;gap:8px;align-items:end;border:1px solid #e5e7eb;border-radius:12px;padding:10px;margin-bottom:8px';
    row.innerHTML=`
      <div>
        <label>Plat / fiche technique</label>
        <div class="pp-sales-search-wrap">
          <input type="text" class="pp-sales-search-input pp-sale-recipe-search" autocomplete="off"
            placeholder="Rechercher une fiche technique…"
            value="${escapeHTML(selectedRecipe?.name||'')}"
            data-selected-id="${selectedRecipe?.id||''}"
            onfocus="ppOpenSalesSearchPP(this)"
            oninput="ppSaleRecipeTypingPP(this)"
            onkeydown="ppSalesSearchKeydownPP(event)">
          <select class="pp-sale-recipe pp-sales-search-native" onchange="updateSaleRecipeLinePP(this)">${saleRecipeOptionsPP(data.recipeId)}</select>
          <div class="pp-sales-search-menu"></div>
        </div>
      </div>
      <div><label>Quantité vendue</label><input class="pp-sale-recipe-qty" type="number" min="0.000001" step="0.000001" value="${Number(data.quantity||1)}" oninput="updateSaleRecipeLinePP(this)"></div>
      <div><label>Prix vente</label><input class="pp-sale-recipe-price" readonly></div>
      <div><label>Coût matière</label><input class="pp-sale-recipe-cost" readonly></div>
      <button type="button" class="btn danger" onclick="this.closest('.pp-sale-recipe-line').remove();updateSaleRecipesTotalsPP()">🗑️</button>`;
    box.appendChild(row);
    updateSaleRecipeLinePP(row.querySelector('.pp-sale-recipe'));
}

function ppDailyAssignmentItemsPP(){
    const recipes=recipesPP.map(recipe=>({
        value:`r:${recipe.id}`,
        name:String(recipe.name||''),
        type:'Fiche technique',
        extra:recipe.category||'',
        search:[recipe.name,recipe.category,recipe.description].join(' ')
    }));
    const stock=products.map(product=>({
        value:`p:${product.id}`,
        name:String(product.name||''),
        type:'Produit stock',
        extra:`${formatNumber(product.stock||0)} ${product.unit||''}`.trim(),
        search:[product.name,product.category,product.unit].join(' ')
    }));
    return [...recipes,...stock].sort((a,b)=>a.name.localeCompare(b.name,'fr'));
}

function ppDailyAssignmentLabelPP(match){
    if(match?.recipeId){
        const recipe=recipesPP.find(item=>Number(item.id)===Number(match.recipeId));
        return recipe?recipe.name:'';
    }
    if(match?.stockProductId){
        const product=products.find(item=>Number(item.id)===Number(match.stockProductId));
        return product?product.name:'';
    }
    return '';
}

function ppRenderDailyAssignmentSuggestionsPP(input){
    const wrap=input.closest('.pp-sales-search-wrap');
    const menu=wrap?.querySelector('.pp-sales-search-menu');
    if(!menu)return;
    const q=ppSalesSearchTextPP(input.value);
    const items=ppDailyAssignmentItemsPP()
        .filter(item=>!q||ppSalesSearchTextPP(item.search).includes(q))
        .slice(0,100);
    menu.innerHTML=`
      ${!q?`<button type="button" class="pp-sales-search-option" data-value="" onclick="ppChooseDailyAssignmentPP(this)">
        <strong>Non affecté</strong><small>Supprimer l’affectation actuelle</small>
      </button>`:''}
      ${items.map(item=>`
        <button type="button" class="pp-sales-search-option" data-value="${item.value}" onclick="ppChooseDailyAssignmentPP(this)">
          <strong>${escapeHTML(item.name)}</strong>
          <small>${escapeHTML(item.type)}${item.extra?` · ${escapeHTML(item.extra)}`:''}</small>
        </button>`).join('')}`;
    menu.classList.add('is-open');
}

function ppChooseDailyAssignmentPP(button){
    const wrap=button.closest('.pp-sales-search-wrap');
    const input=wrap?.querySelector('.pp-daily-assignment-search');
    const index=Number(input?.dataset.matchIndex);
    const value=String(button.dataset.value||'');
    if(!Number.isInteger(index)||!ppDailyScanMatches[index])return;
    if(input){
        if(value.startsWith('r:'))input.value=recipesPP.find(item=>Number(item.id)===Number(value.slice(2)))?.name||'';
        else if(value.startsWith('p:'))input.value=products.find(item=>Number(item.id)===Number(value.slice(2)))?.name||'';
        else input.value='';
    }
    wrap.querySelector('.pp-sales-search-menu')?.classList.remove('is-open');
    updateDailySalesAssignmentPP(index,value);
}

function ppDailyAssignmentTypingPP(input){
    ppRenderDailyAssignmentSuggestionsPP(input);
}

/* Dernier override : recherche rapide dans la vérification du scan de ventes. */
function renderDailyScanReviewPP(){
    ppEnsureSalesQuickSearchStylesPP();
    const box=document.getElementById('ppDailyScanReview');if(!box)return;
    if(!ppDailyScanMatches.length){
        box.innerHTML='<div class="scan-note">Aucune ligne de vente reconnue.</div>';
        const save=document.getElementById('ppDailyScanSaveBtn');if(save)save.disabled=true;return;
    }

    const matched=ppDailyScanMatches.filter(x=>x.matchType!=='unmatched').length;
    const unmatched=ppDailyScanMatches.length-matched;
    const sumTTC=ppDailyScanReportSummary?.grandTTC||ppDailyScanMatches.reduce((a,x)=>a+Number(x.totalTTC||0),0);

    box.innerHTML=`
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;margin:12px 0">
        <div class="stat-card" style="padding:12px"><small>Lignes détectées</small><strong style="display:block">${ppDailyScanMatches.length}</strong></div>
        <div class="stat-card" style="padding:12px"><small>Affectées</small><strong style="display:block">${matched}</strong></div>
        <div class="stat-card" style="padding:12px"><small>À vérifier</small><strong style="display:block">${unmatched}</strong></div>
        <div class="stat-card" style="padding:12px"><small>Net TTC rapport</small><strong style="display:block">${formatMoney(sumTTC)}</strong></div>
      </div>
      <div style="padding:10px 12px;background:#f8fafc;border-radius:10px;margin-bottom:12px">
        <strong>Principe :</strong> plats préparés → Fiche Technique ; boissons/produits finis → Produit fini / Stock direct.
        Le choix manuel est mémorisé pour les prochains scans.
      </div>
      <h3>Vérification avant enregistrement</h3>
      <div style="overflow:auto"><table style="width:100%;min-width:1100px">
      <thead><tr><th>Catégorie</th><th>Désignation rapport</th><th>Qté</th><th>Total TTC</th><th>Affectation</th><th>Confiance</th></tr></thead><tbody>
      ${ppDailyScanMatches.map((m,i)=>`<tr>
          <td>${escapeHTML(m.category||'-')}</td>
          <td><strong>${escapeHTML(m.rawName||m.sourceLine||'-')}</strong></td>
          <td><input type="number" min="0.000001" step="0.000001" value="${m.quantity}" onchange="ppDailyScanMatches[${i}].quantity=Number(this.value)"></td>
          <td>${formatMoney(m.totalTTC||0)}</td>
          <td style="min-width:310px">
            <div class="pp-sales-search-wrap">
              <input type="text" class="pp-sales-search-input pp-daily-assignment-search" autocomplete="off"
                placeholder="Rechercher une fiche ou un article…"
                value="${escapeHTML(ppDailyAssignmentLabelPP(m))}"
                data-match-index="${i}"
                onfocus="ppOpenSalesSearchPP(this)"
                oninput="ppDailyAssignmentTypingPP(this)"
                onkeydown="ppSalesSearchKeydownPP(event)">
              <div class="pp-sales-search-menu"></div>
            </div>
          </td>
          <td>${m.matchType==='unmatched'?'<span class="status danger">À vérifier</span>':`<span class="status success">${m.score>=100?'Mémorisé / validé':Math.round(m.score)+'%'}</span>`}</td>
        </tr>`).join('')}
      </tbody></table></div>
      ${ppDailyScanReportSummary?.paymentMethods?.length?`<div style="margin-top:12px"><strong>Paiements :</strong> ${ppDailyScanReportSummary.paymentMethods.map(p=>`${p.mode}: ${formatMoney(p.amount)}`).join(' / ')}</div>`:''}
      ${ppDailyScanReportSummary?.subtotalHT?`<div style="margin-top:6px"><strong>HT:</strong> ${formatMoney(ppDailyScanReportSummary.subtotalHT)} — <strong>TVA:</strong> ${formatMoney(ppDailyScanReportSummary.vat)} — <strong>TTC:</strong> ${formatMoney(ppDailyScanReportSummary.grandTTC)}</div>`:''}
    `;
    const save=document.getElementById('ppDailyScanSaveBtn');if(save)save.disabled=false;
}


